import type { MetadataRoute } from "next";
import { SITE_URL } from "@/lib/site";

export default function robots(): MetadataRoute.Robots {
  // `host` is intentionally omitted — the Host: directive is a Yandex
  // extension that Google / Bing ignore. Canonical origin preference
  // is already communicated via the per-page `<link rel="canonical">`
  // and the metadataBase in app/layout.tsx, so the Host: line was
  // just noise. Audit L-08.
  return {
    rules: [
      {
        userAgent: "*",
        allow: "/",
        // Admin lives behind a JWT-gated UI, but there's no point letting
        // crawlers index its login page or any in-flight admin URL.
        disallow: ["/admin", "/admin/"],
      },
    ],
    sitemap: `${SITE_URL}/sitemap.xml`,
  };
}

