import type { MetadataRoute } from "next";
import { getSeriesList, getStories, getTags } from "@/lib/api";
import { SITE_URL } from "@/lib/site";

// Revalidate hourly — keeps sitemap fresh without hammering the API.
export const revalidate = 3600;

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const [storiesRes, seriesRes, tags] = await Promise.all([
    getStories({ limit: 1000 }).catch(() => ({
      data: [],
      meta: { total: 0, page: 1, limit: 1000, totalPages: 0 },
    })),
    getSeriesList({ limit: 1000 }).catch(() => ({
      data: [],
      meta: { total: 0, page: 1, limit: 1000, totalPages: 0 },
    })),
    getTags().catch(() => []),
  ]);

  const now = new Date();

  const staticEntries: MetadataRoute.Sitemap = [
    {
      url: `${SITE_URL}/`,
      lastModified: now,
      changeFrequency: "daily",
      priority: 1,
    },
    {
      url: `${SITE_URL}/search`,
      lastModified: now,
      changeFrequency: "weekly",
      priority: 0.5,
    },
  ];

  const storyEntries: MetadataRoute.Sitemap = storiesRes.data.map((s) => ({
    url: `${SITE_URL}/story/${s.id}`,
    lastModified: s.publishedAt ? new Date(s.publishedAt) : now,
    changeFrequency: "monthly",
    priority: 0.8,
  }));

  // Series pages + every chapter that's been published. The series
  // detail already comes back with its chapters, so we don't need a
  // separate listing endpoint to enumerate chapter URLs.
  const seriesEntries: MetadataRoute.Sitemap = [];
  const chapterEntries: MetadataRoute.Sitemap = [];
  for (const series of seriesRes.data) {
    seriesEntries.push({
      url: `${SITE_URL}/series/${series.id}`,
      lastModified: now,
      changeFrequency: "weekly",
      priority: 0.7,
    });
    for (const chapter of series.chapters) {
      chapterEntries.push({
        url: `${SITE_URL}/chapter/${chapter.id}`,
        lastModified: chapter.publishedAt
          ? new Date(chapter.publishedAt)
          : now,
        changeFrequency: "monthly",
        priority: 0.6,
      });
    }
  }

  const tagEntries: MetadataRoute.Sitemap = tags.map((t) => ({
    url: `${SITE_URL}/tag/${t.slug}`,
    lastModified: now,
    changeFrequency: "weekly",
    priority: 0.4,
  }));

  return [
    ...staticEntries,
    ...storyEntries,
    ...seriesEntries,
    ...chapterEntries,
    ...tagEntries,
  ];
}

