import { headers } from "next/headers";

interface Props {
  data: Record<string, unknown> | Record<string, unknown>[];
}

/**
 * Server-rendered JSON-LD <script>. Single component for any
 * structured-data block — pages just hand it the schema object.
 * Renders nothing client-side; the script tag ships in the SSR HTML
 * so crawlers see it on first request.
 *
 * Async (server component) so it can read the per-request CSP nonce
 * set by proxy.ts. Without the nonce, the enforcing CSP would
 * reject this inline `<script>`. The nonce reads from the
 * `x-nonce` request header which proxy.ts injects.
 */
export default async function JsonLd({ data }: Props) {
  const nonce = (await headers()).get("x-nonce") ?? undefined;
  return (
    <script
      type="application/ld+json"
      nonce={nonce}
      // eslint-disable-next-line react/no-danger
      dangerouslySetInnerHTML={{
        __html: JSON.stringify(data).replace(/</g, "\\u003c"),
      }}
    />
  );
}

import type { Metadata, Viewport } from "next";
import Script from "next/script";
import JsonLd from "@/components/JsonLd";
import PublicGates from "@/components/PublicGates";
import { SITE_AUTHOR, SITE_DESCRIPTION, SITE_NAME, SITE_URL } from "@/lib/site";
import "./globals.css";

export const metadata: Metadata = {
  metadataBase: new URL(SITE_URL),
  title: {
    default: SITE_NAME,
    template: `%s — ${SITE_NAME}`,
  },
  description: SITE_DESCRIPTION,
  applicationName: SITE_NAME,
  authors: [{ name: SITE_AUTHOR.name, url: SITE_AUTHOR.url }],
  creator: SITE_AUTHOR.name,
  publisher: SITE_NAME,
  alternates: {
    canonical: "/",
    types: {
      "application/atom+xml": [{ url: "/feed.xml", title: SITE_NAME }],
    },
  },
  openGraph: {
    type: "website",
    siteName: SITE_NAME,
    title: SITE_NAME,
    description: SITE_DESCRIPTION,
    url: SITE_URL,
    // The default image is generated by app/opengraph-image.tsx and
    // resolved automatically by Next.js — per-page metadata can
    // override it without redefining the rest of this block.
  },
  twitter: {
    card: "summary_large_image",
    title: SITE_NAME,
    description: SITE_DESCRIPTION,
  },
  robots: {
    index: true,
    follow: true,
  },
};

// themeColor / colorScheme moved out of `metadata` and into a separate
// `viewport` export in Next.js 14+ — the old location is deprecated.
// The hex matches the resting --bg token in globals.css so the mobile
// browser chrome blends into the page rather than flashing a lighter
// default.
export const viewport: Viewport = {
  themeColor: "#0a0a0a",
  colorScheme: "dark",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    // suppressHydrationWarning on <html> covers the data-theme attribute the
    // boot script sets before React hydrates; suppressing on <body> handles
    // the Grammarly extension's own attribute injection.
    <html
      lang="en"
      className="dark h-full antialiased"
      data-theme="dark"
      suppressHydrationWarning
    >
      <body className="min-h-full flex flex-col" suppressHydrationWarning>
        {/*
          Boot script — applies the persisted theme + reading prefs to
          <html> before React hydrates so returning visitors don't see
          a flash of the default theme. Lives as a static file under
          /public/boot.js so React 19 doesn't flag a <script> tag
          inside the component tree (an inline child trips
          "Encountered a script tag while rendering React component"
          even when wrapped in next/script).
        */}
        {/* Skip-to-content link — first focusable element in the
            DOM so keyboard / screen-reader users can bypass the
            site header. Targets the page's `<main id="main">`
            which every route renders. The element is visually
            parked off-screen via `.skip-link` in globals.css and
            slides into the top-left when focused. */}
        <a href="#main" className="skip-link">
          Skip to content
        </a>
        <Script
          id="lucifer-boot-prefs"
          src="/boot.js"
          strategy="beforeInteractive"
        />
        <JsonLd
          data={{
            "@context": "https://schema.org",
            "@type": "WebSite",
            name: SITE_NAME,
            description: SITE_DESCRIPTION,
            url: SITE_URL,
            author: {
              "@type": "Person",
              name: SITE_AUTHOR.name,
              url: SITE_AUTHOR.url,
            },
            publisher: {
              "@type": "Organization",
              name: SITE_NAME,
              url: SITE_URL,
            },
          }}
        />
        {children}
        <PublicGates />
      </body>
    </html>
  );
}

// Single source of truth for the site's canonical URL. Used by
// metadata, sitemap, feed, and any link that needs to be absolute.
//
// Override per-environment via NEXT_PUBLIC_SITE_URL — e.g. set it to
// the production domain in your hosting provider's env settings.

export const SITE_URL = (
  process.env.NEXT_PUBLIC_SITE_URL ?? "http://localhost:3000"
).replace(/\/+$/, "");

export const SITE_NAME = "Lucifer's Diary";

export const SITE_DESCRIPTION =
  "A dark literary diary — long-form fiction read in the dark.";

// Author identity for JSON-LD `author` / OG `article:author` fields.
// Pseudonym only — matches the diary's first-person narrator persona
// and keeps real identity out of the public schema. Change in this
// one place to update every schema + meta tag site-wide.
export const SITE_AUTHOR = {
  name: "Lucifer",
  url: SITE_URL,
} as const;

