"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  buildShareTargets,
  QUOTE_MAX_CHARS,
  truncateQuote,
  type ShareTarget,
} from "@/lib/share";
import styles from "./QuoteShare.module.css";

interface Props {
  /** Title of the work being quoted — used in the attribution line. */
  title: string;
  /**
   * Absolute URL of the page hosting the passage. We do NOT read
   * `window.location` ourselves so the caller can supply a canonical
   * URL (no `?page=2` querystring noise in shared links).
   */
  url: string;
  /**
   * Ref to the element that wraps the readable content. Selections
   * outside this element (e.g. site header, footer) are ignored so
   * the popover doesn't appear when the user is just selecting a
   * heading or a nav label.
   */
  containerRef: React.RefObject<HTMLElement | null>;
}

interface SelectionState {
  text: string;
  truncated: boolean;
  /** Selection bounding rect in viewport coordinates. */
  rect: DOMRect;
}

/** Minimum characters in a selection before the popover appears. */
const MIN_SELECT_CHARS = 20;

/** Debounce after `selectionchange` before the popover renders. */
const SELECTION_DEBOUNCE_MS = 220;

/** Popover dimensions used for viewport-edge clamping. */
const POPOVER_WIDTH = 420;
const POPOVER_HEIGHT = 44;
const VIEWPORT_PADDING = 12;

/**
 * Floating share-the-quote popover. Listens for text selections
 * inside `containerRef`; when one settles longer than
 * `MIN_SELECT_CHARS`, renders a popover anchored above (or below)
 * the selection with X / Facebook / Bluesky / Copy buttons.
 *
 * Selection is ignored when:
 * - Empty / collapsed.
 * - Shorter than `MIN_SELECT_CHARS` (filters accidental drags).
 * - Outside `containerRef` (header, footer, nav, etc.).
 *
 * Dismissed on Escape, scroll, click outside the popover, or a
 * fresh selection landing outside the previous container.
 */
export default function QuoteShare({ title, url, containerRef }: Props) {
  const [selection, setSelection] = useState<SelectionState | null>(null);
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);
  const debounceRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const popoverRef = useRef<HTMLDivElement>(null);

  const dismiss = useCallback(() => {
    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
      debounceRef.current = null;
    }
    setSelection(null);
    setCopiedIndex(null);
  }, []);

  useEffect(() => {
    return () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
    };
  }, []);

  // Track selections. selectionchange fires on every cursor move
  // during a drag, so we debounce until the user pauses — otherwise
  // the popover would chase the cursor.
  useEffect(() => {
    const onSelectionChange = () => {
      if (debounceRef.current) clearTimeout(debounceRef.current);
      debounceRef.current = setTimeout(() => {
        const container = containerRef.current;
        if (!container) {
          setSelection(null);
          return;
        }
        const sel = window.getSelection();
        if (!sel || sel.isCollapsed || sel.rangeCount === 0) {
          setSelection(null);
          return;
        }
        const range = sel.getRangeAt(0);
        // Both ends of the selection must be inside the container.
        // Without this, dragging from a heading into the body, or
        // selecting across the site chrome, would trigger us.
        if (
          !container.contains(range.startContainer) ||
          !container.contains(range.endContainer)
        ) {
          setSelection(null);
          return;
        }
        const raw = sel.toString().trim();
        if (raw.length < MIN_SELECT_CHARS) {
          setSelection(null);
          return;
        }
        const { text, truncated } = truncateQuote(raw, QUOTE_MAX_CHARS);
        const rect = range.getBoundingClientRect();
        setSelection({ text, truncated, rect });
      }, SELECTION_DEBOUNCE_MS);
    };

    document.addEventListener("selectionchange", onSelectionChange);
    return () => {
      document.removeEventListener("selectionchange", onSelectionChange);
    };
  }, [containerRef]);

  // Dismissal triggers — Escape, scroll, click outside.
  useEffect(() => {
    if (!selection) return;

    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") dismiss();
    };
    const onScroll = () => dismiss();
    const onPointerDown = (e: PointerEvent) => {
      const target = e.target as Node | null;
      if (target && popoverRef.current?.contains(target)) return;
      // Wait one tick — if the pointer-down is part of starting a
      // new selection, the upcoming `selectionchange` will replace
      // our state with the new selection instead of clearing it.
      setTimeout(() => {
        const sel = window.getSelection();
        if (!sel || sel.isCollapsed) dismiss();
      }, 0);
    };

    window.addEventListener("keydown", onKey);
    window.addEventListener("scroll", onScroll, { passive: true });
    document.addEventListener("pointerdown", onPointerDown);
    return () => {
      window.removeEventListener("keydown", onKey);
      window.removeEventListener("scroll", onScroll);
      document.removeEventListener("pointerdown", onPointerDown);
    };
  }, [selection, dismiss]);

  if (!selection) return null;

  const position = computePosition(selection.rect);
  const targets = buildShareTargets({
    text: selection.text,
    title,
    url,
    truncated: selection.truncated,
  });

  const onShareClick = async (target: ShareTarget, index: number) => {
    if (target.action.kind === "url") {
      window.open(target.action.url, "_blank", "noopener,noreferrer");
      dismiss();
      return;
    }
    try {
      await navigator.clipboard.writeText(target.action.payload);
      setCopiedIndex(index);
      setTimeout(() => setCopiedIndex(null), 1200);
    } catch {
      // Clipboard write may fail (focus loss, permission). Fail
      // silently — the user can re-select and retry. No toast on
      // this site by design.
    }
  };

  return (
    <div
      ref={popoverRef}
      className={styles.popover}
      role="toolbar"
      aria-label="Share selected quote"
      style={{
        top: `${position.top}px`,
        left: `${position.left}px`,
        // Block pointer-down propagation so clicking the popover
        // doesn't dismiss it via the outside-click handler before
        // the click resolves.
        pointerEvents: "auto",
      }}
      onPointerDown={(e) => {
        e.stopPropagation();
      }}
    >
      {targets.map((target, i) => {
        const isCopy = target.action.kind === "copy";
        const showCopied = isCopy && copiedIndex === i;
        return (
          <button
            key={target.label}
            type="button"
            className={`${styles.button} ${
              showCopied ? styles.buttonCopied : ""
            }`}
            onClick={() => void onShareClick(target, i)}
          >
            {showCopied ? "Copied" : target.label}
          </button>
        );
      })}
    </div>
  );
}

/**
 * Pick a viewport-clamped {top, left} for the popover relative to
 * the selection rect. Prefers above-the-selection; falls below when
 * there isn't room (or on a tall selection that runs off the top).
 */
function computePosition(rect: DOMRect) {
  const vw = window.innerWidth;
  const vh = window.innerHeight;
  const spaceAbove = rect.top;
  const spaceBelow = vh - rect.bottom;

  // Horizontal: center on the selection, clamped to viewport.
  const desiredLeft = rect.left + rect.width / 2 - POPOVER_WIDTH / 2;
  const left = Math.max(
    VIEWPORT_PADDING,
    Math.min(desiredLeft, vw - POPOVER_WIDTH - VIEWPORT_PADDING),
  );

  // Vertical: above unless there's not enough room — then below.
  const above = spaceAbove >= POPOVER_HEIGHT + VIEWPORT_PADDING * 2;
  if (above) {
    return { top: rect.top - POPOVER_HEIGHT - 8, left };
  }
  if (spaceBelow >= POPOVER_HEIGHT + VIEWPORT_PADDING * 2) {
    return { top: rect.bottom + 8, left };
  }
  // Tight viewport — pin near the top of the visible area as a
  // last resort so the popover is still reachable.
  return { top: VIEWPORT_PADDING, left };
}

