22	/**
23	 * Truncate to <= max chars, breaking at the last word boundary
24	 * (or hard-cut if the next break is past 60% of max). Returns the
25	 * trimmed text and a flag so the caller can show "…".
26	 */
27	export function truncateQuote(text: string, max = QUOTE_MAX_CHARS) {
28	  const normalized = text.trim().replace(/\s+/g, " ");
29	  if (normalized.length <= max) {
30	    return { text: normalized, truncated: false };
31	  }
32	  const slice = normalized.slice(0, max);
33	  const lastSpace = slice.lastIndexOf(" ");
34	  const cut = lastSpace > max * 0.6 ? slice.slice(0, lastSpace) : slice;
35	  return { text: cut.trimEnd(), truncated: true };
36	}
37	
38	export interface ShareTarget {
39	  /** Display label */
40	  label: string;
41	  /** Either a URL to open (window.open) or a side-effect callback */
42	  action: { kind: "url"; url: string } | { kind: "copy"; payload: string };
43	}
44	
