46	  /** Already-truncated quote text */
47	  text: string;
48	  /** Title of the work being quoted (story/chapter title) */
49	  title: string;
50	  /** Absolute URL of the page hosting the quote */
51	  url: string;
52	  /** True if `text` was truncated from a longer selection */
53	  truncated: boolean;
54	}
55	
56	/**
57	 * Build the share-target list for a given selection. Centralized
58	 * here so QuoteShare.tsx can stay focused on UX.
59	 *
60	 * Targets:
61	 * - X (Twitter) — `twitter.com/intent/tweet`
62	 * - Facebook — `facebook.com/sharer/sharer.php`
63	 * - Bluesky — `bsky.app/intent/compose`
64	 * - Copy Quote — quote + attribution + URL into clipboard
65	 * - Copy Link-to-Passage — URL + Text Fragments hash for
66	 *   browser-native scroll-and-highlight on arrival
67	 */
68	export function buildShareTargets({
69	  text,
70	  title,
71	  url,
72	  truncated,
73	}: BuildShareTargetsInput): ShareTarget[] {
74	  const quote = truncated ? `${text}…` : text;
75	  const attribution = `“${quote}” — ${title}, ${SITE_NAME}`;
76	
77	  return [
78	    {
79	      label: "X",
80	      action: {
81	        kind: "url",
82	        url: `https://twitter.com/intent/tweet?text=${enc(attribution)}&url=${enc(url)}`,
83	      },
84	    },
85	    {
86	      label: "Facebook",
87	      action: {
88	        kind: "url",
89	        url: `https://www.facebook.com/sharer/sharer.php?u=${enc(url)}&quote=${enc(attribution)}`,
90	      },
91	    },
92	    {
93	      label: "Bluesky",
94	      action: {
95	        kind: "url",
96	        url: `https://bsky.app/intent/compose?text=${enc(`${attribution}\n\n${url}`)}`,
97	      },
98	    },
99	    {
100	      label: "Copy Quote",
101	      action: {
102	        kind: "copy",
103	        payload: `${attribution}\n${url}`,
104	      },
105	    },
106	    {
107	      label: "Copy Link to Passage",
108	      action: {
109	        kind: "copy",
110	        payload: buildTextFragmentUrl(url, text),
111	      },
112	    },
113	  ];
114	}
115	
116	/**
117	 * Build a Text Fragments URL — the `#:~:text=foo,bar` syntax that
118	 * Chromium browsers honor natively for "scroll to this passage and
119	 * highlight it." Firefox / Safari need the polyfill in
120	 * `components/TextFragmentScroller.tsx`.
121	 *
122	 * For short selections we just encode the whole thing. For longer
123	 * ones we encode the first 5 + last 5 words as a head/tail pair —
124	 * safer than the whole quote because:
125	 *   1. Encoded URLs over ~2000 chars get clipped by some clients.
126	 *   2. The head/tail form survives minor edits in the middle of the
127	 *      passage (Chromium will still match on the boundary words).
128	 */
129	export function buildTextFragmentUrl(baseUrl: string, text: string): string {
130	  const normalized = text.trim().replace(/\s+/g, " ");
131	  const words = normalized.split(" ");
132	  if (words.length <= 10) {
133	    return `${baseUrl}#:~:text=${enc(normalized)}`;
134	  }
135	  const head = words.slice(0, 5).join(" ");
136	  const tail = words.slice(-5).join(" ");
137	  return `${baseUrl}#:~:text=${enc(head)},${enc(tail)}`;
138	}
