/* Floating popover anchored to the reader's text selection. */

.popover {
  position: fixed;
  z-index: 90;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px;
  background: var(--bg-surface);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  box-shadow: 0 12px 28px -12px rgba(0, 0, 0, 0.65);
  font-family: var(--font-ui);
  /* Slight pop-in — the popover wants to feel responsive without
     stealing attention from the selection. */
  animation: quoteShareIn 140ms ease-out;
}

@keyframes quoteShareIn {
  from {
    opacity: 0;
    transform: translateY(2px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.button {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 10px;
  border-radius: var(--radius-pill);
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-muted);
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: var(--tracking-tag);
  text-transform: uppercase;
  cursor: pointer;
  white-space: nowrap;
  transition:
    color var(--transition-fast),
    border-color var(--transition-fast),
    background var(--transition-fast);
}
.button:hover {
  color: var(--text);
  border-color: var(--border-line-hover);
}
.button:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

/* "Copied" flash — the copy buttons swap to this for ~1.2s after
   a successful clipboard write so the user sees confirmation
   without a separate toast. */
.buttonCopied {
  color: var(--gold);
  border-color: var(--gold);
  background: var(--gold-dim);
}

.divider {
  width: 1px;
  height: 16px;
  background: var(--border-line);
  margin: 0 2px;
}

/* Brief amber flash on the passage when a visitor arrives via a
   Text Fragments URL (#:~:text=...) and the polyfill scrolls to
   it. Chromium handles its own highlight natively; this is the
   Firefox/Safari version. */
.fragmentFlash {
  animation: fragmentFlash 2400ms ease-out;
}

@keyframes fragmentFlash {
  0%, 30% {
    background: var(--gold-dim);
    box-shadow: 0 0 0 4px var(--gold-dim);
  }
  100% {
    background: transparent;
    box-shadow: 0 0 0 0 transparent;
  }
}

