// ============================================================
// Share helpers: turn a reader-selected passage into URLs for the
// big text-only social targets + clipboard copy variants.
// ============================================================
//
// Used by `components/QuoteShare.tsx`. Pure functions, no state, no
// network — every share is a pop-out window (or a clipboard write)
// owned by the user agent. No analytics; matches the site's
// privacy posture from the recent security-hardening commits.

import { SITE_NAME } from "@/lib/site";

const enc = encodeURIComponent;

/**
 * Cap for the quoted text. X posts max at 280 chars; we leave
 * ~40 for the attribution + URL slug. Quotes longer than this
 * are truncated on a word boundary and given an ellipsis.
 */
export const QUOTE_MAX_CHARS = 240;

/**
 * Truncate to <= max chars, breaking at the last word boundary
 * (or hard-cut if the next break is past 60% of max). Returns the
 * trimmed text and a flag so the caller can show "…".
 */
export function truncateQuote(text: string, max = QUOTE_MAX_CHARS) {
  const normalized = text.trim().replace(/\s+/g, " ");
  if (normalized.length <= max) {
    return { text: normalized, truncated: false };
  }
  const slice = normalized.slice(0, max);
  const lastSpace = slice.lastIndexOf(" ");
  const cut = lastSpace > max * 0.6 ? slice.slice(0, lastSpace) : slice;
  return { text: cut.trimEnd(), truncated: true };
}

/** Icon identifier — mapped to an SVG glyph in QuoteShare.tsx. */
export type ShareIconId = "x" | "facebook" | "bluesky" | "copy" | "link";

export interface ShareTarget {
  /** Display label */
  label: string;
  /** Which glyph to render alongside the label. */
  icon: ShareIconId;
  /** Either a URL to open (window.open) or a side-effect callback */
  action: { kind: "url"; url: string } | { kind: "copy"; payload: string };
}

export interface BuildShareTargetsInput {
  /** Already-truncated quote text */
  text: string;
  /** Title of the work being quoted (story/chapter title) */
  title: string;
  /** Absolute URL of the page hosting the quote */
  url: string;
  /** True if `text` was truncated from a longer selection */
  truncated: boolean;
}

/**
 * Build the share-target list for a given selection. Centralized
 * here so QuoteShare.tsx can stay focused on UX.
 *
 * Targets:
 * - X (Twitter) — `twitter.com/intent/tweet`
 * - Facebook — `facebook.com/sharer/sharer.php`
 * - Bluesky — `bsky.app/intent/compose`
 * - Copy Quote — quote + attribution + URL into clipboard
 * - Copy Link-to-Passage — URL + Text Fragments hash for
 *   browser-native scroll-and-highlight on arrival
 */
export function buildShareTargets({
  text,
  title,
  url,
  truncated,
}: BuildShareTargetsInput): ShareTarget[] {
  const quote = truncated ? `${text}…` : text;
  const attribution = `“${quote}” — ${title}, ${SITE_NAME}`;

  return [
    {
      label: "X",
      action: {
        kind: "url",
        url: `https://twitter.com/intent/tweet?text=${enc(attribution)}&url=${enc(url)}`,
      },
    },
    {
      label: "Facebook",
      action: {
        kind: "url",
        url: `https://www.facebook.com/sharer/sharer.php?u=${enc(url)}&quote=${enc(attribution)}`,
      },
    },
    {
      label: "Bluesky",
      action: {
        kind: "url",
        url: `https://bsky.app/intent/compose?text=${enc(`${attribution}\n\n${url}`)}`,
      },
    },
    {
      label: "Copy Quote",
      action: {
        kind: "copy",
        payload: `${attribution}\n${url}`,
      },
    },
    {
      label: "Copy Link to Passage",
      action: {
        kind: "copy",
        payload: buildTextFragmentUrl(url, text),
      },
    },
  ];
}

/**
 * Build a Text Fragments URL — the `#:~:text=foo,bar` syntax that
 * Chromium browsers honor natively for "scroll to this passage and
 * highlight it." Firefox / Safari need the polyfill in
 * `components/TextFragmentScroller.tsx`.
 *
 * For short selections we just encode the whole thing. For longer
 * ones we encode the first 5 + last 5 words as a head/tail pair —
 * safer than the whole quote because:
 *   1. Encoded URLs over ~2000 chars get clipped by some clients.
 *   2. The head/tail form survives minor edits in the middle of the
 *      passage (Chromium will still match on the boundary words).
 */
export function buildTextFragmentUrl(baseUrl: string, text: string): string {
  const normalized = text.trim().replace(/\s+/g, " ");
  const words = normalized.split(" ");
  if (words.length <= 10) {
    return `${baseUrl}#:~:text=${enc(normalized)}`;
  }
  const head = words.slice(0, 5).join(" ");
  const tail = words.slice(-5).join(" ");
  return `${baseUrl}#:~:text=${enc(head)},${enc(tail)}`;
}

