import { notFound } from "next/navigation";
import type { Metadata } from "next";
import CardGrid from "@/components/CardGrid";
import { SeriesCard } from "@/components/SeriesCard";
import SiteHeader from "@/components/SiteHeader";
import StoryCard from "@/components/StoryCard";
import { ApiError, getSeriesList, getStories, getTagBySlug } from "@/lib/api";
import { SITE_NAME, SITE_URL } from "@/lib/site";
import styles from "../../search/page.module.css";

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  try {
    const tag = await getTagBySlug(slug);
    return {
      title: `#${tag.name}`,
      description: `Stories tagged "${tag.name}" on ${SITE_NAME}.`,
      alternates: { canonical: `/tag/${tag.slug}` },
      openGraph: {
        title: `#${tag.name} — ${SITE_NAME}`,
        description: `Stories tagged "${tag.name}" on ${SITE_NAME}.`,
        url: `${SITE_URL}/tag/${tag.slug}`,
      },
    };
  } catch {
    return { title: "Tag not found" };
  }
}

export default async function TagPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;

  let tag;
  try {
    tag = await getTagBySlug(slug);
  } catch (e) {
    if (e instanceof ApiError && e.status === 404) notFound();
    throw e;
  }

  const [storiesRes, seriesRes] = await Promise.all([
    getStories({ tagIds: [tag.id], limit: 60 }).catch(() => ({
      data: [],
      meta: { total: 0, page: 1, limit: 60, totalPages: 0 },
    })),
    getSeriesList({ tagIds: [tag.id], limit: 60 }).catch(() => ({
      data: [],
      meta: { total: 0, page: 1, limit: 60, totalPages: 0 },
    })),
  ]);

  const stories = storiesRes.data;
  const seriesList = seriesRes.data;
  const totalCount = stories.length + seriesList.length;

  return (
    <>
      <SiteHeader />
      <div className={styles.page}>
        <div className={styles.intro}>
        <h2 className={styles.title}>
          <span style={{ color: "var(--gold)", fontStyle: "italic" }}>#</span>
          {tag.name}
          {tag.isAdult && (
            <span
              style={{
                marginLeft: 12,
                fontFamily: "var(--font-ui)",
                fontSize: 11,
                fontWeight: 600,
                letterSpacing: "0.12em",
                textTransform: "uppercase",
                color: "var(--like)",
                border: "1px solid var(--like)",
                padding: "2px 10px",
                borderRadius: "var(--radius-pill)",
                verticalAlign: "middle",
              }}
            >
              Adult
            </span>
          )}
        </h2>
        <p className={styles.subtitle}>
          {totalCount === 0
            ? "Nothing tagged with this yet."
            : `${totalCount} ${totalCount === 1 ? "piece" : "pieces"} tagged with this.`}
        </p>
      </div>

      <main id="main" tabIndex={-1} className={styles.main}>
        {totalCount === 0 ? (
          <p className={styles.empty}>Nothing yet.</p>
        ) : (
          <>
            {stories.length > 0 && (
              <section className={styles.section}>
                <h3 className={styles.sectionTitle}>
                  Stories &middot; {stories.length}
                </h3>
                <CardGrid>
                  {stories.map((s) => (
                    <StoryCard key={s.id} story={s} />
                  ))}
                </CardGrid>
              </section>
            )}
            {seriesList.length > 0 && (
              <section className={styles.section}>
                <h3 className={styles.sectionTitle}>
                  Series &middot; {seriesList.length}
                </h3>
                <CardGrid>
                  {seriesList.map((sr) => (
                    <SeriesCard key={sr.id} series={sr} />
                  ))}
                </CardGrid>
              </section>
            )}
          </>
        )}
        </main>
      </div>
    </>
  );
}

import type { Metadata, Viewport } from "next";
import Script from "next/script";
import JsonLd from "@/components/JsonLd";
import PublicGates from "@/components/PublicGates";
import { SITE_AUTHOR, SITE_DESCRIPTION, SITE_NAME, SITE_URL } from "@/lib/site";
import "./globals.css";

export const metadata: Metadata = {
  metadataBase: new URL(SITE_URL),
  title: {
    default: SITE_NAME,
    template: `%s — ${SITE_NAME}`,
  },
  description: SITE_DESCRIPTION,
  applicationName: SITE_NAME,
  authors: [{ name: SITE_AUTHOR.name, url: SITE_AUTHOR.url }],
  creator: SITE_AUTHOR.name,
  publisher: SITE_NAME,
  alternates: {
    canonical: "/",
    types: {
      "application/atom+xml": [{ url: "/feed.xml", title: SITE_NAME }],
    },
  },
  openGraph: {
    type: "website",
    siteName: SITE_NAME,
    title: SITE_NAME,
    description: SITE_DESCRIPTION,
    url: SITE_URL,
    // The default image is generated by app/opengraph-image.tsx and
    // resolved automatically by Next.js — per-page metadata can
    // override it without redefining the rest of this block.
  },
  twitter: {
    card: "summary_large_image",
    title: SITE_NAME,
    description: SITE_DESCRIPTION,
  },
  robots: {
    index: true,
    follow: true,
  },
};

// themeColor / colorScheme moved out of `metadata` and into a separate
// `viewport` export in Next.js 14+ — the old location is deprecated.
// The hex matches the resting --bg token in globals.css so the mobile
// browser chrome blends into the page rather than flashing a lighter
// default.
export const viewport: Viewport = {
  themeColor: "#0a0a0a",
  colorScheme: "dark",
};

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode;
}>) {
  return (
    // suppressHydrationWarning on <html> covers the data-theme attribute the
    // boot script sets before React hydrates; suppressing on <body> handles
    // the Grammarly extension's own attribute injection.
    <html
      lang="en"
      className="dark h-full antialiased"
      data-theme="dark"
      suppressHydrationWarning
    >
      <body className="min-h-full flex flex-col" suppressHydrationWarning>
        {/*
          Boot script — applies the persisted theme + reading prefs to
          <html> before React hydrates so returning visitors don't see
          a flash of the default theme. Lives as a static file under
          /public/boot.js so React 19 doesn't flag a <script> tag
          inside the component tree (an inline child trips
          "Encountered a script tag while rendering React component"
          even when wrapped in next/script).
        */}
        {/* Skip-to-content link — first focusable element in the
            DOM so keyboard / screen-reader users can bypass the
            site header. Targets the page's `<main id="main">`
            which every route renders. The element is visually
            parked off-screen via `.skip-link` in globals.css and
            slides into the top-left when focused. */}
        <a href="#main" className="skip-link">
          Skip to content
        </a>
        <Script
          id="lucifer-boot-prefs"
          src="/boot.js"
          strategy="beforeInteractive"
        />
        <JsonLd
          data={{
            "@context": "https://schema.org",
            "@type": "WebSite",
            name: SITE_NAME,
            description: SITE_DESCRIPTION,
            url: SITE_URL,
            author: {
              "@type": "Person",
              name: SITE_AUTHOR.name,
              url: SITE_AUTHOR.url,
            },
            publisher: {
              "@type": "Organization",
              name: SITE_NAME,
              url: SITE_URL,
            },
          }}
        />
        {children}
        <PublicGates />
      </body>
    </html>
  );
}

