import ContinueReadingRow from "@/components/ContinueReadingRow";
import ExpandableSection from "@/components/ExpandableSection";
import RecommendationsRow from "@/components/RecommendationsRow";
import ResumeReadingRow from "@/components/ResumeReadingRow";
import { ChapterCard, SeriesCard } from "@/components/SeriesCard";
import SiteHeader from "@/components/SiteHeader";
import StoryCard from "@/components/StoryCard";
import TagBar from "@/components/TagBar";
import {
  getAuthorsChoice,
  getLatestSeries,
  getLatestStories,
  getMostLiked,
  getMostRead,
  getTags,
} from "@/lib/api";
import type { HomepageCard as HomepageCardItem } from "@/types";
import styles from "./page.module.css";

export default async function HomePage() {
  // Concurrent fetches with graceful fallback if any one fails — the
  // homepage shouldn't 500 because Author's Choice is empty for example.
  const [tags, latestStories, latestSeries, mostLiked, mostRead, authorsChoice] =
    await Promise.all([
      getTags().catch(() => []),
      getLatestStories().catch(() => []),
      getLatestSeries().catch(() => []),
      getMostLiked().catch(() => []),
      getMostRead().catch(() => []),
      getAuthorsChoice().catch(() => []),
    ]);

  const sections = [
    {
      key: "latest-stories",
      title: "New Stories",
      items: latestStories,
      type: "story" as const,
    },
    {
      key: "latest-series",
      title: "New Series",
      items: latestSeries,
      type: "series" as const,
    },
    {
      key: "most-liked",
      title: "Most Liked",
      items: mostLiked,
      type: "homepage" as const,
    },
    {
      key: "most-read",
      title: "Most Read",
      items: mostRead,
      type: "homepage" as const,
    },
    {
      key: "authors-choice",
      title: "Author's Choice",
      items: authorsChoice,
      type: "homepage" as const,
    },
  ];

  const isEmpty = sections.every((s) => s.items.length === 0);

  return (
    <>
      <SiteHeader />
      <div className={styles.page}>
        <TagBar tags={tags} basePath="/search" />

      <main id="main" tabIndex={-1} className={styles.main}>
        {/* Scroll-position-driven resume row (backend-backed). Sits
            above the series-level continue row — readers most often
            want to jump back into the specific page they were on
            before they look at "what series was I in." Both rows
            self-hide when they have no data, so there's never an
            "empty section" gap on the homepage. */}
        <ResumeReadingRow />
        <ContinueReadingRow />

        {/* Personalized row — renders only for logged-in readers.
            Shows "For you" once they've got 3+ interactions, falls
            back to "Trending now" until then. Anonymous readers see
            nothing here, so the homepage looks identical to before
            this PR for them. */}
        <RecommendationsRow />

        {isEmpty ? (
          <p className={styles.empty}>No stories yet.</p>
        ) : (
          sections
            .filter((s) => s.items.length > 0)
            .map((section) => (
              // Below this threshold the row already shows everything,
              // so the See all toggle would be a no-op.
              <ExpandableSection
                key={section.key}
                title={section.title}
                expandable={section.items.length > 4}
              >
                {section.type === "story" &&
                  section.items.map((item) => (
                    <StoryCard key={item.id} story={item} />
                  ))}
                {section.type === "series" &&
                  section.items.map((item) => (
                    <SeriesCard key={item.id} series={item} />
                  ))}
                {section.type === "homepage" &&
                  section.items.map((item) => (
                    <HomepageItem key={item.id} item={item} />
                  ))}
              </ExpandableSection>
            ))
        )}
        </main>
      </div>
    </>
  );
}

function HomepageItem({ item }: { item: HomepageCardItem }) {
  if (item.type === "story") return <StoryCard story={item} />;
  return <ChapterCard chapter={item} />;
}

