import { notFound } from "next/navigation";
import type { Metadata } from "next";
import CardGrid from "@/components/CardGrid";
import { SeriesCard } from "@/components/SeriesCard";
import SiteHeader from "@/components/SiteHeader";
import StoryCard from "@/components/StoryCard";
import { ApiError, getSeriesList, getStories, getTagBySlug } from "@/lib/api";
import { SITE_NAME, SITE_URL } from "@/lib/site";
import styles from "../../search/page.module.css";

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  try {
    const tag = await getTagBySlug(slug);
    // Keyword-led title (runs through the `%s — Lucifer's Diary`
    // template) + a description that names the tag alongside the
    // genre terms readers actually search for.
    const description = `Read ${tag.name} erotica and adult sex stories on ${SITE_NAME} — long-form tales and slow-burn series for readers who like it dark.`;
    return {
      title: `${tag.name} Erotica & Sex Stories`,
      description,
      alternates: { canonical: `/tag/${tag.slug}` },
      openGraph: {
        title: `${tag.name} Erotica & Sex Stories — ${SITE_NAME}`,
        description,
        url: `${SITE_URL}/tag/${tag.slug}`,
      },
    };
  } catch {
    return { title: "Tag not found" };
  }
}

export default async function TagPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;

  let tag;
  try {
    tag = await getTagBySlug(slug);
  } catch (e) {
    if (e instanceof ApiError && e.status === 404) notFound();
    throw e;
  }

  const [storiesRes, seriesRes] = await Promise.all([
    getStories({ tagIds: [tag.id], limit: 60 }).catch(() => ({
      data: [],
      meta: { total: 0, page: 1, limit: 60, totalPages: 0 },
    })),
    getSeriesList({ tagIds: [tag.id], limit: 60 }).catch(() => ({
      data: [],
      meta: { total: 0, page: 1, limit: 60, totalPages: 0 },
    })),
  ]);

  const stories = storiesRes.data;
  const seriesList = seriesRes.data;
  const totalCount = stories.length + seriesList.length;

  return (
    <>
      <SiteHeader />
      <div className={styles.page}>
        <div className={styles.intro}>
        <h1 className={styles.title}>
          <span style={{ color: "var(--gold)", fontStyle: "italic" }}>#</span>
          {tag.name}
          {tag.isAdult && (
            <span
              style={{
                marginLeft: 12,
                fontFamily: "var(--font-ui)",
                fontSize: 11,
                fontWeight: 600,
                letterSpacing: "0.12em",
                textTransform: "uppercase",
                color: "var(--like)",
                border: "1px solid var(--like)",
                padding: "2px 10px",
                borderRadius: "var(--radius-pill)",
                verticalAlign: "middle",
              }}
            >
              Adult
            </span>
          )}
        </h2>
        <p className={styles.subtitle}>
          {totalCount === 0
            ? "Nothing tagged with this yet."
            : `${totalCount} ${totalCount === 1 ? "piece" : "pieces"} tagged with this.`}
        </p>
      </div>

      <main id="main" tabIndex={-1} className={styles.main}>
        {totalCount === 0 ? (
          <p className={styles.empty}>Nothing yet.</p>
        ) : (
          <>
            {stories.length > 0 && (
              <section className={styles.section}>
                <h3 className={styles.sectionTitle}>
                  Stories &middot; {stories.length}
                </h3>
                <CardGrid>
                  {stories.map((s) => (
                    <StoryCard key={s.id} story={s} />
                  ))}
                </CardGrid>
              </section>
            )}
            {seriesList.length > 0 && (
              <section className={styles.section}>
                <h3 className={styles.sectionTitle}>
                  Series &middot; {seriesList.length}
                </h3>
                <CardGrid>
                  {seriesList.map((sr) => (
                    <SeriesCard key={sr.id} series={sr} />
                  ))}
                </CardGrid>
              </section>
            )}
          </>
        )}
        </main>
      </div>
    </>
  );
}

