/* Marketing landing page (route: /). The story-browsing rails live
   at /browse — see app/browse/page.tsx. */

.landing {
  max-width: var(--container-home);
  margin: 0 auto;
  padding: 0 var(--pad-x) 96px;
  display: flex;
  flex-direction: column;
  gap: 72px;
}

/* ── Hero ──────────────────────────────────────────────────────── */
.hero {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 18px;
  max-width: 780px;
  padding: clamp(56px, 11vw, 128px) 0 16px;
}

.kicker {
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold);
  margin: 0;
}

.heroTitle {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(44px, 8.5vw, 92px);
  line-height: 1.02;
  letter-spacing: -0.01em;
  color: var(--text);
  margin: 0;
}

.heroAccent {
  font-style: italic;
  color: var(--text-muted);
}

.heroPitch {
  font-family: var(--font-reading);
  font-size: clamp(16px, 2.2vw, 20px);
  line-height: 1.6;
  color: var(--text-muted);
  max-width: 56ch;
  margin: 6px 0 0;
}

/* ── Call to action ────────────────────────────────────────────── */
.cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  margin-top: 14px;
  padding: 14px 38px;
  font-family: var(--font-ui);
  font-size: 14px;
