"use client";

import Link from "next/link";
import { useRef } from "react";
import BlockedTagsButton from "@/components/BlockedTagsButton";
import SearchBar from "@/components/SearchBar";
import SurpriseLink from "@/components/SurpriseLink";
import ThemeSwitcher from "@/components/ThemeSwitcher";
import UserMenu from "@/components/UserMenu";
import { gsap, prefersReducedMotion } from "@/lib/gsap";
import styles from "./SiteHeader.module.css";

const MOBILE_BREAKPOINT = 720;

// Tween durations for the search-bar morph. Open is a touch faster
// than close so the action icons' second-phase reveal feels like a
// settle rather than a snap.
const OPEN_DURATION = 0.42;
const CLOSE_BAR_DURATION = 0.38;
const CLOSE_ICONS_DURATION = 0.36;

// Per-icon translateX targets. The icons sit at orders 2, 3, 5, 6
// around the search bar (order 4) on mobile; these values land each
// icon's center at the row center where the search bar lives.
const ICON_TRANSLATE_X = [90, 45, -45, -90];

/**
 * Site-wide sticky header. On mobile, the four action icons (Surprise,
 * Hidden, Theme, User) morph into the search bar when its input
 * takes focus and morph back out when focus leaves. The morph is a
 * GSAP timeline rather than CSS transitions because:
 *   1. Forward and reverse get distinct easing — `power3.out` on
 *      open feels punchy; `power3.in` on close feels gentle.
 *   2. The close needs two distinct phases (bar shrinks first, icons
 *      morph back second) which CSS transition-delay couldn't reliably
 *      coordinate across browser engines.
 *   3. Smooth interruption: if the user blurs mid-open, GSAP picks
 *      up from current values via gsap.to() instead of snapping.
 */
export default function SiteHeader() {
  const innerRef = useRef<HTMLDivElement>(null);
  const centerRef = useRef<HTMLDivElement>(null);
  const rightRef = useRef<HTMLDivElement>(null);

  const animateMorph = (direction: "open" | "close") => {
    if (typeof window === "undefined") return;
    if (window.innerWidth > MOBILE_BREAKPOINT) return;
    if (prefersReducedMotion()) return;

    const center = centerRef.current;
    const inner = innerRef.current;
    const right = rightRef.current;
    if (!center || !inner || !right) return;

    const icons = Array.from(right.children) as HTMLElement[];

    // Kill any in-flight tweens on these targets so a rapid
    // focus/blur sequence doesn't pile up animations.
    gsap.killTweensOf([center, inner, ...icons]);

    if (direction === "open") {
      const tl = gsap.timeline();
      // Bar grows + column gap collapses simultaneously with the
      // icons' inward morph — feels like one continuous motion.
      tl.to(
        center,
        {
          width: "calc(100vw - 2 * var(--pad-x-mobile))",
          duration: OPEN_DURATION,
          ease: "power3.out",
        },
        0,
      );
      tl.to(inner, { columnGap: 0, duration: OPEN_DURATION, ease: "power3.out" }, 0);
      tl.to(
        icons,
        {
          // Translate each icon toward the bar's center. Outer pair
          // travels further than the inner pair.
          x: (i) => ICON_TRANSLATE_X[i] ?? 0,
          scale: 0.4,
          opacity: 0,
          maxWidth: 0,
          duration: OPEN_DURATION,
          ease: "power3.out",
        },
        0,
      );
    } else {
      const tl = gsap.timeline();
      // Phase 1: bar shrinks (icons stay collapsed in layout).
      tl.to(
        center,
        {
          width: "36px",
          duration: CLOSE_BAR_DURATION,
          ease: "power3.in",
        },
        0,
      );
      // Phase 2: icons morph back out from the bar's center to their
      // own positions. Starts when the bar's shrink completes so
      // there's no wrap-flicker from layout contention.
      tl.set(inner, { columnGap: 8 }, CLOSE_BAR_DURATION);
      tl.to(
        icons,
        {
          x: 0,
          scale: 1,
          opacity: 1,
          maxWidth: 300,
          duration: CLOSE_ICONS_DURATION,
          ease: "power3.out",
        },
        CLOSE_BAR_DURATION,
      );
    }
  };

  return (
    <header className={styles.header}>
      <div className={styles.inner} ref={innerRef}>
        <div className={styles.left}>
          <Link href="/" className={styles.logo}>
            Lucifer&rsquo;s Diary
          </Link>
        </div>
        <div className={styles.center} ref={centerRef}>
          <SearchBar
            onFocus={() => animateMorph("open")}
            onBlur={() => animateMorph("close")}
          />
        </div>
        <div className={styles.right} ref={rightRef}>
          <SurpriseLink />
          <BlockedTagsButton />
          <ThemeSwitcher />
          <UserMenu />
        </div>
      </div>
    </header>
  );
}

