import type { MetadataRoute } from "next";
import { getSeriesList, getStories, getTags } from "@/lib/api";
import { SITE_URL } from "@/lib/site";

// Revalidate hourly — keeps sitemap fresh without hammering the API.
export const revalidate = 3600;

export default async function sitemap(): Promise<MetadataRoute.Sitemap> {
  const [storiesRes, seriesRes, tags] = await Promise.all([
    getStories({ limit: 1000 }).catch(() => ({
      data: [],
      meta: { total: 0, page: 1, limit: 1000, totalPages: 0 },
    })),
    getSeriesList({ limit: 1000 }).catch(() => ({
      data: [],
      meta: { total: 0, page: 1, limit: 1000, totalPages: 0 },
    })),
    getTags().catch(() => []),
  ]);

  const now = new Date();

  const staticEntries: MetadataRoute.Sitemap = [
    {
      url: `${SITE_URL}/`,
      lastModified: now,
      changeFrequency: "daily",
      priority: 1,
    },
    {
      url: `${SITE_URL}/search`,
      lastModified: now,
      changeFrequency: "weekly",
      priority: 0.5,
    },
  ];

  const storyEntries: MetadataRoute.Sitemap = storiesRes.data.map((s) => ({
    url: `${SITE_URL}/story/${s.id}`,
    lastModified: s.publishedAt ? new Date(s.publishedAt) : now,
    changeFrequency: "monthly",
    priority: 0.8,
  }));

  // Series pages + every chapter that's been published. The series
  // detail already comes back with its chapters, so we don't need a
  // separate listing endpoint to enumerate chapter URLs.
  const seriesEntries: MetadataRoute.Sitemap = [];
  const chapterEntries: MetadataRoute.Sitemap = [];
  for (const series of seriesRes.data) {
    seriesEntries.push({
      url: `${SITE_URL}/series/${series.id}`,
      lastModified: now,
      changeFrequency: "weekly",
      priority: 0.7,
    });
    for (const chapter of series.chapters) {
      chapterEntries.push({
        url: `${SITE_URL}/chapter/${chapter.id}`,
        lastModified: chapter.publishedAt
          ? new Date(chapter.publishedAt)
          : now,
        changeFrequency: "monthly",
        priority: 0.6,
      });
    }
  }

  const tagEntries: MetadataRoute.Sitemap = tags.map((t) => ({
    url: `${SITE_URL}/tag/${t.slug}`,
    lastModified: now,
    changeFrequency: "weekly",
    priority: 0.4,
  }));

  return [
    ...staticEntries,
    ...storyEntries,
    ...seriesEntries,
    ...chapterEntries,
    ...tagEntries,
  ];
}

"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import DashboardList from "@/components/DashboardList";
import SiteHeader from "@/components/SiteHeader";
import { Button } from "@/components/ui/button";
import { getSessionToken } from "@/lib/session";
import SettingsPanel from "./_components/SettingsPanel";
import {
  getMyFollows,
  getMyLikes,
  getMySaves,
  logout,
  markFollowsSeen,
  useAuth,
  type FollowedSeries,
  type LikedItem,
  type SavedItem,
} from "@/lib/userAuth";
import styles from "./page.module.css";

type Tab = "dashboard" | "settings";

const dateFmt = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
});

/**
 * Account home. Two tabs:
 *  - Dashboard — saved stories + liked stories. Followed series will
 *    join them in a follow-up PR.
 *  - Settings — username / lastActive / deletion period read-only
 *    today; password change + email sync land in PR E.
 */
export default function ProfilePage() {
  const router = useRouter();
  const auth = useAuth();
  const [tab, setTab] = useState<Tab>("dashboard");
  const [signingOut, setSigningOut] = useState(false);

  if (auth.status === "loading") {
    return (
      <div className={styles.page}>
        <SiteHeader />
        <main id="main" tabIndex={-1} className={styles.main}>
          <p className={styles.loading}>Loading…</p>
        </main>
      </div>
    );
  }

  if (auth.status === "anonymous") {
    return (
      <div className={styles.page}>
        <SiteHeader />
        <main id="main" tabIndex={-1} className={styles.main}>
          <h1 className={styles.title}>Profile</h1>
          <p className={styles.subtitle}>
            You&rsquo;re not signed in. <Link href="/login">Sign in</Link>{" "}
            or <Link href="/signup">create an account</Link>.
          </p>
        </main>
      </div>
    );
  }

  const onLogout = async () => {
    if (signingOut) return;
    setSigningOut(true);
    try {
      await logout();
    } catch {
      // ignore — we'll clear local state and refresh either way
    }
    router.push("/");
    router.refresh();
  };

  const { user } = auth;

  return (
    <div className={styles.page}>
      <SiteHeader />
      <main id="main" tabIndex={-1} className={styles.main}>
        <header className={styles.header}>
          <div>
            <h1 className={styles.title}>{user.username}</h1>
            <p className={styles.metaLine}>
              Joined {dateFmt.format(new Date(user.createdAt))}
            </p>
          </div>
          <Button
            variant="ghost"
            onClick={() => void onLogout()}
            disabled={signingOut}
          >
            {signingOut ? "Signing out…" : "Sign out"}
          </Button>
        </header>

        <div className={styles.tabs} role="tablist">
          <button
            type="button"
            role="tab"
            aria-selected={tab === "dashboard"}
            onClick={() => setTab("dashboard")}
            className={`${styles.tab} ${tab === "dashboard" ? styles.tabActive : ""}`}
          >
            Dashboard
          </button>
          <button
            type="button"
            role="tab"
            aria-selected={tab === "settings"}
            onClick={() => setTab("settings")}
            className={`${styles.tab} ${tab === "settings" ? styles.tabActive : ""}`}
          >
            Settings
          </button>
        </div>

        {tab === "dashboard" ? (
          <DashboardPanel />
        ) : (
          <SettingsPanel user={user} onRefresh={auth.refresh} />
        )}
      </main>
    </div>
  );
}

// ── Dashboard ──────────────────────────────────────────────────────

// Per-resource state: data is the loaded array (null while pending);
// error is the load failure message for THIS resource only. Previous
// version had one shared error that nuked the whole panel when any
// single fetch failed — saved + liked might be perfectly loadable
// even when, say, /follows is down.
interface Resource<T> {
  data: T[] | null;
  error: string | null;
}

const initialResource: Resource<never> = { data: null, error: null };

function errorMessage(reason: unknown, fallback: string): string {
  return reason instanceof Error ? reason.message : fallback;
}

function DashboardPanel() {
  const [saved, setSaved] = useState<Resource<SavedItem>>(initialResource);
  const [liked, setLiked] = useState<Resource<LikedItem>>(initialResource);
  const [followed, setFollowed] =
    useState<Resource<FollowedSeries>>(initialResource);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      const sessionToken = getSessionToken();
      // allSettled instead of all — one rejection no longer aborts
      // the entire batch. Each section's data/error is set
      // independently from its own settled result.
      const [savedR, likedR, followedR] = await Promise.allSettled([
        getMySaves(),
        getMyLikes(sessionToken),
        getMyFollows(),
      ]);
      if (cancelled) return;

      setSaved(
        savedR.status === "fulfilled"
          ? { data: savedR.value, error: null }
          : { data: null, error: errorMessage(savedR.reason, "Couldn't load saves") },
      );
      setLiked(
        likedR.status === "fulfilled"
          ? { data: likedR.value, error: null }
          : { data: null, error: errorMessage(likedR.reason, "Couldn't load likes") },
      );
      setFollowed(
        followedR.status === "fulfilled"
          ? { data: followedR.value, error: null }
          : { data: null, error: errorMessage(followedR.reason, "Couldn't load follows") },
      );

      // Now that any unread badges are visible, mark them seen.
      // Fire-and-forget — failure is harmless and we don't care if
      // markFollowsSeen lands on a stale snapshot.
      if (
        followedR.status === "fulfilled" &&
        followedR.value.some((row) => row.unreadCount > 0)
      ) {
        void markFollowsSeen().catch(() => {});
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  return (
    <section className={styles.tabPanel}>
      <Section title="Saved" count={saved.data?.length ?? 0}>
        {saved.error ? (
          <p className={styles.empty}>{saved.error}</p>
        ) : saved.data === null ? (
          <p className={styles.empty}>Loading…</p>
        ) : (
          <DashboardList
            items={saved.data}
            timestampFor={(item) =>
              `Saved ${dateFmt.format(new Date(item.savedAt))}`
            }
            empty="Nothing saved yet. Bookmark a story or chapter from its page."
          />
        )}
      </Section>

      <Section title="Liked" count={liked.data?.length ?? 0}>
        {liked.error ? (
          <p className={styles.empty}>{liked.error}</p>
        ) : liked.data === null ? (
          <p className={styles.empty}>Loading…</p>
        ) : (
          <DashboardList
            items={liked.data}
            timestampFor={(item) =>
              `Liked ${dateFmt.format(new Date(item.likedAt))}`
            }
            empty="Nothing liked yet."
          />
        )}
      </Section>

      <Section title="Followed series" count={followed.data?.length ?? 0}>
        {followed.error ? (
          <p className={styles.empty}>{followed.error}</p>
        ) : followed.data === null ? (
          <p className={styles.empty}>Loading…</p>
        ) : (
          <FollowedList items={followed.data} />
        )}
      </Section>
    </section>
  );
}

function FollowedList({ items }: { items: FollowedSeries[] }) {
  if (items.length === 0) {
    return (
      <p className={styles.empty}>
        Not following anything yet. The Follow button on a series page
        adds it here.
      </p>
    );
  }
  return (
    <ul className={styles.followList}>
      {items.map((s) => (
        <li key={s.id} className={styles.followRow}>
          <Link href={`/series/${s.id}`} className={styles.followLink}>
            <div className={styles.followHead}>
              <span className={styles.kind}>
                Series · {statusLabel(s.status)}
              </span>
              <span className={styles.followMeta}>
                {s.chapterCount}{" "}
                {s.chapterCount === 1 ? "chapter" : "chapters"}
              </span>
            </div>
            <h3 className={styles.followTitle}>
              {s.title}
              {s.unreadCount > 0 && (
                <span className={styles.unreadBadge}>
                  {s.unreadCount} new
                </span>
              )}
            </h3>
            {s.latestPublishedAt && (
              <p className={styles.followLatest}>
                Latest chapter{" "}
                {dateFmt.format(new Date(s.latestPublishedAt))}
              </p>
            )}
          </Link>
        </li>
      ))}
    </ul>
  );
}

function statusLabel(status: FollowedSeries["status"]) {
  if (status === "COMPLETE") return "Complete";
  if (status === "HIATUS") return "On hiatus";
  return "Ongoing";
}

function Section({
  title,
  count,
  children,
}: {
  title: string;
  count: number;
  children: React.ReactNode;
}) {
  return (
    <div className={styles.section}>
      <header className={styles.sectionHeader}>
        <h2 className={styles.sectionTitle}>{title}</h2>
        <span className={styles.sectionCount}>{count}</span>
      </header>
      {children}
    </div>
  );
}

