"use client";

import { useRouter } from "next/navigation";
import { useEffect, useMemo, useRef, useState } from "react";
import { getSeriesList, getStories, getTags } from "@/lib/api";
import { pickSurprise } from "@/lib/surprise";
import type {
  SeriesCard as SeriesCardType,
  StoryCard as StoryCardType,
  Tag,
} from "@/types";
import styles from "./CommandPalette.module.css";

type Item =
  | { kind: "story"; id: string; title: string; href: string }
  | { kind: "series"; id: string; title: string; href: string }
  | {
      kind: "chapter";
      id: string;
      title: string;
      seriesTitle: string;
      href: string;
    }
  | { kind: "tag"; id: string; name: string; isAdult: boolean; href: string }
  | { kind: "action"; id: string; label: string; run: () => void };

interface CacheData {
  stories: StoryCardType[];
  series: SeriesCardType[];
  tags: Tag[];
}

export default function CommandPalette() {
  const router = useRouter();
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const [activeIndex, setActiveIndex] = useState(0);
  const [data, setData] = useState<CacheData | null>(null);
  const [loading, setLoading] = useState(false);
  const inputRef = useRef<HTMLInputElement>(null);

  // Open / close via Cmd+K (or Ctrl+K), Esc to close. Single global
  // listener registered once. The previous version had `open` in the
  // deps array and inside the Escape branch — re-registering on each
  // toggle plus the captured `open` value meant the brief gap between
  // setOpen and effect re-run could see a stale flag. Now: Cmd+K uses
  // functional setOpen (no capture needed) and Escape unconditionally
  // setOpen(false) (a no-op when already closed). Both safe with
  // stale state.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const isOpener =
        (e.metaKey || e.ctrlKey) && e.key.toLowerCase() === "k";
      if (isOpener) {
        e.preventDefault();
        setOpen((o) => !o);
        return;
      }
      if (e.key === "Escape") {
        setOpen(false);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  // Fetch data the first time the palette opens. Subsequent opens reuse
  // the cached lists since the homepage signal already revalidates
  // every couple of minutes.
  useEffect(() => {
    if (!open || data || loading) return;
    setLoading(true);
    void (async () => {
      try {
        const [storiesRes, seriesRes, tags] = await Promise.all([
          getStories({ limit: 500 }).catch(() => ({
            data: [] as StoryCardType[],
            meta: { total: 0, page: 1, limit: 500, totalPages: 0 },
          })),
          getSeriesList({ limit: 500 }).catch(() => ({
            data: [] as SeriesCardType[],
            meta: { total: 0, page: 1, limit: 500, totalPages: 0 },
          })),
          getTags().catch(() => [] as Tag[]),
        ]);
        setData({
          stories: storiesRes.data,
          series: seriesRes.data,
          tags,
        });
      } finally {
        setLoading(false);
      }
    })();
  }, [open, data, loading]);

  // Focus the input on every open.
  useEffect(() => {
    if (!open) return;
    requestAnimationFrame(() => inputRef.current?.focus());
  }, [open]);

  // Reset query + selection when reopening so a stale "before" search
  // doesn't bleed into the next session.
  useEffect(() => {
    if (open) {
      setQuery("");
      setActiveIndex(0);
    }
  }, [open]);

  const items = useMemo<Item[]>(() => {
    const out: Item[] = [];
    const q = query.trim().toLowerCase();
    const matches = (s: string) =>
      q === "" ? true : s.toLowerCase().includes(q);

    // Static actions first — they always show.
    out.push({
      kind: "action",
      id: "surprise",
      label: "Surprise me — open a random chapter",
      run: async () => {
        const pick = await pickSurprise();
        router.push(pick.href);
      },
    });
    out.push({
      kind: "action",
      id: "home",
      label: "Go to homepage",
      run: () => router.push("/"),
    });
    out.push({
      kind: "action",
      id: "search",
      label: "Open search",
      run: () => router.push("/search"),
    });

    if (data) {
      for (const s of data.stories) {
        if (!matches(s.title)) continue;
        out.push({
          kind: "story",
          id: s.id,
          title: s.title,
          href: `/story/${s.id}`,
        });
      }
      for (const sr of data.series) {
        if (matches(sr.title)) {
          out.push({
            kind: "series",
            id: sr.id,
            title: sr.title,
            href: `/series/${sr.id}`,
          });
        }
        for (const ch of sr.chapters) {
          if (matches(ch.title) || matches(sr.title)) {
            out.push({
              kind: "chapter",
              id: ch.id,
              title: ch.title,
              seriesTitle: sr.title,
              href: `/chapter/${ch.id}`,
            });
          }
        }
      }
      for (const t of data.tags) {
        if (matches(t.name)) {
          out.push({
            kind: "tag",
            id: t.id,
            name: t.name,
            isAdult: t.isAdult,
            href: `/search?tagIds=${encodeURIComponent(t.id)}`,
          });
        }
      }
    }
    return out;
  }, [query, data, router]);

  // Keep the active row in range when the result list shrinks.
  useEffect(() => {
    if (activeIndex >= items.length) setActiveIndex(0);
  }, [items, activeIndex]);

  const run = async (item: Item) => {
    setOpen(false);
    if (item.kind === "action") {
      await item.run();
    } else {
      router.push(item.href);
    }
  };

  const onKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "ArrowDown") {
      e.preventDefault();
      setActiveIndex((i) => Math.min(i + 1, items.length - 1));
    } else if (e.key === "ArrowUp") {
      e.preventDefault();
      setActiveIndex((i) => Math.max(i - 1, 0));
    } else if (e.key === "Enter") {
      e.preventDefault();
      const target = items[activeIndex];
      if (target) void run(target);
    }
  };

  if (!open) return null;

  return (
    <div
      className={styles.backdrop}
      onClick={() => setOpen(false)}
      role="dialog"
      aria-modal="true"
      aria-label="Command palette"
    >
      <div
        className={styles.panel}
        onClick={(e) => e.stopPropagation()}
        onKeyDown={onKeyDown}
      >
        <div className={styles.inputRow}>
          <SearchGlyph />
          <input
            ref={inputRef}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search stories, series, chapters, tags…"
            className={styles.input}
            aria-label="Command palette search"
          />
          <kbd className={styles.kbd}>Esc</kbd>
        </div>

        <ul className={styles.list} role="listbox">
          {items.length === 0 && (
            <li className={styles.empty}>
              {loading ? "Loading…" : "Nothing matches."}
            </li>
          )}
          {items.map((item, i) => (
            <li key={`${item.kind}-${item.id ?? (item as { name?: string }).name}`}>
              <button
                type="button"
                role="option"
                aria-selected={i === activeIndex}
                onMouseEnter={() => setActiveIndex(i)}
                onClick={() => void run(item)}
                className={`${styles.row} ${
                  i === activeIndex ? styles.rowActive : ""
                }`}
              >
                <span className={styles.kind}>{labelFor(item)}</span>
                <span className={styles.title}>{primaryFor(item)}</span>
                <span className={styles.subtitle}>{secondaryFor(item)}</span>
              </button>
            </li>
          ))}
        </ul>

        <div className={styles.footer}>
          <span>
            <kbd className={styles.kbd}>↑</kbd>
            <kbd className={styles.kbd}>↓</kbd>
            navigate
          </span>
          <span>
            <kbd className={styles.kbd}>↵</kbd>
            open
          </span>
          <span>
            <kbd className={styles.kbd}>Esc</kbd>
            close
          </span>
        </div>
      </div>
    </div>
  );
}

function labelFor(item: Item): string {
  switch (item.kind) {
    case "story":
      return "Story";
    case "series":
      return "Series";
    case "chapter":
      return "Chapter";
    case "tag":
      return item.isAdult ? "Tag · adult" : "Tag";
    case "action":
      return "Action";
  }
}

function primaryFor(item: Item): string {
  switch (item.kind) {
    case "story":
    case "series":
    case "chapter":
      return item.title;
    case "tag":
      return item.name;
    case "action":
      return item.label;
  }
}

function secondaryFor(item: Item): string {
  switch (item.kind) {
    case "chapter":
      return item.seriesTitle;
    default:
      return "";
  }
}

function SearchGlyph() {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.75"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      className={styles.searchGlyph}
      suppressHydrationWarning
    >
      <circle cx="11" cy="11" r="7" />
      <path d="m20 20-3.5-3.5" />
    </svg>
  );
}

