"use client";

import { usePathname } from "next/navigation";
import AgeGate from "./AgeGate";
import BlockedTagsApplier from "./BlockedTagsApplier";
import CommandPalette from "./CommandPalette";

/**
 * Wraps the AgeGate, the global Cmd+K command palette, and the
 * BlockedTagsApplier so they only render for the public site. The
 * admin panel sits behind login and has its own navigation, and the
 * author shouldn't have their own content hidden.
 */
export default function PublicGates() {
  const pathname = usePathname();
  if (pathname?.startsWith("/admin")) return null;
  return (
    <>
      <AgeGate />
      <CommandPalette />
      <BlockedTagsApplier />
    </>
  );
}

