3	import { useEffect, useState } from "react";
4	import styles from "./AgeGate.module.css";
5	
6	const STORAGE_KEY = "lucifer_age_confirmed";
7	
8	/**
9	 * First-visit age gate. Persists "yes" in localStorage so subsequent
10	 * visits skip the modal entirely. "No" sends the user away.
11	 *
12	 * Renders nothing on the server; on the client, mounts hidden until
13	 * the localStorage check finishes — that prevents the gate from
14	 * flashing for returning visitors.
15	 */
16	export default function AgeGate() {
17	  const [state, setState] = useState<"checking" | "show" | "hide" | "leaving">(
18	    "checking",
19	  );
20	
21	  useEffect(() => {
22	    // localStorage can throw — disabled in private/incognito mode on
23	    // some browsers, or hit a quota error in extreme cases. Treat
24	    // any failure as "not confirmed" so the gate still appears
25	    // rather than crashing the component out.
26	    let ok = false;
27	    try {
28	      ok = window.localStorage.getItem(STORAGE_KEY) === "1";
29	    } catch {
30	      // ignored — fall through with ok=false
31	    }
32	    setState(ok ? "hide" : "show");
33	  }, []);
34	
35	  if (state === "checking" || state === "hide") return null;
36	
37	  const confirm = () => {
38	    try {
39	      window.localStorage.setItem(STORAGE_KEY, "1");
40	    } catch {
41	      // localStorage may be disabled — still let them through.
42	    }
43	    setState("hide");
44	  };
45	
46	  const decline = () => {
47	    setState("leaving");
48	    setTimeout(() => {
49	      try {
50	        if (window.history.length > 1) {
51	          window.history.back();
52	          return;
53	        }
54	      } catch {
55	        // ignored
56	      }
57	      try {
58	        window.location.replace("about:blank");
59	      } catch {
60	        // ignored
61	      }
62	    }, 1200);
63	  };
64	
65	  return (
66	    <div
67	      role="dialog"
68	      aria-modal="true"
69	      aria-labelledby="age-gate-title"
70	      className={styles.overlay}
71	    >
72	      <div className={styles.card}>
73	        <div className={styles.mark}>Lucifer&rsquo;s Diary</div>
74	
75	        <p className={styles.notice}>Notice</p>
76	
77	        <h2 id="age-gate-title" className={styles.title}>
78	          This volume contains adult writing.
79	        </h2>
80	
81	        <p className={styles.body}>
82	          Some stories here include explicit themes intended for readers aged
83	          eighteen and over. If you are not yet 18, please leave.
84	        </p>
85	
86	        {state === "show" ? (
87	          <div className={styles.buttons}>
88	            <button
89	              type="button"
90	              onClick={confirm}
91	              className={styles.confirmBtn}
92	            >
93	              Yes, I am 18 or older
94	            </button>
95	            <button
96	              type="button"
97	              onClick={decline}
98	              className={styles.declineBtn}
99	            >
100	              No, I am not
101	            </button>
102	          </div>
103	        ) : (
104	          <div className={styles.leaving}>Closing the volume…</div>
105	        )}
106	
107	        <div className={styles.fineprint}>
108	          By entering you confirm you meet the age requirement in your
109	          jurisdiction.
110	        </div>
111	      </div>
112	    </div>
113	  );
