"use client";

import { useEffect, useState } from "react";
import styles from "./AgeGate.module.css";

const STORAGE_KEY = "lucifer_age_confirmed";

/**
 * First-visit age gate. Persists "yes" in localStorage so subsequent
 * visits skip the modal entirely. "No" sends the user away.
 *
 * Renders nothing on the server; on the client, mounts hidden until
 * the localStorage check finishes — that prevents the gate from
 * flashing for returning visitors.
 */
export default function AgeGate() {
  const [state, setState] = useState<"checking" | "show" | "hide" | "leaving">(
    "checking",
  );

  useEffect(() => {
    // localStorage can throw — disabled in private/incognito mode on
    // some browsers, or hit a quota error in extreme cases. Treat
    // any failure as "not confirmed" so the gate still appears
    // rather than crashing the component out.
    let ok = false;
    try {
      ok = window.localStorage.getItem(STORAGE_KEY) === "1";
    } catch {
      // ignored — fall through with ok=false
    }
    setState(ok ? "hide" : "show");
  }, []);

  if (state === "checking" || state === "hide") return null;

  const confirm = () => {
    try {
      window.localStorage.setItem(STORAGE_KEY, "1");
    } catch {
      // localStorage may be disabled — still let them through.
    }
    setState("hide");
  };

  const decline = () => {
    setState("leaving");
    setTimeout(() => {
      try {
        if (window.history.length > 1) {
          window.history.back();
          return;
        }
      } catch {
        // ignored
      }
      try {
        window.location.replace("about:blank");
      } catch {
        // ignored
      }
    }, 1200);
  };

  return (
    <div
      role="dialog"
      aria-modal="true"
      aria-labelledby="age-gate-title"
      className={styles.overlay}
    >
      <div className={styles.card}>
        <div className={styles.mark}>Lucifer&rsquo;s Diary</div>

        <p className={styles.notice}>Notice</p>

        <h2 id="age-gate-title" className={styles.title}>
          This volume contains adult writing.
        </h2>

        <p className={styles.body}>
          Some stories here include explicit themes intended for readers aged
          eighteen and over. If you are not yet 18, please leave.
        </p>

        {state === "show" ? (
          <div className={styles.buttons}>
            <button
              type="button"
              onClick={confirm}
              className={styles.confirmBtn}
            >
              Yes, I am 18 or older
            </button>
            <button
              type="button"
              onClick={decline}
              className={styles.declineBtn}
            >
              No, I am not
            </button>
          </div>
        ) : (
          <div className={styles.leaving}>Closing the volume…</div>
        )}

        <div className={styles.fineprint}>
          By entering you confirm you meet the age requirement in your
          jurisdiction.
        </div>
      </div>
    </div>
  );
}

