/* Marketing landing page (route: /). The story-browsing rails live
   at /browse — see app/browse/page.tsx. */

.landing {
  max-width: var(--container-home);
  margin: 0 auto;
  padding: 0 var(--pad-x) 96px;
  display: flex;
  flex-direction: column;
  gap: 72px;
}

/* ── Hero ──────────────────────────────────────────────────────── */
.hero {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 16px;
  max-width: 820px;
  padding: clamp(56px, 11vw, 128px) 0 8px;
}

.heroTitle {
  font-family: var(--font-display);
  font-weight: 700;
  font-size: clamp(48px, 9vw, 96px);
  line-height: 1.0;
  letter-spacing: -0.01em;
  color: var(--text);
  margin: 0;
}

.heroSub {
  font-family: var(--font-display);
  font-style: italic;
  font-weight: 500;
  font-size: clamp(19px, 3vw, 28px);
  line-height: 1.25;
  color: var(--gold);
  margin: 2px 0 0;
}

.heroPitch {
  font-family: var(--font-reading);
  font-size: clamp(16px, 2.2vw, 20px);
  line-height: 1.6;
  color: var(--text-muted);
  max-width: 58ch;
  margin: 8px 0 0;
}

/* ── Call to action ────────────────────────────────────────────── */
.ctaRow {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 16px;
}

.cta,
.ctaGhost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 14px 38px;
  font-family: var(--font-ui);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  border-radius: var(--radius-pill);
  text-decoration: none;
  transition:
    transform var(--transition-fast),
    background var(--transition-fast),
    color var(--transition-fast),
    border-color var(--transition-fast);
}

.cta {
  color: var(--bg);
  background: var(--gold);
  border: 1px solid var(--gold);
}
.cta:hover {
  transform: translateY(-1px);
  background: transparent;
  color: var(--gold);
}

.ctaGhost {
  color: var(--text);
  background: transparent;
  border: 1px solid var(--border-line-hover);
}
.ctaGhost:hover {
  transform: translateY(-1px);
  border-color: var(--gold);
  color: var(--gold);
}

.cta:focus-visible,
.ctaGhost:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

/* ── Prose section ("What this is") ────────────────────────────── */
.prose {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 68ch;
  border-top: 1px solid var(--border-line);
  padding-top: 56px;
}

.proseTitle {
  font-family: var(--font-display);
  font-size: clamp(22px, 3.5vw, 32px);
  font-weight: 600;
  color: var(--text);
  margin: 0;
}

.proseBody {
  font-family: var(--font-reading);
  font-size: 16px;
  line-height: 1.7;
  color: var(--text-muted);
  margin: 0;
}

/* ── Feature trio ──────────────────────────────────────────────── */
.features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  border-top: 1px solid var(--border-line);
  padding-top: 56px;
}

.feature {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.featureTitle {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 600;
  color: var(--text);
  margin: 0;
}

.featureBody {
  font-family: var(--font-reading);
  font-size: 15px;
  line-height: 1.65;
  color: var(--text-muted);
  margin: 0;
}

/* ── About / closing prose + CTA ───────────────────────────────── */
.about {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 68ch;
  border-top: 1px solid var(--border-line);
  padding-top: 56px;
}

.aboutTitle {
  font-family: var(--font-display);
  font-size: clamp(24px, 4vw, 38px);
  font-weight: 700;
  line-height: 1.1;
  color: var(--text);
  margin: 0;
}

.aboutBody {
  font-family: var(--font-reading);
  font-size: 16px;
  line-height: 1.7;
  color: var(--text-muted);
  margin: 0;
}

.about .cta {
  margin-top: 8px;
  align-self: flex-start;
}

/* ── Footer tagline ────────────────────────────────────────────── */
.footerTagline {
  font-family: var(--font-reading);
  font-style: italic;
  font-size: 14px;
  color: var(--text-muted);
  text-align: center;
  border-top: 1px solid var(--border-line);
  padding-top: 40px;
  margin: 0;
}

@media (max-width: 720px) {
  .landing {
    padding: 0 var(--pad-x-mobile) 80px;
    gap: 56px;
  }
  .features {
    grid-template-columns: 1fr;
    gap: 28px;
  }
}

