  gap: 28px;
  border-top: 1px solid var(--border-line);
  padding-top: 56px;
}

.feature {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.featureTitle {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 600;
  color: var(--text);
  margin: 0;
}

.featureBody {
  font-family: var(--font-reading);
  font-size: 15px;
  line-height: 1.65;
  color: var(--text-muted);
  margin: 0;
}

/* ── About / closing prose + CTA ───────────────────────────────── */
.about {
  display: flex;
  flex-direction: column;
  gap: 16px;
  max-width: 68ch;
  border-top: 1px solid var(--border-line);
  padding-top: 56px;
}

.aboutTitle {
  font-family: var(--font-display);
  font-size: clamp(24px, 4vw, 38px);
  font-weight: 700;
  line-height: 1.1;
  color: var(--text);
  margin: 0;
}

.aboutBody {
  font-family: var(--font-reading);
  font-size: 16px;
  line-height: 1.7;
  color: var(--text-muted);
  margin: 0;
}

.about .cta {
  margin-top: 8px;
  align-self: flex-start;
}

/* ── Footer tagline ────────────────────────────────────────────── */
.footerTagline {
  font-family: var(--font-reading);
  font-style: italic;
  font-size: 14px;
  color: var(--text-muted);
  text-align: center;
  border-top: 1px solid var(--border-line);
  padding-top: 40px;
  margin: 0;
}

@media (max-width: 720px) {
  .landing {
    padding: 0 var(--pad-x-mobile) 80px;
    gap: 56px;
  }
  .features {
    grid-template-columns: 1fr;
    gap: 28px;
  }
}

