import Link from "next/link";
import InlineRichText from "@/components/InlineRichText";
import ReadTime from "@/components/ReadTime";
import TagPill from "@/components/TagPill";
import type {
  ChapterCard as ChapterCardType,
  SeriesCard as SeriesCardType,
} from "@/types";
import styles from "./StoryCard.module.css";

function pluralize(n: number, singular: string, plural = `${singular}s`) {
  return `${n} ${n === 1 ? singular : plural}`;
}

function HeartGlyph() {
  return (
    <svg
      className={styles.likeIcon}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      suppressHydrationWarning
    >
      <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
    </svg>
  );
}

// ── SeriesCard ─────────────────────────────────────────────────────

export function SeriesCard({ series }: { series: SeriesCardType }) {
  const chapterCount = series._count?.chapters ?? series.chapters.length;
  const latestChapter = series.chapters[0];

  return (
    <Link
      href={`/series/${series.id}`}
      className={`${styles.card} ${series.isAdult ? styles.cardAdult : ""}`}
      data-tag-ids={series.tags.map((t) => t.id).join(" ")}
    >
      {/* 1. Title */}

