"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { adminStats, type AdminStats } from "@/lib/adminApi";
import adminStyles from "./admin.module.css";
import styles from "./dashboard.module.css";

const numberFormatter = new Intl.NumberFormat("en-US");

// Auth gating moved to frontend/middleware.ts when the admin token
// migrated to an httpOnly cookie (audit H-01 / H-02). If we're
// rendering, the cookie was present at middleware time; any later
// 401 (expired token, manual logout in another tab) is handled by
// adminApi.request hard-navigating to /admin/login.

export default function AdminDashboard() {
  const [stats, setStats] = useState<AdminStats | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    void adminStats
      .get()
      .then((s) => {
        if (!cancelled) setStats(s);
      })
      .catch((e) => {
        if (!cancelled) {
          setError(e instanceof Error ? e.message : "Failed to load stats");
        }
      });
    return () => {
      cancelled = true;
    };
  }, []);

  if (error)
    return (
      <p className={adminStyles.adminEmpty}>
        Couldn&rsquo;t load stats: {error}
      </p>
    );
  if (!stats)
    return <p className={adminStyles.adminEmpty}>Loading dashboard…</p>;

  const { totals, longest, topTags, recent } = stats;
  const peak = Math.max(
    1,
    ...recent.map((r) => r.chapters + r.stories),
  );

  return (
    <>
      <header className={adminStyles.adminPageHeader}>
        <h2 className={adminStyles.adminPageTitle}>Dashboard</h2>
      </header>

      <div className={styles.cards}>
        <Card
          label="Words published"
          primary={numberFormatter.format(totals.words.published)}
          secondary={`across ${totals.stories.published} ${
            totals.stories.published === 1 ? "story" : "stories"
          } + ${totals.chapters.published} ${
            totals.chapters.published === 1 ? "chapter" : "chapters"
          }`}
          accent
        />
        <Card
          label="Stories"
          primary={numberFormatter.format(totals.stories.total)}
          secondary={`${totals.stories.published} published · ${totals.stories.draft} draft`}
        />
        <Card
          label="Series"
          primary={numberFormatter.format(totals.series.total)}
          secondary={`${totals.chapters.total} ${
            totals.chapters.total === 1 ? "chapter" : "chapters"
          } total`}

