          </ul>
        </section>

        <section className={styles.section}>
          <h3 className={styles.sectionTitle}>Top tags</h3>
          {topTags.length === 0 ? (
            <p className={styles.longEmpty}>No tags in use yet.</p>
          ) : (
            <ul className={styles.tagList}>
              {topTags.map((t) => (
                <li key={t.id} className={styles.tagRow}>
                  <span
                    className={`${styles.tagPill} ${
                      t.isAdult ? styles.tagPillAdult : styles.tagPillSafe
                    }`}
                  >
                    {t.name}
                  </span>
                  <span className={styles.tagUsage}>
                    {t.usage} {t.usage === 1 ? "use" : "uses"}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </section>
      </div>

      <footer className={styles.shortcuts}>
        <Link href="/admin/stories" className={styles.shortcutLink}>
