// ============================================================
// NOTES (admin scratchpad — multi-card, color-coded)
// ============================================================
//
// Each Note is one card in the admin Notes panel on the
// Story / Chapter editor. Replaces the legacy single-string
// `notes` column previously on Story and Chapter. Polymorphic
// owner — exactly one of storyId / chapterId is set, enforced
// in the migration via a CHECK constraint (Prisma can't model
// XOR-nullable FKs directly).

model Note {
  id         String    @id @default(uuid())
  storyId    String?   @map("story_id")
  chapterId  String?   @map("chapter_id")
  // Short pill title — shown collapsed in the panel.
  title      String    @default("")
  // Body of the note. Plain text — see Story.notes (legacy) for
  // why we don't drag a rich-text editor in here.
  body       String    @default("")
  // Pill / dot color in the admin Notes panel. Enum keeps the
  // palette tight and validated; adding a color is a one-line
  // schema change (each addition needs a migration).
  color      NoteColor @default(GOLD)
  // Sort order within the owner's notes list. Lower first. Drag-
  // to-reorder is future work; today new notes append.
  orderIndex Int       @default(0) @map("order_index")
  createdAt  DateTime  @default(now()) @map("created_at")
