import {
  BadRequestException,
  Injectable,
  NotFoundException,
} from '@nestjs/common';
import { NoteColor } from '@prisma/client';
import { PrismaService } from '../prisma/prisma.service';
import { CreateNoteDto } from './dto/create-note.dto';
import { UpdateNoteDto } from './dto/update-note.dto';

@Injectable()
export class NotesService {
  constructor(private readonly prisma: PrismaService) {}

  // Create — owner XOR enforced here and at the DB level.
  async create(dto: CreateNoteDto) {
    const { storyId, chapterId, title, body, color } = dto;
    if (Boolean(storyId) === Boolean(chapterId)) {
      throw new BadRequestException(
        'Exactly one of storyId or chapterId must be provided',
      );
    }

    // Verify the owner exists AND isn't soft-deleted so we don't
    // create an orphan note on a row that's queued for hard delete.
    if (storyId) {
      const story = await this.prisma.story.findFirst({
        where: { id: storyId, deletedAt: null },
        select: { id: true },
      });
      if (!story) throw new NotFoundException(`Story ${storyId} not found`);
    } else {
      const chapter = await this.prisma.chapter.findFirst({
        where: { id: chapterId!, deletedAt: null },
        select: { id: true },
      });
      if (!chapter)
        throw new NotFoundException(`Chapter ${chapterId} not found`);
    }

    // Append at the end. Notes-per-piece is expected to be small
    // (handfuls, not hundreds), so this targeted query is cheap.
    const last = await this.prisma.note.findFirst({
      where: storyId ? { storyId } : { chapterId },
      orderBy: { orderIndex: 'desc' },
      select: { orderIndex: true },
    });
    const orderIndex = (last?.orderIndex ?? -1) + 1;

    return this.prisma.note.create({
      data: {
        storyId: storyId ?? null,
        chapterId: chapterId ?? null,
        title: title ?? '',
        body: body ?? '',
        color: color ?? NoteColor.GOLD,
        orderIndex,
      },
    });
  }

  // List — caller supplies exactly one of storyId / chapterId.
  async list(args: { storyId?: string; chapterId?: string }) {
    const { storyId, chapterId } = args;
    if (Boolean(storyId) === Boolean(chapterId)) {
      throw new BadRequestException(
        'Provide exactly one of storyId or chapterId',
      );
    }
    return this.prisma.note.findMany({
      where: storyId ? { storyId } : { chapterId },
      orderBy: { orderIndex: 'asc' },
    });
  }

  async update(id: string, dto: UpdateNoteDto) {
    const exists = await this.prisma.note.findUnique({
      where: { id },
      select: { id: true },
    });
    if (!exists) throw new NotFoundException(`Note ${id} not found`);
    return this.prisma.note.update({
      where: { id },
      data: dto,
    });
  }

  async remove(id: string) {
    const exists = await this.prisma.note.findUnique({
      where: { id },
      select: { id: true },
    });
    if (!exists) throw new NotFoundException(`Note ${id} not found`);
    await this.prisma.note.delete({ where: { id } });
    return { ok: true };
  }
}

