"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import RichTextEditor from "@/components/RichTextEditor";
import { plainTextToHtml } from "@/lib/richtext";
import NotesDrawer from "./NotesDrawer";
import TagPicker from "./TagPicker";
import styles from "./ContentForm.module.css";

const READING_WPM = 200;

export interface ContentFormValues {
  title: string;
  excerpt: string;
  content: string;
  estimatedReadMinutes: number;
  isAuthorsChoice: boolean;
  authorsNote: string;
  epigraph: string;
  /**
   * Private scratchpad. Stored on the row but never returned by
   * any public reader endpoint. Plain text by intent.
   */
  notes: string;
  tagIds: string[];
  /**
   * Optional series attachment, used by the new-story flow only.
   * When non-null, the parent page redirects the create call to
   * the chapter endpoint under this series id; when null, the
   * row becomes a standalone Story.
   */
  seriesId: string | null;
}

const EMPTY: ContentFormValues = {
  title: "",
  excerpt: "",
  content: "",
  estimatedReadMinutes: 1,
  isAuthorsChoice: false,
  authorsNote: "",
  epigraph: "",
  notes: "",
  tagIds: [],
  seriesId: null,
};

export interface SeriesOption {
  id: string;
  title: string;
}

interface Props {
  /** undefined = creating, set = editing */
  initial?: Partial<ContentFormValues>;
  /** Called when the user clicks Save (draft). Returns truthy on success. */
  onSave: (values: ContentFormValues) => Promise<unknown>;
  /**
   * Called automatically a short while after each edit. Only wired in
   * edit views (where we already have a row id to PATCH) — leave
   * undefined when creating.
   */
  onAutoSave?: (values: ContentFormValues) => Promise<unknown>;
  /** Optional Publish button — only meaningful when editing */
  onPublish?: () => Promise<unknown>;
  /** Optional Unpublish button — same */
  onUnpublish?: () => Promise<unknown>;
  /** Optional Delete button — same */
  onDelete?: () => Promise<unknown>;
  /** Whether the resource is currently published — used to swap publish/unpublish */
  isPublished?: boolean;
  /** Cancel link target */
  cancelHref?: string;
  /** Resource label, e.g. "Story" or "Chapter" */
  resource?: string;
  /** Optional confirm before delete */
  deleteConfirmMessage?: string;
  /**
   * If provided, the sidebar shows an "Attach to series" picker.
   * Only meaningful on the new-story flow — once a row exists,
   * moving it between series and standalone would require a
   * delete + recreate dance we don't support.
   */
  seriesOptions?: SeriesOption[];
  /**
   * Label for the single submit button when the form runs in
   * "create" mode (i.e. `onPublish` is undefined). The create
   * pages handle the publish step inside their own onSave so the
   * writer only sees one button. Defaults to "Save".
   */
  submitLabel?: string;
}

const AUTOSAVE_DEBOUNCE_MS = 1500;

export default function ContentForm({
  initial,

        {!savedAt && autoSaveStatus === "error" && (
          <span className={styles.autoSaveError}>Auto-save failed</span>
        )}

        {onDelete && (
          <Button
            type="button"
            variant="ghost"
            onClick={() => void submit("delete")}
            disabled={pending}
            style={{ color: "var(--like)" }}
          >
            Delete
          </Button>
        )}
      </div>
    </form>

    {/* Floating notes button + slide-out scratchpad. Sits outside the
        form so the drawer's overlay covers the whole admin layout
        (including the side nav) when open. The button is fixed
        bottom-right so it's reachable regardless of scroll position
        in a long content. */}
    <button
      type="button"
      onClick={() => setNotesOpen(true)}
      className={styles.notesFab}
      aria-label="Open notes"
      title="Open notes (private scratchpad)"
    >
      <svg
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
        strokeLinejoin="round"
        aria-hidden="true"
        suppressHydrationWarning
      >
        <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
        <polyline points="14 2 14 8 20 8" />
        <line x1="8" y1="13" x2="16" y2="13" />
        <line x1="8" y1="17" x2="14" y2="17" />
      </svg>
      <span>Notes</span>
      {values.notes.trim().length > 0 && (
        <span className={styles.notesFabDot} aria-hidden="true" />
      )}
    </button>

    <NotesDrawer
      open={notesOpen}
      onClose={() => setNotesOpen(false)}
      value={values.notes}
      onChange={(next) => update("notes", next)}
    />
    </>
  );
}

