"use client";

import { useRouter } from "next/navigation";
import { use, useEffect, useState } from "react";
import ContentForm, {
  type ContentFormValues,
} from "@/app/admin/_components/ContentForm";
import { adminStories } from "@/lib/adminApi";
import type { AdminStory } from "@/types";
import styles from "../../admin.module.css";

export default function EditStoryPage({
  params,
}: {
  params: Promise<{ id: string }>;
}) {
  const { id } = use(params);
  const router = useRouter();
  const [story, setStory] = useState<AdminStory | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    void adminStories
      .get(id)
      .then((s) => {
        if (!cancelled) setStory(s);
      })
      .catch((e) => {
        // Guard setError the same way .then() is guarded — a fetch
        // that rejects after the component unmounts must not setState.
        if (!cancelled) {
          setError(e instanceof Error ? e.message : "Load failed");
        }
      });
    return () => {
      cancelled = true;
    };
  }, [id]);

  const onSave = async (v: ContentFormValues) => {
    const updated = await adminStories.update(id, {
      title: v.title,
      content: v.content,
      excerpt: v.excerpt,
      estimatedReadMinutes: v.estimatedReadMinutes,
      isAuthorsChoice: v.isAuthorsChoice,
      authorsNote: v.isAuthorsChoice ? v.authorsNote : undefined,
      epigraph: v.epigraph || undefined,
      notes: v.notes,
      tagIds: v.tagIds,
    });
    setStory(updated);
  };

  // Auto-save uses the same payload but doesn't reset the local state
  // tree — preserves cursor position / focus inside the rich text
  // editor mid-typing.
  const onAutoSave = async (v: ContentFormValues) => {
    await adminStories.update(id, {
      title: v.title,
      content: v.content,
      excerpt: v.excerpt,
      estimatedReadMinutes: v.estimatedReadMinutes,
      isAuthorsChoice: v.isAuthorsChoice,
      authorsNote: v.isAuthorsChoice ? v.authorsNote : undefined,
      epigraph: v.epigraph || undefined,
      notes: v.notes,
      tagIds: v.tagIds,
    });
  };

  const onPublish = async () => {
    const updated = await adminStories.publish(id);
    setStory(updated);
  };

  const onUnpublish = async () => {
    const updated = await adminStories.unpublish(id);
    setStory(updated);
  };

  const onDelete = async () => {
    await adminStories.remove(id);
    router.replace("/admin/stories");
  };

  if (error) return <p className={styles.adminEmpty}>{error}</p>;
  if (!story) return <p className={styles.adminEmpty}>Loading…</p>;

  return (
    <>
      <header className={styles.adminPageHeader}>
        <h2 className={styles.adminPageTitle}>{story.title || "Edit story"}</h2>
      </header>
      <ContentForm
        initial={{
          title: story.title,
          excerpt: story.excerpt,
          content: story.content,
          estimatedReadMinutes: story.estimatedReadMinutes,
          isAuthorsChoice: story.isAuthorsChoice,
          authorsNote: story.authorsNote ?? "",
          epigraph: story.epigraph ?? "",
          notes: story.notes ?? "",
          tagIds: story.tags.map((t) => t.id),
        }}
        onSave={onSave}
        onAutoSave={onAutoSave}
        onPublish={onPublish}
        onUnpublish={onUnpublish}
        onDelete={onDelete}
        isPublished={!!story.publishedAt}
        resource="Story"
        cancelHref="/admin/stories"
      />
    </>
  );
}

