  title: string;
  content: string;
  excerpt: string;
  estimatedReadMinutes: number;
  isAuthorsChoice?: boolean;
  authorsNote?: string;
  epigraph?: string;
  notes?: string;
  tagIds?: string[];
}

export const adminStories = {
  list: () => request<StoryCard[]>("/admin/stories"),
  get: (id: string) => request<AdminStory>(`/admin/stories/${id}`),
  create: (data: StoryInput) =>
    request<AdminStory>("/admin/stories", {
      method: "POST",
      body: JSON.stringify(data),
    }),
