// ============================================================
// Shared types for the Lucifer's Diary frontend.
// Mirrors the response shapes of the NestJS API.
// ============================================================

export type ContentType = "story" | "chapter";

export interface Tag {
  id: string;
  name: string;
  slug: string;
  isAdult: boolean;
  createdAt: string;
}

// ── Cards (no full content, used in lists / homepage) ──────────

export interface StoryCard {
  type?: "story";
  id: string;
  title: string;
  excerpt: string;
  estimatedReadMinutes: number;
  likeCount: number;
  accumulatedReadSeconds: number;
  isAuthorsChoice: boolean;
  isAdult: boolean;
  publishedAt: string | null;
  tags: Tag[];
}

export interface ChapterCard {
  type?: "chapter";
  id: string;
  title: string;
  excerpt: string;
  orderIndex: number;
  estimatedReadMinutes: number;
  likeCount: number;
  accumulatedReadSeconds: number;
  isAuthorsChoice: boolean;
  isAdult: boolean;
  publishedAt: string | null;
  series: { id: string; title: string };
  tags: Tag[];
}

export type SeriesStatus = "ONGOING" | "COMPLETE" | "HIATUS";

export interface SeriesCard {
  id: string;
  title: string;
  excerpt: string;
  status: SeriesStatus;
  likeCount: number;
  accumulatedReadSeconds: number;
  isAdult: boolean;
  createdAt: string;
  tags: Tag[];
  chapters: Array<{
    id: string;
    title: string;
    orderIndex: number;
    publishedAt: string | null;
  }>;
  _count?: { chapters: number };
}

// Discriminated union for the three merged homepage sections.
// item.type === 'story' | 'chapter'
export type HomepageCard =
  | (StoryCard & { type: "story" })
  | (ChapterCard & { type: "chapter" });

// ── Full reading payloads ──────────────────────────────────────

export interface FullStory {
  id: string;
  title: string;
  excerpt: string;
  estimatedReadMinutes: number;
  likeCount: number;
  isAuthorsChoice: boolean;
  isAdult: boolean;
  authorsNote: string | null;
  epigraph: string | null;
  publishedAt: string;
  tags: Tag[];
  content: string;
  page: number;
  totalPages: number;
}

export interface FullChapter {
  id: string;
  title: string;
  excerpt: string;
  orderIndex: number;
  estimatedReadMinutes: number;
  likeCount: number;
  isAuthorsChoice: boolean;
  isAdult: boolean;
  authorsNote: string | null;
  epigraph: string | null;
  publishedAt: string;
  series: { id: string; title: string };
  tags: Tag[];
  content: string;
  page: number;
  totalPages: number;
  prev: { id: string; title: string; orderIndex: number } | null;
  next: { id: string; title: string; orderIndex: number } | null;
}

export interface SeriesDetail {
  id: string;
  title: string;
  excerpt: string;
  authorsNote: string | null;
  status: SeriesStatus;
  likeCount: number;
  accumulatedReadSeconds: number;
  createdAt: string;
  tags: Tag[];
  chapters: Array<{
    id: string;
    title: string;
    excerpt: string;
    orderIndex: number;
    estimatedReadMinutes: number;
    likeCount: number;
    publishedAt: string;
    tags: Tag[];
  }>;
}

