"use client";

// ============================================================
// Admin API client. The admin JWT lives in an httpOnly cookie
// (`lucifer_admin_session`) set by `POST /api/auth/login` and is
// sent automatically on every request via `credentials: 'include'`.
// No token ever enters JavaScript, so an XSS payload on the admin
// surface can't exfiltrate the session (audit H-01). The
// server-side gate for /admin routes lives in
// `frontend/middleware.ts` (audit H-02).
//
// Used only from client components.
// ============================================================

import type {
  AdminChapter,
  AdminSeriesDetail,
  AdminSeriesListItem,
  AdminStory,
  StoryCard,
  Tag,
} from "@/types";

const API_URL =
  process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3001/api";

/**
 * Thrown when a request hits a 401. The request handler also kicks
 * off a hard navigation to /admin/login so the user lands somewhere
 * useful; callers can still `instanceof`-check this to skip any
 * follow-up state updates that would race the navigation.
 */
export class AuthError extends Error {
  constructor() {
    super("UNAUTHORIZED");
    this.name = "AuthError";
  }
}

async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    ...((init.headers as Record<string, string>) ?? {}),
  };

  const res = await fetch(`${API_URL}${path}`, {
    ...init,
    headers,
    cache: "no-store",
    // Send the admin session cookie on every request.
    credentials: "include",
  });

  if (res.status === 401) {
    // Hard navigation to login. `window.location` (not Next's router)
    // is intentional — the in-flight fetch may have raced a stale
    // auth state, and a full reload clears any client state derived
    // from the now-expired session.
    if (typeof window !== "undefined") {
      window.location.href = "/admin/login";
    }
    throw new AuthError();
  }
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`${init.method ?? "GET"} ${path} -> ${res.status}${text ? `: ${text}` : ""}`);
  }
  if (res.status === 204) return undefined as T;
