  // newer characters locally. Without this, the input would silently
  // revert; without the lastSent check, the user's in-flight edits
  // would be clobbered by the server echo.
  useEffect(() => {
    if (title === lastSentTitle.current) setTitle(note.title);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [note.title]);
  useEffect(() => {
    if (body === lastSentBody.current) setBody(note.body);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [note.body]);

  // Debounced PATCH for title.
  useEffect(() => {
    if (title === note.title) return;
    const t = setTimeout(() => {
      lastSentTitle.current = title;
      onChange({ title });
    }, AUTOSAVE_DEBOUNCE_MS);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [title]);

  // Debounced PATCH for body.
  useEffect(() => {
    if (body === note.body) return;
    const t = setTimeout(() => {
      lastSentBody.current = body;
      onChange({ body });
    }, AUTOSAVE_DEBOUNCE_MS);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [body]);

  // Close the menu on outside click / Esc.
  useEffect(() => {
    if (!menuOpen) return;
    const onPointer = (e: PointerEvent) => {
      const target = e.target as Node | null;
      if (target && menuRef.current?.contains(target)) return;
      setMenuOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setMenuOpen(false);
    };
    document.addEventListener("pointerdown", onPointer);
    window.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onPointer);
      window.removeEventListener("keydown", onKey);
    };
  }, [menuOpen]);

  const colorLabel =
    NOTE_COLORS.find((c) => c.value === note.color)?.label ?? "Gold";
  const displayTitle = title.trim() || "Untitled note";

  const menu = (
    <div ref={menuRef} className={styles.menuWrap}>
      <button
        type="button"
        onClick={(e) => {
          e.stopPropagation();
          setMenuOpen((v) => !v);
        }}
        className={styles.menuBtn}
        aria-label="Note actions"
        aria-haspopup="menu"
        aria-expanded={menuOpen}
      >
        <DotsGlyph />
      </button>
      {menuOpen && (
        <div role="menu" className={styles.menuPanel}>
          <p className={styles.menuLabel}>Color</p>
          <div className={styles.swatchRow}>
            {NOTE_COLORS.map((c) => (
              <button
                key={c.value}
                type="button"
                onClick={() => {
                  onChange({ color: c.value });
                  setMenuOpen(false);
                }}
                className={`${styles.swatch} ${
                  c.value === note.color ? styles.swatchActive : ""
                }`}
                data-color={c.value}
                aria-label={`Color: ${c.label}`}
                title={c.label}
              >
                {c.value === note.color && <CheckGlyph />}
              </button>
            ))}
          </div>
          <button
            type="button"
            role="menuitem"
            onClick={() => {
              setMenuOpen(false);
              onDelete();
            }}
            className={styles.deleteBtn}
          >
            Delete note
          </button>
        </div>
      )}
    </div>
  );

  if (!expanded) {
    return (
      <div
        className={`${styles.card} ${styles.collapsed}`}
        data-color={note.color}
      >
        <button
          type="button"
          onClick={onExpand}
          className={styles.pillBody}
          aria-label={`Open note: ${displayTitle}. Color: ${colorLabel}`}
        >
          <span className={styles.dot} aria-hidden="true" />
          <span className={styles.pillTitle}>{displayTitle}</span>
        </button>
        {menu}
      </div>
    );
  }

  return (
    <div
      className={`${styles.card} ${styles.expanded}`}
      data-color={note.color}
    >
      <div className={styles.expandedHeader}>
        <button
          type="button"
          onClick={onCollapse}
          className={styles.collapseBtn}
          aria-label="Collapse note"
          title="Collapse"
        >
          <span className={styles.dot} aria-hidden="true" />
        </button>
        <input
          type="text"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Title"
          maxLength={120}
          className={styles.titleInput}
          aria-label="Note title"
        />
        {menu}
      </div>
      <textarea
        value={body}
        onChange={(e) => setBody(e.target.value)}
        placeholder="Note…"
        className={styles.bodyArea}
        rows={6}
        aria-label="Note body"
      />
    </div>
  );
}

function DotsGlyph() {
  return (
    <svg
      viewBox="0 0 24 24"
      width="16"
      height="16"
      fill="currentColor"
      aria-hidden="true"
      suppressHydrationWarning
    >
      <circle cx="5" cy="12" r="1.6" />
      <circle cx="12" cy="12" r="1.6" />
      <circle cx="19" cy="12" r="1.6" />
    </svg>
  );
}

function CheckGlyph() {
  return (
    <svg
      viewBox="0 0 24 24"
      width="12"
      height="12"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      suppressHydrationWarning
    >
      <polyline points="20 6 9 17 4 12" />
    </svg>
  );
}

input.content:
/* One note in the admin NotesPanel.
   The data-color attribute on .card maps to --note-color so the dot
   and accents pick up the right tone automatically.

   Palette tuned for the dark canvas — muted, dim-glow, literary. */

.card {
  --note-color: var(--gold);
  position: relative;
  display: flex;
  flex-direction: column;
  background: var(--bg-surface);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  font-family: var(--font-ui);
  transition: border-color var(--transition-fast);
}

.card[data-color="GOLD"]    { --note-color: var(--gold); }
.card[data-color="CRIMSON"] { --note-color: #c4584c; }
.card[data-color="SAGE"]    { --note-color: #7fa17b; }
.card[data-color="INDIGO"]  { --note-color: #7e8ed1; }
.card[data-color="AMBER"]   { --note-color: #d99a4a; }
.card[data-color="SLATE"]   { --note-color: #8a8e97; }

/* ── Collapsed pill ────────────────────────────────────────────── */
.collapsed {
  flex-direction: row;
  align-items: center;
  gap: 4px;
  padding: 4px 6px 4px 12px;
  border-radius: var(--radius-pill);
}
.collapsed:hover {
  border-color: var(--note-color);
}

.pillBody {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex: 1 1 auto;
  min-width: 0;
  background: transparent;
  border: 0;
  padding: 6px 0;
  font: inherit;
  color: var(--text);
  cursor: pointer;
  text-align: left;
}
.pillBody:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  border-radius: var(--radius-pill);
}

.dot {
  flex: 0 0 auto;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--note-color);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.35) inset;
}

.pillTitle {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.01em;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Expanded card ─────────────────────────────────────────────── */
.expanded {
  padding: 10px 10px 12px;
  border-color: var(--note-color);
}

.expandedHeader {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
}

.collapseBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  background: transparent;
  border: 0;
  border-radius: var(--radius-pill);
  cursor: pointer;
  padding: 0;
  color: var(--text-muted);
  transition: background var(--transition-fast);
}
.collapseBtn:hover {
  background: var(--bg);
}
.collapseBtn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.titleInput {
  flex: 1 1 auto;
  min-width: 0;
  background: transparent;
  border: 0;
  border-bottom: 1px solid transparent;
  padding: 4px 2px;
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  outline: none;
  transition: border-color var(--transition-fast);
}
.titleInput::placeholder {
  color: var(--text-muted);
  font-weight: 500;
  font-style: italic;
}
.titleInput:focus {
  border-bottom-color: var(--note-color);
}

.bodyArea {
  width: 100%;
  min-height: 120px;
  resize: vertical;
  background: var(--bg);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  padding: 10px 12px;
  font-family: var(--font-reading);
  font-size: 14px;
  line-height: 1.55;
  color: var(--text);
  outline: none;
  transition: border-color var(--transition-fast);
}
.bodyArea::placeholder {
  color: var(--text-muted);
  font-style: italic;
}
.bodyArea:focus {
  border-color: var(--note-color);
}

/* ── 3-dot action menu ─────────────────────────────────────────── */
.menuWrap {
  position: relative;
  flex: 0 0 auto;
}

.menuBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: transparent;
  border: 0;
  border-radius: var(--radius-pill);
  cursor: pointer;
  padding: 0;
  color: var(--text-muted);
  transition: background var(--transition-fast), color var(--transition-fast);
}
.menuBtn:hover {
  background: var(--bg);
  color: var(--text);
}
.menuBtn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.menuPanel {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 50;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 180px;
  padding: 10px 12px;
  background: var(--bg-surface);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  box-shadow: 0 12px 28px -12px rgba(0, 0, 0, 0.7);
}

.menuLabel {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.swatchRow {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
}

.swatch {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2px solid transparent;
  cursor: pointer;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: rgba(0, 0, 0, 0.85);
  transition: transform var(--transition-fast), border-color var(--transition-fast);
}
.swatch[data-color="GOLD"]    { background: var(--gold); }
.swatch[data-color="CRIMSON"] { background: #c4584c; }
.swatch[data-color="SAGE"]    { background: #7fa17b; }
.swatch[data-color="INDIGO"]  { background: #7e8ed1; }
.swatch[data-color="AMBER"]   { background: #d99a4a; }
.swatch[data-color="SLATE"]   { background: #8a8e97; }
.swatch:hover {
  transform: scale(1.08);
}
.swatch:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}
.swatchActive {
  border-color: var(--text);
}

.deleteBtn {
  background: transparent;
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  padding: 7px 10px;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--like);
  cursor: pointer;
  text-align: left;
  transition: background var(--transition-fast), border-color var(--transition-fast);
}
.deleteBtn:hover {
  background: var(--bg);
  border-color: var(--like);
}
.deleteBtn:focus-visible {
  outline: 2px solid var(--like);
  outline-offset: 2px;
}

