input.content:
"use client";

import { useCallback, useEffect, useState } from "react";
import { adminNotes } from "@/lib/adminApi";
import type { Note, NoteColor } from "@/types";
import NoteCard from "./NoteCard";
import styles from "./NotesPanel.module.css";

interface Props {
  /** Exactly one of storyId / chapterId must be set. */
  storyId?: string;
  chapterId?: string;
}

/**
 * Persistent right-column notes panel on the story / chapter editor.
 * Multiple color-coded note cards, one expanded at a time, with an
 * "+ Add note" action. Replaces the legacy single-textarea NotesDrawer.
 *
 * On wide screens the panel sits inline in the page's grid. Under
 * 1100px it collapses into a floating button (bottom-right) that
 * slides the panel in as an overlay sheet. The internal `mobileOpen`
 * state controls the sheet — it's a no-op on desktop because the CSS
 * forces the panel visible there regardless.
 */
export default function NotesPanel({ storyId, chapterId }: Props) {
  const [notes, setNotes] = useState<Note[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [busy, setBusy] = useState(false);

  // Initial fetch — re-runs if the owner id changes (e.g., editing
  // a different chapter in the same series flow).
  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    adminNotes
      .list({ storyId, chapterId })
      .then((data) => {
        if (cancelled) return;
        setNotes(data);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setError(e instanceof Error ? e.message : "Failed to load notes");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [storyId, chapterId]);

  const addNote = useCallback(async () => {
    if (busy) return;
    setBusy(true);
    try {
      const created = await adminNotes.create({
        storyId,
        chapterId,
        color: "GOLD",
      });
      setNotes((prev) => [...prev, created]);
      setExpandedId(created.id);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "Failed to add note");
    } finally {
      setBusy(false);
    }
  }, [busy, storyId, chapterId]);

  const updateNote = useCallback(
    async (
      id: string,
      patch: { title?: string; body?: string; color?: NoteColor },
    ) => {
      // Optimistic — apply locally first so typing/color clicks feel
      // instant; the server's response is the authoritative version
      // and overwrites in case of normalization.
      setNotes((prev) =>
        prev.map((n) => (n.id === id ? { ...n, ...patch } : n)),
      );
      try {
        const updated = await adminNotes.update(id, patch);
        setNotes((prev) => prev.map((n) => (n.id === id ? updated : n)));
      } catch (e: unknown) {
        setError(e instanceof Error ? e.message : "Failed to save note");
      }
    },
    [],
  );

  const deleteNote = useCallback(
    async (id: string) => {
      const removed = notes.find((n) => n.id === id);
      // Optimistic remove; on failure, re-insert at its original index.
      const idx = notes.findIndex((n) => n.id === id);
