/* Persistent right-column notes panel on the admin editor.

   Wide screens (>=1100px): inline in the page grid, sticky so it
     stays visible while the writer scrolls a long body.
   Narrow screens (<1100px): hidden by default; revealed as a
     slide-in sheet from the right when the FAB is tapped. */

.panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-self: start;
  width: 340px;
  max-height: calc(100dvh - 96px);
  padding: 14px;
  background: var(--bg-surface);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  position: sticky;
  top: 24px;
  font-family: var(--font-ui);
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border-line);
}

.title {
  margin: 0;
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--text);
}

.list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1 1 auto;
  overflow-y: auto;
  /* Breathing room so the bottom card isn't flush against the
     "Add note" button. */
  padding: 4px 0 4px;
}

.empty {
  margin: 16px 0;
  text-align: center;
  font-style: italic;
  font-size: 13px;
  color: var(--text-muted);
}

.error {
  margin: 0;
  padding: 8px 10px;
  background: rgba(196, 88, 76, 0.08);
  border: 1px solid rgba(196, 88, 76, 0.35);
  border-radius: var(--radius-md-app);
  font-size: 12px;
  color: var(--like);
}

.addBtn {
  margin-top: 4px;
  padding: 9px 12px;
  background: transparent;
  border: 1px dashed var(--border-line);
  border-radius: var(--radius-md-app);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  text-align: center;
  transition:
    border-color var(--transition-fast),
    color var(--transition-fast),
    background var(--transition-fast);
}
.addBtn:hover {
  border-color: var(--gold);
  color: var(--gold);
}
.addBtn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}
.addBtn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ── Mobile-only chrome ─────────────────────────────────────────
   The close button, the FAB, and the scrim are hidden on wide
   screens. The panel itself becomes a fixed slide-in sheet under
   1100px and slides in when `.mobileOpen` is on. */

.closeMobile {
  display: none;
  background: transparent;
  border: 0;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  cursor: pointer;
  color: var(--text-muted);
  padding: 0;
}
.closeMobile:hover {
  color: var(--text);
  background: var(--bg);
}

.mobileFab {
  display: none; /* desktop hides it */
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 80;
  align-items: center;
  gap: 8px;
  padding: 10px 16px;
  background: var(--bg-surface);
  border: 1px solid var(--gold);
  border-radius: var(--radius-pill);
  color: var(--gold);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  box-shadow: 0 12px 28px -10px rgba(0, 0, 0, 0.7);
  cursor: pointer;
}
.mobileFab:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.fabBadge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  background: var(--gold);
  border-radius: 9px;
  font-size: 10px;
  font-weight: 700;
  color: var(--bg);
  letter-spacing: 0;
}

.scrim {
  display: none; /* desktop hides it */
  position: fixed;
  inset: 0;
  z-index: 70;
  background: rgba(0, 0, 0, 0.55);
}

@media (max-width: 1100px) {
  /* Sheet mode: panel becomes a fixed slide-in from the right. */
  .panel {
    position: fixed;
    inset: 0 0 0 auto;
    width: min(360px, 92vw);
    max-height: 100dvh;
    height: 100dvh;
    border-radius: 0;
    border-left: 1px solid var(--border-line);
    border-right: 0;
    border-top: 0;
    border-bottom: 0;
    z-index: 90;
    top: auto;
    transform: translateX(100%);
    transition: transform 220ms ease-out;
  }
  .panel.mobileOpen {
    transform: translateX(0);
  }
  .closeMobile {
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }
  .mobileFab {
    display: inline-flex;
  }
  .scrim {
    display: block;
  }
}

