/* Floating notes button — fixed bottom-right so it's reachable from
   anywhere in a long content. Pill shape + gold accent matches the
   rest of the brand affordances. The dot indicator lights up when
   the writer has typed any notes, so they remember the scratchpad
   has stuff in it next time they open the page. */
.notesFab {
  position: fixed;
  right: 24px;
  bottom: 24px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 10px 18px;
  border: 1px solid var(--gold);
  border-radius: var(--radius-pill);
  background: var(--bg-surface);
  color: var(--gold);
  font-family: var(--font-ui);
  font-size: var(--fs-ui-sm);
  font-weight: 500;
  letter-spacing: var(--tracking-tag);
  text-transform: uppercase;
  cursor: pointer;
  z-index: 80;
  box-shadow: 0 8px 24px -8px rgba(0, 0, 0, 0.5);
  transition:
    background var(--transition-fast),
    color var(--transition-fast),
    transform var(--transition-fast);
}
.notesFab:hover {
  background: var(--gold);
  color: var(--bg);
  transform: translateY(-1px);
}
.notesFab svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

.notesFabDot {
  position: absolute;
  top: 6px;
  right: 6px;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gold);
  border: 1px solid var(--bg-surface);
}
.notesFab:hover .notesFabDot {
  background: var(--bg);
  border-color: var(--gold);
}

