.form {
  display: flex;
  flex-direction: column;
  gap: 24px;
  max-width: 1200px;
}

/* 2-column layout — main column for the long-form text fields,
   sticky sidebar for the page-level metadata (read time, tags,
   author's choice). The sidebar stays visible while the writer
   scrolls through a long content area. */
.grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 32px;
  align-items: start;
}

.main {
  display: flex;
  flex-direction: column;
  gap: 24px;
  min-width: 0;
}

.sidebar {
  display: flex;
  flex-direction: column;
  gap: 24px;
  position: sticky;
  /* Sticks just below the global sticky SiteHeader (~64px tall) +
     a bit of breathing room. */
  top: 80px;
  align-self: start;
}

@media (max-width: 1000px) {
  .grid {
    grid-template-columns: 1fr;
  }
  .sidebar {
    position: static;
  }
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.inlineRow {
  display: flex;
