interface Props {
  /** Exactly one of storyId / chapterId — passed straight to NotesPanel. */
  storyId?: string;
  chapterId?: string;
  /** The editor form (ContentForm). */
  children: ReactNode;
}

/**
 * Two-column wrapper used by the story / chapter edit pages: the
 * editor form on the left, the persistent multi-card NotesPanel on
 * the right. Collapses to a single column under 1100px — NotesPanel
 * handles its own slide-in sheet there.
 */
export default function EditorWithNotes({ storyId, chapterId, children }: Props) {
  return (
    <div className={styles.layout}>
      <div className={styles.formCol}>{children}</div>
      <div className={styles.notesCol}>
        <NotesPanel storyId={storyId} chapterId={chapterId} />
      </div>
    </div>
  );
}

