"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { use, useEffect, useState } from "react";
import ContentForm, {
  type ContentFormValues,
} from "@/app/admin/_components/ContentForm";
import EditorWithNotes from "@/app/admin/_components/EditorWithNotes";
import { adminChapters } from "@/lib/adminApi";
import type { AdminChapter } from "@/types";
import styles from "../../../../admin.module.css";

export default function EditChapterPage({
  params,
}: {
  params: Promise<{ id: string; chapterId: string }>;
}) {
  const { id: seriesId, chapterId } = use(params);
  const router = useRouter();
  const [chapter, setChapter] = useState<AdminChapter | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    void adminChapters
      .get(chapterId)
      .then((c) => {
        if (!cancelled) setChapter(c);
      })
      .catch((e) => {
        // Guard setError the same way .then() is guarded — a fetch
        // that rejects after the component unmounts must not setState.
        if (!cancelled) {
          setError(e instanceof Error ? e.message : "Load failed");
        }
      });
    return () => {
      cancelled = true;
    };
  }, [chapterId]);

  const onSave = async (v: ContentFormValues) => {
    const updated = await adminChapters.update(chapterId, {
      title: v.title,
      content: v.content,
      excerpt: v.excerpt,
      estimatedReadMinutes: v.estimatedReadMinutes,
      isAuthorsChoice: v.isAuthorsChoice,
      authorsNote: v.isAuthorsChoice ? v.authorsNote : undefined,
      epigraph: v.epigraph || undefined,
      notes: v.notes,
      tagIds: v.tagIds,
    });
    setChapter(updated);
  };

  const onAutoSave = async (v: ContentFormValues) => {
    await adminChapters.update(chapterId, {
      title: v.title,
      content: v.content,
      excerpt: v.excerpt,
      estimatedReadMinutes: v.estimatedReadMinutes,
      isAuthorsChoice: v.isAuthorsChoice,
      authorsNote: v.isAuthorsChoice ? v.authorsNote : undefined,
      epigraph: v.epigraph || undefined,
      notes: v.notes,
      tagIds: v.tagIds,
    });
  };

  const onPublish = async () => {
    const updated = await adminChapters.publish(chapterId);
    setChapter(updated);
  };

  const onUnpublish = async () => {
    const updated = await adminChapters.unpublish(chapterId);
    setChapter(updated);
  };

  const onDelete = async () => {
    await adminChapters.remove(chapterId);
    router.replace(`/admin/series/${seriesId}`);
  };

  if (error) return <p className={styles.adminEmpty}>{error}</p>;
  if (!chapter) return <p className={styles.adminEmpty}>Loading…</p>;

  return (
    <>
      <header className={styles.adminPageHeader}>
        <h2 className={styles.adminPageTitle}>
          {chapter.title || "Edit chapter"}
        </h2>
        <Link
          href={`/admin/series/${seriesId}`}
          style={{ color: "var(--text-muted)", fontSize: 13 }}
        >
          ← Back to {chapter.series.title}
        </Link>
      </header>
      <ContentForm
        initial={{
          title: chapter.title,
          excerpt: chapter.excerpt,
          content: chapter.content,
          estimatedReadMinutes: chapter.estimatedReadMinutes,
          isAuthorsChoice: chapter.isAuthorsChoice,
          authorsNote: chapter.authorsNote ?? "",
          epigraph: chapter.epigraph ?? "",
          notes: chapter.notes ?? "",
          tagIds: chapter.tags.map((t) => t.id),
        }}
        onSave={onSave}
        onAutoSave={onAutoSave}
        onPublish={onPublish}
        onUnpublish={onUnpublish}
        onDelete={onDelete}
        isPublished={!!chapter.publishedAt}
        resource="Chapter"
      />
    </>
  );
}

