"use client";

import { useRouter } from "next/navigation";
import { useEffect, useState } from "react";
import ContentForm, {
  type ContentFormValues,
  type SeriesOption,
} from "@/app/admin/_components/ContentForm";
import { adminChapters, adminSeries, adminStories } from "@/lib/adminApi";
import styles from "../../admin.module.css";

export default function NewStoryPage() {
  const router = useRouter();
  const [seriesOptions, setSeriesOptions] = useState<SeriesOption[]>([]);

  // Load the existing series so the sidebar's "Attach to series"
  // picker can offer them. Newest-first matches the admin list.
  useEffect(() => {
    let cancelled = false;
    void adminSeries
      .list()
      .then((rows) => {
        if (cancelled) return;
        setSeriesOptions(
          rows.map((r) => ({ id: r.id, title: r.title })),
        );
      })
      .catch(() => {
        // Failure here just hides the picker — the writer can still
        // create a standalone story.
      });
    return () => {
      cancelled = true;
    };
  }, []);

  const onSave = async (v: ContentFormValues) => {
    const payload = {
      title: v.title,
      content: v.content,
      excerpt: v.excerpt,
      estimatedReadMinutes: v.estimatedReadMinutes,
      isAuthorsChoice: v.isAuthorsChoice,
      authorsNote: v.isAuthorsChoice ? v.authorsNote : undefined,
      epigraph: v.epigraph || undefined,
      notes: v.notes || undefined,
      tagIds: v.tagIds,
    };

    if (v.seriesId) {
      // Picked a series in the sidebar — create as a chapter at the
      // end of that series, publish it immediately, and land the
      // writer back on the series detail page.
      const created = await adminChapters.create(v.seriesId, payload);
      await adminChapters.publish(created.id);
      router.replace(`/admin/series/${v.seriesId}`);
      return;
    }

    // Standalone story — create + publish in one shot, then land on
    // the edit page so the writer can keep tweaking. Single click
    // does the whole thing; the editor's own buttons take over from
    // there.
    const created = await adminStories.create(payload);
    await adminStories.publish(created.id);
    router.replace(`/admin/stories/${created.id}`);
  };

  return (
    <>
      <header className={styles.adminPageHeader}>
        <h2 className={styles.adminPageTitle}>New story</h2>
      </header>
      <ContentForm
        onSave={onSave}
        resource="Story"
        cancelHref="/admin/stories"
        seriesOptions={seriesOptions}
        submitLabel="Save & publish"
      />
    </>
  );
}

