"use client";

import { useCallback, useEffect, useState } from "react";
import { adminNotes } from "@/lib/adminApi";
import type { Note, NoteColor } from "@/types";
import NoteCard from "./NoteCard";
import styles from "./NotesPanel.module.css";

interface Props {
  /** Exactly one of storyId / chapterId must be set. */
  storyId?: string;
  chapterId?: string;
}

/**
 * Persistent right-column notes panel on the story / chapter editor.
 * Multiple color-coded note cards, one expanded at a time, with an
 * "+ Add note" action. Replaces the legacy single-textarea NotesDrawer.
 *
 * On wide screens the panel sits inline in the page's grid. Under
 * 1100px it collapses into a floating button (bottom-right) that
 * slides the panel in as an overlay sheet. The internal `mobileOpen`
 * state controls the sheet — it's a no-op on desktop because the CSS
 * forces the panel visible there regardless.
 */
export default function NotesPanel({ storyId, chapterId }: Props) {
  const [notes, setNotes] = useState<Note[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [busy, setBusy] = useState(false);

  // Initial fetch — re-runs if the owner id changes (e.g., editing
  // a different chapter in the same series flow). The setState calls
  // before the async fetch are an intentional reset-to-loading; the
  // react-hooks/set-state-in-effect rule (added in a recent plugin
  // bump) flags this pattern, but it's the same shape used elsewhere
  // in the codebase (see CommandPalette, AgeGate).
  useEffect(() => {
    let cancelled = false;
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setLoading(true);
    // eslint-disable-next-line react-hooks/set-state-in-effect
    setError(null);
    adminNotes
      .list({ storyId, chapterId })
      .then((data) => {
        if (cancelled) return;
        setNotes(data);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setError(e instanceof Error ? e.message : "Failed to load notes");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [storyId, chapterId]);

  const addNote = useCallback(async () => {
    if (busy) return;
    setBusy(true);
    try {
      const created = await adminNotes.create({
        storyId,
        chapterId,
        color: "GOLD",
      });
      setNotes((prev) => [...prev, created]);
      setExpandedId(created.id);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : "Failed to add note");
    } finally {
      setBusy(false);
    }
  }, [busy, storyId, chapterId]);

  const updateNote = useCallback(
    async (
      id: string,
      patch: { title?: string; body?: string; color?: NoteColor },
    ) => {
      // Optimistic — apply locally first so typing/color clicks feel
      // instant; the server's response is the authoritative version
      // and overwrites in case of normalization.
      setNotes((prev) =>
        prev.map((n) => (n.id === id ? { ...n, ...patch } : n)),
      );
      try {
        const updated = await adminNotes.update(id, patch);
        setNotes((prev) => prev.map((n) => (n.id === id ? updated : n)));
      } catch (e: unknown) {
        setError(e instanceof Error ? e.message : "Failed to save note");
      }
    },
    [],
  );

  const deleteNote = useCallback(
    async (id: string) => {
      const removed = notes.find((n) => n.id === id);
      // Optimistic remove; on failure, re-insert at its original index.
      const idx = notes.findIndex((n) => n.id === id);
      setNotes((prev) => prev.filter((n) => n.id !== id));
      if (expandedId === id) setExpandedId(null);
      try {
        await adminNotes.remove(id);
      } catch (e: unknown) {
        if (removed) {
          setNotes((prev) => {
            const next = prev.slice();
            next.splice(idx, 0, removed);
            return next;
          });
        }
        setError(e instanceof Error ? e.message : "Failed to delete note");
      }
    },
    [notes, expandedId],
  );

  return (
    <>
      <aside
        className={`${styles.panel} ${mobileOpen ? styles.mobileOpen : ""}`}
        aria-label="Notes"
      >
        <header className={styles.header}>
          <h3 className={styles.title}>Notes</h3>
          {/* Mobile-only close — hidden via CSS on wide screens. */}
          <button
            type="button"
            onClick={() => setMobileOpen(false)}
            className={styles.closeMobile}
            aria-label="Close notes"
          >
            <CrossGlyph />
          </button>
        </header>

        <div className={styles.list}>
          {error && <p className={styles.error}>{error}</p>}
          {loading && notes.length === 0 && (
            <p className={styles.empty}>Loading notes…</p>
          )}
          {!loading && notes.length === 0 && !error && (
            <p className={styles.empty}>No notes yet. Add one below.</p>
          )}
          {notes.map((note) => (
            <NoteCard
              key={note.id}
              note={note}
              expanded={expandedId === note.id}
              onExpand={() => setExpandedId(note.id)}
              onCollapse={() => setExpandedId(null)}
              onChange={(patch) => void updateNote(note.id, patch)}
              onDelete={() => void deleteNote(note.id)}
            />
          ))}
        </div>

        <button
          type="button"
          onClick={() => void addNote()}
          disabled={busy}
          className={styles.addBtn}
        >
          + Add note
        </button>
      </aside>

      {/* Mobile-only floating trigger — fixed bottom-right, hidden on
          wide screens via CSS. Carries a dot when notes exist so the
          writer knows the panel has content even when closed. */}
      <button
        type="button"
        onClick={() => setMobileOpen(true)}
        className={styles.mobileFab}
        aria-label="Open notes"
        title="Notes"
      >
        <NotesGlyph />
        <span>Notes</span>
        {notes.length > 0 && (
          <span className={styles.fabBadge} aria-hidden="true">
            {notes.length}
          </span>
        )}
      </button>

      {/* Scrim behind the mobile sheet — hidden on desktop and when
          the sheet is closed. */}
      {mobileOpen && (
        <div
          className={styles.scrim}
          onPointerDown={() => setMobileOpen(false)}
          aria-hidden="true"
        />
      )}
    </>
  );
}

function NotesGlyph() {
  return (
    <svg
      viewBox="0 0 24 24"
      width="16"
      height="16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.75"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      suppressHydrationWarning
    >
      <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
      <polyline points="14 2 14 8 20 8" />
      <line x1="8" y1="13" x2="16" y2="13" />
      <line x1="8" y1="17" x2="14" y2="17" />
    </svg>
  );
}

function CrossGlyph() {
  return (
    <svg
      viewBox="0 0 24 24"
      width="16"
      height="16"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.75"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      suppressHydrationWarning
    >
      <line x1="18" y1="6" x2="6" y2="18" />
      <line x1="6" y1="6" x2="18" y2="18" />
    </svg>
  );
}

