toolUseResult.originalFile:
/* Persistent right-column notes panel on the admin editor.

   Wide screens (>=1100px): inline in the page grid, sticky so it
     stays visible while the writer scrolls a long body.
   Narrow screens (<1100px): hidden by default; revealed as a
     slide-in sheet from the right when the FAB is tapped. */

.panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-self: start;
  width: 340px;
  max-height: calc(100dvh - 96px);
  padding: 14px;
  background: var(--bg-surface);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  position: sticky;
  top: 24px;
  font-family: var(--font-ui);
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border-line);
}

.title {
  margin: 0;
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--text);
}

.list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1 1 auto;
  overflow-y: auto;
  /* Breathing room so the bottom card isn't flush against the
     "Add note" button. */
  padding: 4px 0 4px;
}

.empty {
  margin: 16px 0;
  text-align: center;
  font-style: italic;
  font-size: 13px;
  color: var(--text-muted);
}

.error {
  margin: 0;
  padding: 8px 10px;
  background: rgba(196, 88, 76, 0.08);
  border: 1px solid rgba(196, 88, 76, 0.35);
  border-radius: var(--radius-md-app);
  font-size: 12px;
  color: var(--like);
}

.addBtn {
  margin-top: 4px;
  padding: 9px 12px;
  background: transparent;
  border: 1px dashed var(--border-line);
  border-radius: var(--radius-md-app);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  text-align: center;
  transition:
    border-color var(--transition-fast),
    color var(--transition-fast),
    background var(--transition-fast);
}
.addBtn:hover {
  border-color: var(--gold);
  color: var(--gold);
}
.addBtn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}
.addBtn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

/* ── Mobile-only chrome ─────────────────────────────────────────
   The close button, the FAB, and the scrim are hidden on wide
   screens. The panel itself becomes a fixed slide-in sheet under
   1100px and slides in when `.mobileOpen` is on. */

.closeMobile {
  display: none;
  background: transparent;
  border: 0;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  cursor: pointer;
  color: var(--text-muted);
  padding: 0;
}
