/* Persistent right-column notes panel on the admin editor.

   Wide screens (>=1100px): inline in the page grid, sticky so it
     stays visible while the writer scrolls a long body.
   Narrow screens (<1100px): hidden by default; revealed as a
     slide-in sheet from the right when the FAB is tapped. */

.panel {
  display: flex;
  flex-direction: column;
  gap: 12px;
  align-self: start;
  /* Wider than the original 340px so the panel absorbs the empty
     space between ContentForm's 1200px max-width and the right
     viewport edge on standard desktop widths. */
  width: clamp(360px, 32vw, 600px);
  max-height: calc(100dvh - 96px);
  padding: 14px;
  background: var(--bg-surface);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  position: sticky;
  top: 24px;
  font-family: var(--font-ui);
  /* Smooth the height grow/shrink when a card opens/closes. */
  transition: max-height var(--transition-fast), top var(--transition-fast);
}

/* When any note inside is expanded, give the panel the full visible
   height so the editor has room to actually write. */
.panel.hasExpanded {
  max-height: calc(100dvh - 24px);
  top: 12px;
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--border-line);
}

.title {
  margin: 0;
  font-family: var(--font-display);
  font-size: 16px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--text);
}

.list {
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1 1 auto;
  overflow-y: auto;
  /* Breathing room so the bottom card isn't flush against the
     "Add note" button. */
  padding: 4px 0 4px;
}

.empty {
  margin: 16px 0;
  text-align: center;
  font-style: italic;
  font-size: 13px;
  color: var(--text-muted);
}

.error {
  margin: 0;
  padding: 8px 10px;
  background: rgba(196, 88, 76, 0.08);
  border: 1px solid rgba(196, 88, 76, 0.35);
  border-radius: var(--radius-md-app);
  font-size: 12px;
  color: var(--like);
}

.addBtn {
  margin-top: 4px;
  padding: 9px 12px;
  background: transparent;
  border: 1px dashed var(--border-line);
  border-radius: var(--radius-md-app);
  font-family: var(--font-ui);
  font-size: 13px;
  font-weight: 500;
  color: var(--text-muted);
  cursor: pointer;
  text-align: center;
  transition:
    border-color var(--transition-fast),
    color var(--transition-fast),
    background var(--transition-fast);
}
.addBtn:hover {
  border-color: var(--gold);
  color: var(--gold);
}
.addBtn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}
.addBtn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

