/* One note in the admin NotesPanel.
   The data-color attribute on .card maps to --note-color so the dot
   and accents pick up the right tone automatically.

   Palette tuned for the dark canvas — muted, dim-glow, literary. */

.card {
  --note-color: var(--gold);
  position: relative;
  display: flex;
  flex-direction: column;
  background: var(--bg-surface);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  font-family: var(--font-ui);
  transition: border-color var(--transition-fast);
}

.card[data-color="GOLD"]    { --note-color: var(--gold); }
.card[data-color="CRIMSON"] { --note-color: #c4584c; }
.card[data-color="SAGE"]    { --note-color: #7fa17b; }
.card[data-color="INDIGO"]  { --note-color: #7e8ed1; }
.card[data-color="AMBER"]   { --note-color: #d99a4a; }
.card[data-color="SLATE"]   { --note-color: #8a8e97; }

/* ── Collapsed pill ────────────────────────────────────────────── */
.collapsed {
  flex-direction: row;
  align-items: center;
  gap: 4px;
  padding: 4px 6px 4px 12px;
  border-radius: var(--radius-pill);
}
.collapsed:hover {
  border-color: var(--note-color);
}

.pillBody {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex: 1 1 auto;
  min-width: 0;
  background: transparent;
  border: 0;
  padding: 6px 0;
  font: inherit;
  color: var(--text);
  cursor: pointer;
  text-align: left;
}
.pillBody:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  border-radius: var(--radius-pill);
}

.dot {
  flex: 0 0 auto;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--note-color);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.35) inset;
}

.pillTitle {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.01em;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Expanded card ─────────────────────────────────────────────── */
.expanded {
  padding: 10px 10px 12px;
  border-color: var(--note-color);
}

.expandedHeader {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
}

.collapseBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  background: transparent;
  border: 0;
  border-radius: var(--radius-pill);
  cursor: pointer;
  padding: 0;
  color: var(--text-muted);
  transition: background var(--transition-fast);
}
.collapseBtn:hover {
  background: var(--bg);
}
.collapseBtn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.titleInput {
  flex: 1 1 auto;
  min-width: 0;
  background: transparent;
  border: 0;
  border-bottom: 1px solid transparent;
  padding: 4px 2px;
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  outline: none;
  transition: border-color var(--transition-fast);
}
.titleInput::placeholder {
  color: var(--text-muted);
  font-weight: 500;
  font-style: italic;
}
.titleInput:focus {
  border-bottom-color: var(--note-color);
}

.bodyArea {
  width: 100%;
  min-height: 120px;
  resize: vertical;
  background: var(--bg);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  padding: 10px 12px;
  font-family: var(--font-reading);
  font-size: 14px;
  line-height: 1.55;
  color: var(--text);
  outline: none;
  transition: border-color var(--transition-fast);
}
.bodyArea::placeholder {
  color: var(--text-muted);
  font-style: italic;
}
.bodyArea:focus {
  border-color: var(--note-color);
}

/* ── 3-dot action menu ─────────────────────────────────────────── */
.menuWrap {
  position: relative;
  flex: 0 0 auto;
}

.menuBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: transparent;
  border: 0;
  border-radius: var(--radius-pill);
  cursor: pointer;
  padding: 0;
  color: var(--text-muted);
  transition: background var(--transition-fast), color var(--transition-fast);
}
.menuBtn:hover {
  background: var(--bg);
  color: var(--text);
}
.menuBtn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.menuPanel {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 50;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 180px;
  padding: 10px 12px;
  background: var(--bg-surface);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  box-shadow: 0 12px 28px -12px rgba(0, 0, 0, 0.7);
}

.menuLabel {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.swatchRow {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
}

.swatch {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2px solid transparent;
  cursor: pointer;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: rgba(0, 0, 0, 0.85);
  transition: transform var(--transition-fast), border-color var(--transition-fast);
}
.swatch[data-color="GOLD"]    { background: var(--gold); }
.swatch[data-color="CRIMSON"] { background: #c4584c; }
.swatch[data-color="SAGE"]    { background: #7fa17b; }
.swatch[data-color="INDIGO"]  { background: #7e8ed1; }
.swatch[data-color="AMBER"]   { background: #d99a4a; }
.swatch[data-color="SLATE"]   { background: #8a8e97; }
.swatch:hover {
  transform: scale(1.08);
}
.swatch:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}
.swatchActive {
  border-color: var(--text);
}

.deleteBtn {
  background: transparent;
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  padding: 7px 10px;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--like);
  cursor: pointer;
  text-align: left;
  transition: background var(--transition-fast), border-color var(--transition-fast);
}
.deleteBtn:hover {
  background: var(--bg);
  border-color: var(--like);
}
.deleteBtn:focus-visible {
  outline: 2px solid var(--like);
  outline-offset: 2px;
}

