.menuWrap {
  position: relative;
  flex: 0 0 auto;
}

.menuBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  background: transparent;
  border: 0;
  border-radius: var(--radius-pill);
  cursor: pointer;
  padding: 0;
  color: var(--text-muted);
  transition: background var(--transition-fast), color var(--transition-fast);
}
.menuBtn:hover {
  background: var(--bg);
  color: var(--text);
}
.menuBtn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.menuPanel {
  position: absolute;
  top: calc(100% + 6px);
  right: 0;
  z-index: 50;
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 180px;
  padding: 10px 12px;
  background: var(--bg-surface);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  box-shadow: 0 12px 28px -12px rgba(0, 0, 0, 0.7);
}

.menuLabel {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.swatchRow {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
}

.swatch {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2px solid transparent;
  cursor: pointer;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
