/* One note in the admin NotesPanel.
   The data-color attribute on .card maps to --note-color so the dot
   and accents pick up the right tone automatically.

   Palette tuned for the dark canvas — muted, dim-glow, literary. */

.card {
  --note-color: var(--gold);
  position: relative;
  display: flex;
  flex-direction: column;
  background: var(--bg-surface);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  font-family: var(--font-ui);
  /* Per-property transitions so hover/active/swap each feel right
     instead of one blanket ease that drags everything along. */
  transition:
    border-color var(--transition-fast),
    transform 180ms cubic-bezier(0.16, 1, 0.3, 1),
    box-shadow 220ms cubic-bezier(0.16, 1, 0.3, 1);
}

.card[data-color="GOLD"]    { --note-color: var(--gold); }
.card[data-color="CRIMSON"] { --note-color: #c4584c; }
.card[data-color="SAGE"]    { --note-color: #7fa17b; }
.card[data-color="INDIGO"]  { --note-color: #7e8ed1; }
.card[data-color="AMBER"]   { --note-color: #d99a4a; }
.card[data-color="SLATE"]   { --note-color: #8a8e97; }

/* ── Collapsed pill ────────────────────────────────────────────── */
.collapsed {
  flex-direction: row;
  align-items: center;
  gap: 4px;
  padding: 4px 6px 4px 12px;
  border-radius: var(--radius-pill);
}
.collapsed:hover {
  border-color: var(--note-color);
  /* Small lift + soft glow keyed to the note's color — feels alive
     under the cursor without being noisy. */
  transform: translateY(-1px);
  box-shadow: 0 6px 14px -8px color-mix(in srgb, var(--note-color) 55%, transparent);
}
.collapsed:active {
  transform: translateY(0) scale(0.995);
  box-shadow: none;
}

.pillBody {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex: 1 1 auto;
  min-width: 0;
  background: transparent;
  border: 0;
  padding: 6px 0;
  font: inherit;
  color: var(--text);
  cursor: pointer;
  text-align: left;
}
.pillBody:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  border-radius: var(--radius-pill);
}

.dot {
  flex: 0 0 auto;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--note-color);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.35) inset;
}

.pillTitle {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.01em;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Expanded card ─────────────────────────────────────────────── */
.expanded {
  padding: 10px 10px 12px;
  border-color: var(--note-color);
  /* Stretch to consume any remaining vertical space in the panel's
     list — the textarea inside grows with it. Collapsed pill
     siblings stay at intrinsic height. */
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  min-height: 220px;
  /* Tiny fade + lift-in on mount — runs on pill→expanded swap and
     when a brand-new note is added (it spawns expanded). Subtle, so
     it never reads as decoration. */
  animation: noteExpandIn 200ms cubic-bezier(0.16, 1, 0.3, 1) both;
}

@keyframes noteExpandIn {
  from {
    opacity: 0.4;
    transform: translateY(-3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.expandedHeader {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
}

.collapseBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  background: transparent;
  border: 0;
  border-radius: var(--radius-pill);
  cursor: pointer;
  padding: 0;
  color: var(--text-muted);
  transition: background var(--transition-fast);
}
.collapseBtn:hover {
  background: var(--bg);
}
.collapseBtn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.titleInput {
  flex: 1 1 auto;
  min-width: 0;
  background: transparent;
  border: 0;
  border-bottom: 1px solid transparent;
  padding: 4px 2px;
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  outline: none;
  transition: border-color var(--transition-fast);
}
.titleInput::placeholder {
  color: var(--text-muted);
  font-weight: 500;
  font-style: italic;
}
.titleInput:focus {
  border-bottom-color: var(--note-color);
}

.bodyArea {
  width: 100%;
  /* Flex-grow inside the expanded card so the textarea fills the
     panel's vertical space. The min-height keeps the textarea
     usable even when the panel is short (collapsed neighbours
     above eating the space). resize:none avoids fighting the
     flex sizing with a manual handle. */
  flex: 1 1 auto;
  min-height: 140px;
  resize: none;
  background: var(--bg);
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  padding: 10px 12px;
  font-family: var(--font-reading);
  font-size: 14px;
  line-height: 1.55;
  color: var(--text);
  outline: none;
  transition: border-color var(--transition-fast);
}
.bodyArea::placeholder {
  color: var(--text-muted);
  font-style: italic;
}
.bodyArea:focus {
  border-color: var(--note-color);
}

