"use client";

import { useEffect, useRef } from "react";
import type { ContentType } from "@/types";
import { getReadingPosition } from "./api";
import { getSessionToken } from "./session";

const API_URL =
  process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:3001/api";

/** Minimum time between scroll-driven position writes. */
const WRITE_THROTTLE_MS = 5000;

/**
 * Anything below this percentage is the visitor effectively "at the
 * top." Skip the restore so a 2% scroll on a long chapter doesn't
 * jolt back to where their finger barely touched.
 */
const RESTORE_MIN_PERCENT = 4;

/**
 * Same idea at the top of the document: don't write a scroll
 * position at < 2% — every "open the chapter and immediately scroll
 * a hair" event would otherwise overwrite a real, higher position
 * we've already saved.
 */
const WRITE_MIN_PERCENT = 2;

interface Options {
  contentType: ContentType;
  contentId: string;
  /**
   * Current page in paged-mode chapters. Stored alongside the
   * scroll percentage so resume lands the reader on the right page
   * before scrolling. Pass null in infinite-mode.
   */
  pageNumber: number | null;
  /**
   * True when there's content rendered + the page can scroll.
   * Used to gate the restore-on-mount until the article has paint
   * — restoring against an empty document would scroll nowhere.
   */
  enabled?: boolean;
}

/**
 * Tracks the reader's vertical position within the article and
 * restores it on the next visit. Pairs with the backend
 * `/api/reading-positions` endpoints.
 *
 * Lifecycle:
 *   1. On mount (or when contentId / pageNumber changes) fetch any
 *      stored position. If it matches the current pageNumber and is
 *      ≥ RESTORE_MIN_PERCENT, schedule a scroll via
 *      requestIdleCallback so it happens after first paint without
 *      racing layout.
 *   2. While the user scrolls, throttle a `sendBeacon` write to
 *      `/api/reading-positions` every WRITE_THROTTLE_MS so we don't
 *      hammer the backend.
 *   3. On `visibilitychange → hidden` and `pagehide` flush the
 *      latest position so a tab close doesn't lose the most recent
 *      few seconds of scrolling.
 *
 * Idempotent at the API layer: a duplicate write for the same
 * (contentType, contentId, identifier) upserts onto the existing
 * row, so firing twice on a flaky exit is a no-op.
 */
export function useReadingPosition({
  contentType,
  contentId,
  pageNumber,
  enabled = true,
}: Options) {
  // Hold the latest "should we still be running" flag in a ref so
  // the cleanup paths can short-circuit without going through the
  // closure's value (which is captured at effect-fire time).
  const enabledRef = useRef(enabled);
  enabledRef.current = enabled;

  // Track the last write so we can throttle by elapsed time without
  // a setInterval — `setTimeout` chains lose timing accuracy fast.
  const lastWriteAtRef = useRef(0);
  const pendingTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(
    null,
  );

  useEffect(() => {
    if (!enabled) return;
    if (typeof window === "undefined") return;

    let cancelled = false;

    // ── Restore on mount ────────────────────────────────────────
    //
    // Wrap in idle-callback so the article has time to lay out
    // before we try to scrollTo. Without this, the percentage maps
    // to "0" because document.documentElement.scrollHeight is still
    // the viewport height during hydration.
    const sessionToken = getSessionToken();
    void (async () => {
      try {
        const pos = await getReadingPosition(contentType, contentId, sessionToken);
        if (cancelled || !pos) return;
        // Skip restore if the stored position is on a different
        // page (paged mode) — the page-aware URL handling in the
        // ReadingView will get the visitor onto the right page;
        // then the hook re-fires with the new pageNumber and the
        // restore matches.
        if (pos.pageNumber !== pageNumber) return;
        if (pos.scrollPercentage < RESTORE_MIN_PERCENT) return;

        const restore = () => {
          if (cancelled) return;
          const doc = document.documentElement;
          const target =
            (pos.scrollPercentage / 100) *
            (doc.scrollHeight - window.innerHeight);
          if (!Number.isFinite(target) || target <= 0) return;
          window.scrollTo({ top: target, behavior: "instant" });
        };
        // `requestIdleCallback` falls back to rAF on Safari — that
        // still gets us past the synchronous hydration tick.
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const ric = (window as any).requestIdleCallback as
          | undefined
          | ((cb: () => void, opts?: { timeout: number }) => number);
        if (typeof ric === "function") {
          ric(restore, { timeout: 500 });
        } else {
          requestAnimationFrame(restore);
        }
      } catch {
        // Network failure / bad response — leave the user at the
        // top. The next scroll will start writing a fresh position.
      }
    })();

    // ── Write throttler ─────────────────────────────────────────

    const buildBody = () => {
      const doc = document.documentElement;
      const denom = doc.scrollHeight - window.innerHeight;
      const pct = denom > 0 ? (window.scrollY / denom) * 100 : 0;
      const clamped = Math.max(0, Math.min(100, pct));
      return {
        contentType,
        contentId,
        scrollPercentage: clamped,
        pageNumber,
        sessionToken,
      };
    };

    const sendNow = () => {
      const body = buildBody();
      if (body.scrollPercentage < WRITE_MIN_PERCENT) return;
      lastWriteAtRef.current = Date.now();
      try {
        navigator.sendBeacon(
          `${API_URL}/reading-positions`,
          new Blob([JSON.stringify(body)], { type: "application/json" }),
        );
      } catch {
        // sendBeacon throws synchronously on payload-too-large /
        // wrong type. Should never happen for our payload size,
        // but a swallow keeps the hook resilient.
      }
    };

    const flushPending = () => {
      if (pendingTimeoutRef.current) {
        clearTimeout(pendingTimeoutRef.current);
        pendingTimeoutRef.current = null;
      }
      sendNow();
    };

    const onScroll = () => {
      const elapsed = Date.now() - lastWriteAtRef.current;
      if (elapsed >= WRITE_THROTTLE_MS) {
        sendNow();
        return;
      }
      // Schedule a trailing flush so we capture the user's final
      // resting position even if they stop scrolling between throttle
      // windows.
      if (pendingTimeoutRef.current) return;
      pendingTimeoutRef.current = setTimeout(() => {
        pendingTimeoutRef.current = null;
        sendNow();
      }, WRITE_THROTTLE_MS - elapsed);
    };

    const onVisibility = () => {
      if (document.visibilityState === "hidden") flushPending();
    };

    window.addEventListener("scroll", onScroll, { passive: true });
    document.addEventListener("visibilitychange", onVisibility);
    window.addEventListener("pagehide", flushPending);

    return () => {
      cancelled = true;
      window.removeEventListener("scroll", onScroll);
      document.removeEventListener("visibilitychange", onVisibility);
      window.removeEventListener("pagehide", flushPending);
      if (pendingTimeoutRef.current) {
        clearTimeout(pendingTimeoutRef.current);
        pendingTimeoutRef.current = null;
      }
      // Flush one final write on unmount (SPA route change) so the
      // user's last position before navigating away is captured.
      flushPending();
    };
  }, [contentType, contentId, pageNumber, enabled]);
}

