const restore = () => {
  if (cancelled) return;
  const doc = document.documentElement;
  // Clamp to the current scroll max — post-hydration layout
  // shifts (fonts loading, images resolving) can shrink the
  // document below the saved-percentage target.
  const max = doc.scrollHeight - window.innerHeight;
  const target =
    (pos.scrollPercentage / 100) *
    (doc.scrollHeight - window.innerHeight);
  if (!Number.isFinite(target) || target <= 0) return;
  const clamped = Math.min(target, max);

  // Hash precedence: a `#some-heading` or `#:~:text=...`
  // text-fragment URL means the browser is already handling
  // the navigation target. Skip the restore entirely — the
  // anchor / fragment wins, and a tween on top would race it.
  if (window.location.hash.length > 1) return;

  // Reduced-motion: animating ~1s of vertical scroll is a
  // known vestibular trigger. Keep the legacy instant jump.
  if (prefersReducedMotion()) {
    window.scrollTo({ top: clamped, behavior: "instant" });
    return;
  }

  // Pause the scroll-write throttler BEFORE constructing the
  // tween config — gsap.to is async-internal but the very
  // first onUpdate may fire before a post-construction
  // assignment, racing the guard.
  restoringRef.current = true;
  // Mark the manual write timestamp so even if a wheel/touch
  // wakes onScroll mid-tween, the throttle window absorbs it
  // (belt-and-braces alongside restoringRef).
  lastWriteAtRef.current = Date.now();

  // Killing-clearing both refs runs on success, autoKill
  // (user interrupted), and the rare onInterrupt (a competing
  // tween took over). Each path is the SAME work — declared
  // once, wired three times.
  const clearTweenState = () => {
    restoringRef.current = false;
    tweenRef.current = null;
  };

  tweenRef.current = gsap.to(window, {
    duration: 1.1,
    ease: "power2.out",
    overwrite: "auto",
    scrollTo: {
      y: clamped,
      // Any user wheel/touch/keyboard scroll cancels the
      // tween instantly — non-negotiable for a returning
      // reader who wants to control where they land.
      autoKill: true,
      onAutoKill: clearTweenState,
    },
    // Keep ScrollTrigger-driven in-view reveals firing during
    // the programmatic scroll (matches the canonical GSAP
    // ScrollToPlugin pattern when ScrollTrigger is also live).
    onUpdate: () => ScrollTrigger.update(),
    onComplete: clearTweenState,
    onInterrupt: clearTweenState,
  });
};

