"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import {
  deleteSave,
  getSaveStatus,
  postSave,
  UserApiError,
  useAuth,
  type ContentType,
} from "@/lib/userAuth";
import styles from "./SaveButton.module.css";

interface Props {
  contentType: ContentType;
  contentId: string;
}

/**
 * Bookmark control. Logged-in users save / unsave server-side; the
 * dashboard reads the list back. Anonymous users see a disabled
 * variant that points at /signup with a helpful tooltip — we don't
 * silently swallow taps.
 */
export default function SaveButton({ contentType, contentId }: Props) {
  const auth = useAuth();
  const [saved, setSaved] = useState(false);
  const [pending, setPending] = useState(false);
  const [hydrated, setHydrated] = useState(false);

  // Hydrate "is this saved" from the server once we know we're
  // logged in. Anonymous users never hit the network here.
  useEffect(() => {
    if (auth.status !== "authenticated") {
      setHydrated(false);
      return;
    }
    let cancelled = false;
    void (async () => {
      try {
        const { saved } = await getSaveStatus(contentType, contentId);
        if (!cancelled) {
          setSaved(saved);
          setHydrated(true);
        }
      } catch {
        // Network failure shouldn't block the UI.
        if (!cancelled) setHydrated(true);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [auth.status, contentType, contentId]);

  // Anonymous: render a "Sign up to save" link.
  if (auth.status !== "authenticated") {
    return (
      <Link
        href="/signup"
        className={styles.button}
        title="Sign up to save stories"
        aria-label="Sign up to save stories"
      >
        <BookmarkIcon filled={false} />
        <span>Save</span>
      </Link>
    );
  }

  const toggle = async () => {
    if (pending) return;
    const wasSaved = saved;
    setSaved(!wasSaved);
    setPending(true);
    try {
      if (wasSaved) {
        await deleteSave(contentType, contentId);
      } else {
        await postSave(contentType, contentId);
      }
    } catch (err) {
      // Roll back on failure. A 409 from postSave means the row was
      // already there (probably from a double-tap) — treat as success.
      if (err instanceof UserApiError && err.status === 409 && !wasSaved) {
        // No-op — server agrees it's saved.
      } else {
        setSaved(wasSaved);
      }
    } finally {
      setPending(false);
    }
  };

  return (
    <button
      type="button"
      onClick={() => void toggle()}
      disabled={pending || !hydrated}
      aria-pressed={saved}
      aria-label={saved ? "Remove from saved" : "Save"}
      className={`${styles.button} ${saved ? styles.saved : ""}`}
    >
      <BookmarkIcon filled={saved} />
      <span>{saved ? "Saved" : "Save"}</span>
    </button>
  );
}

function BookmarkIcon({ filled }: { filled: boolean }) {
  return (
    <svg
      className={styles.icon}
      viewBox="0 0 24 24"
      stroke="currentColor"
      fill={filled ? "currentColor" : "none"}
      strokeWidth="1.75"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      suppressHydrationWarning
    >
