==== components/LikeButton.module.css ====
/* Geometry matches Save / Share so all three pills in the reading
   footer read as one consistent row. The .liked state below swaps
   the colors for the active treatment but keeps the same shape. */
.button {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 14px;
  border: 1px solid var(--border-line);
  border-radius: var(--radius-pill);
  background: var(--bg-surface);
  color: var(--text-muted);
  font-family: var(--font-ui);
  font-size: var(--fs-tag);
  font-weight: 500;
  letter-spacing: var(--tracking-tag);
  text-transform: uppercase;
  cursor: pointer;
  transition:
    color var(--transition-fast),
    background var(--transition-fast),
    border-color var(--transition-fast);
}

.button:hover:not(:disabled),
.button:focus-visible:not(:disabled) {
  border-color: var(--border-line-hover);
  color: var(--text);
  /* Suppress the browser default outline so the styled border-color
     swap is the single, unambiguous focus affordance. */
  outline: none;
}

.button:disabled {
  cursor: default;
  opacity: 0.6;
}

.liked {
  color: var(--like);
  border-color: rgba(224, 123, 123, 0.4);
  background: var(--like-tint);
}
.liked:hover:not(:disabled),
.liked:focus-visible:not(:disabled) {
  color: var(--like);
  border-color: rgba(224, 123, 123, 0.55);
  outline: none;
}

.icon {
  width: 13px;
  height: 13px;
  display: inline-flex;
  flex-shrink: 0;
  transition: fill var(--transition-fast);
}

.iconFilled {
  fill: var(--like);
  stroke: var(--like);
}
.iconOutline {
  fill: none;
  stroke: currentColor;
}

.count {
  font-variant-numeric: tabular-nums;
}

/* Touch-target sizing — bump padding so the pill clears 44px tall
   on phones. Desktop stays dense; the like / save / share footer
   row reads as one tight cluster there. */
@media (max-width: 720px) {
  .button {
    padding: 11px 16px;
  }
}
