import { gsap } from 'gsap';
import { CustomBounce } from 'gsap/CustomBounce';
import { CustomEase } from 'gsap/CustomEase';
import { Physics2DPlugin } from 'gsap/Physics2DPlugin';
import { ScrollToPlugin } from 'gsap/ScrollToPlugin';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

if (typeof window !== 'undefined') {
  // Multi-arg registration — one module eval per plugin, all in one
  // call. Subsequent registers are no-ops, so re-importing this
  // module never double-registers. All five are free in gsap@3.13+
  // post-Webflow acquisition (verified against installed 3.15.0).
  // NOTE: if a future PR adds `html { scroll-behavior: smooth }` to
  // globals.css, ScrollToPlugin's autoKill will fight it. Keep the
  // browser's smooth-scroll off; GSAP owns programmatic scrolling.
  gsap.registerPlugin(
    ScrollTrigger,
    ScrollToPlugin,
    Physics2DPlugin,
    CustomBounce,
    CustomEase,
  );

  // Register a single named bounce once; pressFeedback() uses it on
  // every button click. Doing this here (instead of in pressFeedback)
  // means we pay the cost once at module load, not per click.
  CustomBounce.create('btnBounce', {
    strength: 0.55,
    endAtStart: false,
    squash: 1.2,
  });
}

