input.content:
// ============================================================
// pressFeedback — shared GSAP click-feedback timeline for the
// Like / Save / Share / QuoteShare buttons (T3 of the GSAP plan).
// ============================================================
//
// Layered timeline per click:
//   1. CustomBounce squish-and-rebound on scale (transform)
//   2. A `--press-flash` CSS-var tween from 1 → 0; each button's
//      CSS reads it to drive a colored box-shadow that pulses out
//      and fades. The button supplies its own `--press-color`
//      inline-style, so per-button color is one prop.
//   3. (Optional, Like only) Physics2DPlugin confetti burst —
//      short-lived <span> children of the button that get launched
//      upward with gravity + friction, then removed on complete.
//
// Reduced-motion path: skip the bounce + burst, keep the color
// flash so the action still has visual confirmation, but with a
// short non-bouncy curve.
//
// Spam-click safe: kills in-flight tweens on the same element
// before starting a new one (overwrite:'auto' on every tween).

import { gsap, prefersReducedMotion } from "./gsap";

export interface PressFeedbackOptions {
  /** Spawn a particle burst from the button center on the same
   *  timeline — used for Like only. Particles are spans appended to
   *  the button itself (so they're clipped by any modal scrim above,
   *  which is the safer default — see GSAP integration plan §T3). */
  burst?: boolean;
  /** Particle count for the burst. Default 8 — tasteful, not
   *  party-mode confetti. */
  burstCount?: number;
}

/**
 * Trigger a tactile click feedback animation on `el`. Caller passes
 * a color (any CSS color or var(...)) for the glow; the button's
 * inline `--press-color` style picks it up.
 */
export function pressFeedback(
  el: HTMLElement | null,
  opts: PressFeedbackOptions = {},
) {
  if (!el) return;
  // Cancel any in-flight feedback tween on this element so spam
  // clicks restart cleanly rather than queue.
  gsap.killTweensOf(el);

  if (prefersReducedMotion()) {
    // Color flash only — no scale, no burst. Shorter curve.
    gsap.fromTo(
      el,
      { "--press-flash": 1 },
      {
        "--press-flash": 0,
        duration: 0.18,
        ease: "power1.out",
        overwrite: "auto",
      },
    );
    return;
  }

  const tl = gsap.timeline({ defaults: { overwrite: "auto" } });

  // 1. Tactile squish-and-rebound. `btnBounce` is registered once
  //    in lib/gsap.ts at module load.
  tl.fromTo(
    el,
