"use client";

import { useEffect, useRef, useState } from "react";
import { gsap, prefersReducedMotion, useGSAP } from "@/lib/gsap";
import { deleteLike, getLikeStatus, postLike } from "@/lib/api";
import { getSessionToken } from "@/lib/session";
import type { ContentType } from "@/types";
import styles from "./LikeButton.module.css";

interface Props {
  contentType: ContentType;
  contentId: string;
  initialCount: number;
}

export default function LikeButton({ contentType, contentId, initialCount }: Props) {
  const buttonRef = useRef<HTMLButtonElement>(null);
  const [liked, setLiked] = useState(false);
  const [count, setCount] = useState(initialCount);
  const [pending, setPending] = useState(false);

  // Read the current liked state once on mount.
  useEffect(() => {
    let cancelled = false;
    void (async () => {
      try {
        const token = getSessionToken();
        const { liked } = await getLikeStatus(contentType, contentId, token);
        if (!cancelled) setLiked(liked);
      } catch {
        // Network failure shouldn't block the page.
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [contentType, contentId]);

  useGSAP(
    () => {
      // No-op until pulse() is called below — this scope is just here
      // so all gsap.from/to animations are auto-cleaned up.
    },
    { scope: buttonRef },
  );

  const pulse = () => {
    if (!buttonRef.current) return;
    if (prefersReducedMotion()) return;
    gsap.fromTo(
      buttonRef.current,
      { scale: 1 },
      { scale: 1.15, duration: 0.1, yoyo: true, repeat: 1, ease: "power2.out" },
    );
  };

  const toggle = async () => {
    if (pending) return;
    pulse();

    // Optimistic update
    const wasLiked = liked;
    const prevCount = count;
    setLiked(!wasLiked);
    setCount((c) => c + (wasLiked ? -1 : 1));
    setPending(true);

    try {
      const sessionToken = getSessionToken();
      const body = { contentType, contentId, sessionToken };
      if (wasLiked) {
        await deleteLike(body);
      } else {
        await postLike(body);
      }
    } catch {
      // Revert on failure.
      setLiked(wasLiked);
      setCount(prevCount);
    } finally {
      setPending(false);
    }
  };

  return (
    <button
      ref={buttonRef}
      type="button"
      onClick={toggle}
      disabled={pending}
      aria-pressed={liked}
      aria-label={liked ? "Unlike" : "Like"}
      className={`${styles.button} ${liked ? styles.liked : ""}`}
    >
      <Heart filled={liked} />
      <span className={styles.count}>{count}</span>
    </button>
  );
}

function Heart({ filled }: { filled: boolean }) {
  return (
    <svg
      className={`${styles.icon} ${filled ? styles.iconFilled : styles.iconOutline}`}
      viewBox="0 0 24 24"
      strokeWidth="1.5"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      suppressHydrationWarning
    >
      <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
    </svg>
  );
}

