"use client";

import { useEffect, useRef, useState, type CSSProperties } from "react";
import { useGSAP } from "@/lib/gsap";
import { pressFeedback } from "@/lib/pressFeedback";
import styles from "./ShareButton.module.css";

interface Props {
  title: string;
  text?: string;
  /** Falls back to window.location.href when omitted. */
  url?: string;
}

/**
 * Share / copy-link control. Uses the Web Share API when available
 * (mobile, modern browsers) and falls back to copying the URL to the
 * clipboard with a brief "Copied" confirmation.
 */
export default function ShareButton({ title, text, url }: Props) {
  const [copied, setCopied] = useState(false);
  // Holds the "revert from Copied → Share" timer so we can cancel it
  // on unmount. Without this, a user that navigates away before the
  // 1800ms elapsed triggers a setState on an unmounted component.
  const copiedTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (copiedTimerRef.current) clearTimeout(copiedTimerRef.current);
    };
  }, []);

  const onShare = async () => {
    const href = url ?? (typeof window !== "undefined" ? window.location.href : "");
    if (!href) return;

    if (typeof navigator !== "undefined" && "share" in navigator) {
      try {
        await navigator.share({ title, text, url: href });
        return;
      } catch {
        // User aborted or share failed — fall through to copy.
      }
    }

    try {
      await navigator.clipboard.writeText(href);
      setCopied(true);
      // Clear any prior revert in case the user spam-clicked Share.
      if (copiedTimerRef.current) clearTimeout(copiedTimerRef.current);
      copiedTimerRef.current = setTimeout(() => setCopied(false), 1800);
    } catch {
      // ignore — clipboard blocked
    }
  };

  return (
    <button
      type="button"
      onClick={() => void onShare()}
      className={styles.button}
      aria-label="Share this page"
    >
      <Glyph />
      <span>{copied ? "Copied" : "Share"}</span>
    </button>
  );
}

function Glyph() {
  return (
    <svg
      className={styles.icon}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.75"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      suppressHydrationWarning
    >
      <circle cx="18" cy="5" r="3" />
      <circle cx="6" cy="12" r="3" />
      <circle cx="18" cy="19" r="3" />
      <line x1="8.59" y1="13.51" x2="15.42" y2="17.49" />
      <line x1="15.41" y1="6.51" x2="8.59" y2="10.49" />
    </svg>
  );
}

