const onShareClick = async (target: ShareTarget, index: number) => {
  if (target.action.kind === "url") {
    window.open(target.action.url, "_blank", "noopener,noreferrer");
    dismiss();
    return;
  }
  try {
    await navigator.clipboard.writeText(target.action.payload);
    setCopiedIndex(index);
    setTimeout(() => setCopiedIndex(null), 1200);
  } catch {
    // Clipboard write may fail (focus loss, permission). Fail
    // silently — the user can re-select and retry. No toast on
    // this site by design.
  }
};

return (
  <div
    ref={popoverRef}
    className={styles.popover}
    role="toolbar"
    aria-label="Share selected quote"
    style={{
      top: `${position.top}px`,
      left: `${position.left}px`,
      // Block pointer-down propagation so clicking the popover
      // doesn't dismiss it via the outside-click handler before
      // the click resolves.
      pointerEvents: "auto",
    }}
    onPointerDown={(e) => {
      e.stopPropagation();
    }}
  >
    {targets.map((target, i) => {
      const isCopy = target.action.kind === "copy";
      const showCopied = isCopy && copiedIndex === i;
      return (
        <button
          key={target.label}
          type="button"
          className={`${styles.button} ${
            showCopied ? styles.buttonCopied : ""
          }`}
          aria-label={SHARE_ARIA[target.icon]}
          title={SHARE_ARIA[target.icon]}
          onClick={() => void onShareClick(target, i)}
        >
          {showCopied ? <CheckGlyph /> : <ShareGlyph id={target.icon} />}

