"use client";

import { useEffect, useRef, useState } from "react";
import type { Note, NoteColor } from "@/types";
import styles from "./NoteCard.module.css";

// The six colors offered in the picker. Order = display order in the
// swatch row. Each carries a visible label so color is never the only
// signal (a11y: color-not-only). The CSS module maps each value to a
// background via [data-color="…"].
export const NOTE_COLORS: { value: NoteColor; label: string }[] = [
  { value: "GOLD", label: "Gold" },
  { value: "CRIMSON", label: "Crimson" },
  { value: "SAGE", label: "Sage" },
  { value: "INDIGO", label: "Indigo" },
  { value: "AMBER", label: "Amber" },
  { value: "SLATE", label: "Slate" },
];

const AUTOSAVE_DEBOUNCE_MS = 600;

interface Props {
  note: Note;
  expanded: boolean;
  onExpand: () => void;
  onCollapse: () => void;
  /** Patch is sent after a short debounce when title/body change, and
   *  immediately when color changes. */
  onChange: (patch: { title?: string; body?: string; color?: NoteColor }) => void;
  onDelete: () => void;
}

/**
 * One note in the editor's NotesPanel.
 *
 * Collapsed: a pill — color dot + truncated title + 3-dot menu.
 * Expanded: title input + multi-line body textarea + 3-dot menu.
 *
 * Only one card is ever expanded in the panel at a time — the parent
 * tracks `expandedId`. Autosave is debounced per-field; color changes
 * patch immediately.
 */
export default function NoteCard({
  note,
  expanded,
  onExpand,
  onCollapse,
  onChange,
  onDelete,
}: Props) {
  // Local mirror so typing feels immediate. The server-side note may
  // arrive back with merged updates; we re-sync when the prop changes
  // and the local value matches what we last sent.
  const [title, setTitle] = useState(note.title);
  const [body, setBody] = useState(note.body);
  const [menuOpen, setMenuOpen] = useState(false);
  const lastSentTitle = useRef(note.title);
  const lastSentBody = useRef(note.body);
  const menuRef = useRef<HTMLDivElement>(null);

  // Re-sync from upstream when the server's idea of the note changes
  // (e.g., after a color change PATCH returns) AND we haven't typed
  // newer characters locally. Without this, the input would silently
  // revert; without the lastSent check, the user's in-flight edits
  // would be clobbered by the server echo.
  useEffect(() => {
    if (title === lastSentTitle.current) setTitle(note.title);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [note.title]);
  useEffect(() => {
    if (body === lastSentBody.current) setBody(note.body);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [note.body]);

  // Debounced PATCH for title.
  useEffect(() => {
    if (title === note.title) return;
    const t = setTimeout(() => {
      lastSentTitle.current = title;
      onChange({ title });
    }, AUTOSAVE_DEBOUNCE_MS);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [title]);

  // Debounced PATCH for body.
  useEffect(() => {
    if (body === note.body) return;
    const t = setTimeout(() => {
      lastSentBody.current = body;
      onChange({ body });
    }, AUTOSAVE_DEBOUNCE_MS);
    return () => clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [body]);

  // Close the menu on outside click / Esc.
  useEffect(() => {
    if (!menuOpen) return;
    const onPointer = (e: PointerEvent) => {
      const target = e.target as Node | null;
      if (target && menuRef.current?.contains(target)) return;
      setMenuOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setMenuOpen(false);
    };
    document.addEventListener("pointerdown", onPointer);
    window.addEventListener("keydown", onKey);
    return () => {
      document.removeEventListener("pointerdown", onPointer);
      window.removeEventListener("keydown", onKey);
    };
  }, [menuOpen]);

  const colorLabel =
    NOTE_COLORS.find((c) => c.value === note.color)?.label ?? "Gold";
  const displayTitle = title.trim() || "Untitled note";

  const menu = (
    <div ref={menuRef} className={styles.menuWrap}>
      <button
        type="button"
        onClick={(e) => {
          e.stopPropagation();
          setMenuOpen((v) => !v);
        }}
        className={styles.menuBtn}
        aria-label="Note actions"
        aria-haspopup="menu"
        aria-expanded={menuOpen}
      >
        <DotsGlyph />
      </button>
      {menuOpen && (
        <div role="menu" className={styles.menuPanel}>
          <p className={styles.menuLabel}>Color</p>
          <div className={styles.swatchRow}>
            {NOTE_COLORS.map((c) => (
              <button
                key={c.value}
                type="button"
                onClick={() => {
                  onChange({ color: c.value });
                  setMenuOpen(false);
                }}
                className={`${styles.swatch} ${
                  c.value === note.color ? styles.swatchActive : ""
                }`}
                data-color={c.value}
                aria-label={`Color: ${c.label}`}
                title={c.label}
              >
                {c.value === note.color && <CheckGlyph />}
              </button>
            ))}
          </div>
          <button
            type="button"
            role="menuitem"
            onClick={() => {
              setMenuOpen(false);
              onDelete();
            }}
            className={styles.deleteBtn}
          >
            Delete note
          </button>
        </div>
      )}
    </div>
  );

  if (!expanded) {
    return (
      <div
        className={`${styles.card} ${styles.collapsed}`}
        data-color={note.color}
        data-flip-id={note.id}
      >
        <button
          type="button"
          onClick={onExpand}
          className={styles.pillBody}
          aria-label={`Open note: ${displayTitle}. Color: ${colorLabel}`}
        >
          <span className={styles.dot} aria-hidden="true" />
          <span className={styles.pillTitle}>{displayTitle}</span>
        </button>
        {menu}
      </div>
    );
  }

  return (
    <div
      className={`${styles.card} ${styles.expanded}`}
      data-color={note.color}
    >
      <div className={styles.expandedHeader}>
        <button
          type="button"
          onClick={onCollapse}
          className={styles.collapseBtn}
          aria-label="Collapse note"
          title="Collapse"
        >
          <span className={styles.dot} aria-hidden="true" />
        </button>
        <input
          type="text"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          placeholder="Title"
          maxLength={120}
          className={styles.titleInput}
          aria-label="Note title"
        />
        {menu}
      </div>
      <textarea
        value={body}
        onChange={(e) => setBody(e.target.value)}
        placeholder="Note…"
        className={styles.bodyArea}
        rows={6}
        aria-label="Note body"
      />
    </div>
  );
}

function DotsGlyph() {
  return (
    <svg
      viewBox="0 0 24 24"
      width="16"
      height="16"
      fill="currentColor"
      aria-hidden="true"
      suppressHydrationWarning
    >
      <circle cx="5" cy="12" r="1.6" />
      <circle cx="12" cy="12" r="1.6" />
      <circle cx="19" cy="12" r="1.6" />
    </svg>
  );
}

function CheckGlyph() {
  return (
    <svg
      viewBox="0 0 24 24"
      width="12"
      height="12"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      suppressHydrationWarning
    >
      <polyline points="20 6 9 17 4 12" />
    </svg>
  );
}

