export default function NotesPanel({ storyId, chapterId }: Props) {
  const [notes, setNotes] = useState<Note[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [expandedId, setExpandedId] = useState<string | null>(null);
  const [mobileOpen, setMobileOpen] = useState(false);
  const [busy, setBusy] = useState(false);

  // ── Flip morph between pill and expanded card ─────────────
  // Each NoteCard renders two different DOM trees depending on
  // `expanded`, but both branches share the same `data-flip-id={id}`
  // so GSAP Flip can morph one shape into the other on swap.
  // listRef scopes the query so we only Flip notes in THIS panel.
  // flipStateRef stashes the snapshot from the click handler so the
  // useLayoutEffect below can replay it AFTER React commits the new
  // tree (the only point Flip.from can compute the delta).
  const listRef = useRef<HTMLDivElement>(null);
  const flipStateRef = useRef<ReturnType<typeof Flip.getState> | null>(null);

  const captureFlip = useCallback(() => {
    if (prefersReducedMotion()) return;
    const container = listRef.current;
    if (!container) return;
    const targets = container.querySelectorAll("[data-flip-id]");
    if (targets.length === 0) return;
    flipStateRef.current = Flip.getState(targets, {
      // borderRadius matters here — pill (radius-pill) vs expanded
      // (radius-md-app). props lets Flip interpolate them on top of
      // the position/size diff.
      props: "borderRadius,opacity",
    });
  }, []);

  // Replay the captured state AFTER React paints the new tree.
  // useLayoutEffect (not useEffect) so the user never sees the snap
  // before Flip kicks in.
  useLayoutEffect(() => {
    const state = flipStateRef.current;
    if (!state) return;
    flipStateRef.current = null;
    Flip.from(state, {
      duration: 0.4,
      ease: "power2.inOut",
      // absolute pulls morphing items out of flow during the tween so
      // siblings don't shove around them; simple keeps the layout
      // math cheap (no nested-flow recursion).
      absolute: true,
      simple: true,
      // Cards entering for the first time (e.g. a brand-new note
      // added at the bottom) fade up rather than morph from nowhere.
      onEnter: (els) =>
        gsap.fromTo(
          els,
          { opacity: 0, scale: 0.96 },
          { opacity: 1, scale: 1, duration: 0.25, ease: "power2.out" },
        ),
      // Cards leaving (rare here — only on note deletion) fade out
      // gently. Note: with the element-swap pattern, pill→expanded
      // transitions are NOT leave/enter, they're morphs (same flip-id).
      onLeave: (els) =>
        gsap.to(els, { opacity: 0, scale: 0.96, duration: 0.2 }),
    });
  }, [expandedId, notes.length]);

