.collapsed:hover {
  border-color: var(--note-color);
  /* The :hover lift (transform: translateY) used to live here, but
     it fights GSAP's transform writes from the Flip pill→expanded
     morph (T2) and the future T1 dock magnification. Glow stays —
     it's box-shadow, which GSAP doesn't touch. */
  box-shadow: 0 6px 14px -8px color-mix(in srgb, var(--note-color) 55%, transparent);
}
.collapsed:active {
  /* See above — no transform on press either. The Flip morph IS the
     press feedback now. */
  box-shadow: none;
}

