}
.collapsed:active {
  transform: translateY(0) scale(0.995);
  box-shadow: none;
}

.pillBody {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  flex: 1 1 auto;
  min-width: 0;
  background: transparent;
  border: 0;
  padding: 6px 0;
  font: inherit;
  color: var(--text);
  cursor: pointer;
  text-align: left;
}
.pillBody:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  border-radius: var(--radius-pill);
}

.dot {
  flex: 0 0 auto;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--note-color);
  box-shadow: 0 0 0 1px rgba(0, 0, 0, 0.35) inset;
}

.pillTitle {
  flex: 1 1 auto;
  min-width: 0;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.01em;
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Expanded card ─────────────────────────────────────────────── */
