  from {
    opacity: 0.4;
    transform: translateY(-3px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.expandedHeader {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 8px;
}

.collapseBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  background: transparent;
  border: 0;
  border-radius: var(--radius-pill);
  cursor: pointer;
  padding: 0;
  color: var(--text-muted);
  transition: background var(--transition-fast);
}
.collapseBtn:hover {
  background: var(--bg);
}
.collapseBtn:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}

.titleInput {
  flex: 1 1 auto;
  min-width: 0;
  background: transparent;
  border: 0;
  border-bottom: 1px solid transparent;
  padding: 4px 2px;
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 600;
  color: var(--text);
  outline: none;
  transition: border-color var(--transition-fast);
}
.titleInput::placeholder {
  color: var(--text-muted);
  font-weight: 500;
  font-style: italic;
}
.titleInput:focus {
  border-bottom-color: var(--note-color);
}

.bodyArea {
  width: 100%;
