}

@keyframes menuPop {
  from {
    opacity: 0;
    transform: translateY(-4px) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.menuLabel {
  margin: 0;
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--text-muted);
}

.swatchRow {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 6px;
}

.swatch {
  width: 22px;
  height: 22px;
  border-radius: 50%;
  border: 2px solid transparent;
  cursor: pointer;
  padding: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: rgba(0, 0, 0, 0.85);
  transition: transform var(--transition-fast), border-color var(--transition-fast);
}
.swatch[data-color="GOLD"]    { background: var(--gold); }
.swatch[data-color="CRIMSON"] { background: #c4584c; }
.swatch[data-color="SAGE"]    { background: #7fa17b; }
.swatch[data-color="INDIGO"]  { background: #7e8ed1; }
.swatch[data-color="AMBER"]   { background: #d99a4a; }
.swatch[data-color="SLATE"]   { background: #8a8e97; }
.swatch:hover {
  transform: scale(1.08);
}
.swatch:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 2px;
}
.swatchActive {
  border-color: var(--text);
}

.deleteBtn {
  background: transparent;
  border: 1px solid var(--border-line);
  border-radius: var(--radius-md-app);
  padding: 7px 10px;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.04em;
  color: var(--like);
  cursor: pointer;
  text-align: left;
  transition: background var(--transition-fast), border-color var(--transition-fast);
}
.deleteBtn:hover {
  background: var(--bg);
  border-color: var(--like);
}
.deleteBtn:focus-visible {
  outline: 2px solid var(--like);
  outline-offset: 2px;
}

/* Respect the OS-level "Reduce Motion" preference — keep the visual
   states but drop the motion. The codebase already honors this in
   the GSAP morphs in SiteHeader; mirror that here. */
@media (prefers-reduced-motion: reduce) {
