  .collapsed,
  .expanded,
  .menuPanel,
  .collapseBtn,
  .menuBtn,
  .swatch {
    animation: none !important;
    transition: none !important;
  }
  .collapsed:hover,
  .collapsed:active {
    transform: none;
    box-shadow: none;
  }
}

