"use client";

// ============================================================
// useMagneticDock — macOS-dock-style cursor-proximity magnification
// for any container of card-like items.
// ============================================================
//
// Attaches a single pointermove listener to `containerRef.current`,
// loops over `[data-dock-item]` descendants on every move, and tweens
// scale + a tiny orthogonal-axis lift in proportion to cursor
// distance via `gsap.quickTo` setters (pre-baked for throughput).
// On pointerleave, all items glide back to rest.
//
// Mirrors the canonical https://demos.gsap.com/demo/macos-dock-effect/
// pattern (one listener on the container, distance + falloff math
// inline). All bookkeeping is auto-cleaned by `useGSAP`'s
// `context.revert()` on unmount; the explicit cleanup return strips
// the DOM listeners + the ResizeObserver.
//
// Bails on:
//   - prefers-reduced-motion (no listeners attached)
//   - touch / coarse-pointer devices (proximity needs a cursor)
//   - empty containers (no `[data-dock-item]` found)

import { type RefObject } from "react";
import { gsap, prefersReducedMotion, useGSAP } from "./gsap";

export interface MagneticDockOptions {
  /** px of influence on either side of the cursor. Beyond this the
   *  item is at rest scale (1) and zero lift. */
  radius?: number;
  /** Peak scale at distance 0 (i.e. cursor centered on the item). */
  maxScale?: number;
  /** Pixels the item travels along the orthogonal axis at distance 0.
   *  Used as `-y` for horizontal rails (items rise like real dock
   *  icons) and `-x` for vertical lists (items shift toward the
   *  cursor side). Set to 0 to disable. */
  maxLift?: number;
  /** Which axis measures cursor distance — 'x' for horizontal rails,
   *  'y' for vertical lists. */
  axis?: "x" | "y";
}

const DEFAULTS: Required<MagneticDockOptions> = {
  radius: 200,
  maxScale: 1.4,
  maxLift: 12,
  axis: "x",
};

export function useMagneticDock(
  containerRef: RefObject<HTMLElement | null>,
  opts: MagneticDockOptions = {},
  deps: unknown[] = [],
) {
  const { radius, maxScale, maxLift, axis } = { ...DEFAULTS, ...opts };

  useGSAP(
    () => {
      if (prefersReducedMotion()) return;
      // No cursor on touch devices — magnification would either get
      // stuck on the last touch point or never engage at all.
      if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
        return;
      }

      const container = containerRef.current;
      if (!container) return;

      const items = Array.from(
        container.querySelectorAll<HTMLElement>("[data-dock-item]"),
      );
      if (items.length === 0) return;

      // Cards from CardGrid have a `transition: transform var(--transition-fast)`
      // baked in for their CSS hover. That transition will re-ease every
      // GSAP quickTo write and produce ugly jitter — kill the transform
      // transition specifically on these elements while the dock owns them.
      const prevTransitions: string[] = items.map((el) => el.style.transition);
      items.forEach((el) => {
        // Keep any non-transform transitions (border-color etc.) by
        // overriding only `transform`. Empty string here removes inline
        // override on cleanup, letting the CSS rule take back over.
        el.style.transition = "border-color var(--transition-fast)";
      });

      const liftAxis: "x" | "y" = axis === "x" ? "y" : "x";

      // Pre-bake setters so each pointermove tick doesn't allocate a
      // tween. quickTo collapses repeated writes into one continuing
      // tween (the "snappy follow-cursor" feel).
      const setters = items.map((el) => ({
        scale: gsap.quickTo(el, "scale", {
          duration: 0.3,
          ease: "power2.out",
        }),
        lift: gsap.quickTo(el, liftAxis, {
          duration: 0.3,
          ease: "power2.out",
        }),
      }));

      let centers: number[] = [];
      const measure = () => {
        centers = items.map((el) => {
          const r = el.getBoundingClientRect();
          return axis === "x" ? r.left + r.width / 2 : r.top + r.height / 2;
        });
      };
      // Double-rAF — CardGrid's stagger reveal may still be animating
      // y/opacity at first paint, and a too-early measure would catch
      // pre-final positions. By the second frame the layout has settled.
      const raf1 = requestAnimationFrame(() => {
        const raf2 = requestAnimationFrame(measure);
        // No need to track raf2 separately for cleanup — the cancelAnimationFrame
        // below covers raf1, and the inner one is already scheduled.
        void raf2;
      });

      const ro = new ResizeObserver(measure);
      ro.observe(container);
      window.addEventListener("resize", measure);

      const onMove = (e: PointerEvent) => {
        const cursor = axis === "x" ? e.clientX : e.clientY;
        for (let i = 0; i < items.length; i++) {
          const dist = Math.abs(cursor - centers[i]);
          const t = Math.max(0, 1 - dist / radius);
          setters[i].scale(1 + t * (maxScale - 1));
          if (maxLift !== 0) setters[i].lift(-t * maxLift);
        }
      };

      const onLeave = () => {
        gsap.to(items, {
          scale: 1,
          [liftAxis]: 0,
          duration: 0.5,
          ease: "power3.out",
          overwrite: "auto",
        });
      };

      container.addEventListener("pointermove", onMove);
      container.addEventListener("pointerleave", onLeave);

      return () => {
        cancelAnimationFrame(raf1);
        container.removeEventListener("pointermove", onMove);
        container.removeEventListener("pointerleave", onLeave);
        window.removeEventListener("resize", measure);
        ro.disconnect();
        // Restore the original `transition` style so any CSS-driven
        // transform transitions (none today, but defensive) come back.
        items.forEach((el, i) => {
          el.style.transition = prevTransitions[i];
        });
      };
    },
    { scope: containerRef, dependencies: deps },
  );
}

