.card {
  display: flex;
  flex-direction: column;
  /* Fixed dimensions across every story / chapter / series card on
     the public site. Excerpt block has its own locked height; the
     tag row caps to one line via a +N overflow chip; footer pinned
     to the bottom via margin-top: auto. CardGrid.module.css
     overrides width to 100% so cards still stretch to fill grid
     cells inside an .grid container — only the horizontal-scroll
     rows render at the literal 320px below. */
  height: 300px;
  width: 320px;
  flex-shrink: 0;
  padding: var(--pad-card);
  border-radius: var(--radius-lg-app);
  border: 1px solid var(--border-line);
  background: var(--bg-surface);
  transition:
    transform var(--transition-fast),
    border-color var(--transition-fast);
  text-decoration: none;
  color: inherit;
}
.card:hover {
  transform: translateY(-2px);
  border-color: var(--border-line-hover);
}

/* Cards for adult content get the red treatment.
   Tinted top + a more saturated border the user can read at a distance. */
.cardAdult {
  border-color: rgba(224, 123, 123, 0.32);
}
.cardAdult:hover {
  border-color: rgba(224, 123, 123, 0.55);
}

/* ── Layout regions ─────────────────────────────────────────────
   1. Title              (top, fixed line clamp)
   2. Tags row           (just below title)
   3. Excerpt            (3-line clamp; reserves height when empty)
   4. Footer (date, likes)
*/

.title {
  font-family: var(--font-display);
  font-size: var(--fs-card-title);
  line-height: var(--lh-card-title);
  color: var(--text);
  margin: 0;
  font-weight: 600;
  /* Two lines max so card heights stay matched */
  display: -webkit-box;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  min-height: calc(var(--fs-card-title) * var(--lh-card-title) * 2);
}

.tags {
  display: flex;
  gap: 6px;
  /* Single-line strip — anything past the first two tags collapses
     into a +N chip, so the row is always exactly one line tall. */
  flex-wrap: nowrap;
  align-items: center;
  margin-top: 10px;
  /* Always reserve a row's height even when no tags exist so cards
     line up across rows */
  min-height: 22px;
  overflow: hidden;
}

/* Overflow chip — counts tags beyond the first two. Sits at the end
   of the tag row in the muted color so it reads as a label, not a
   pill. */
.tagMore {
  font-family: var(--font-ui);
  font-size: var(--fs-tag);
  font-weight: 500;
  letter-spacing: var(--tracking-tag);
  text-transform: uppercase;
  color: var(--text-muted);
  white-space: nowrap;
  flex-shrink: 0;
}

.excerpt {
  font-family: var(--font-reading);
  font-size: 14px;
  line-height: 1.5;
  color: var(--text-muted);
  margin: 12px 0 0;
  display: -webkit-box;
  -webkit-line-clamp: 3;
  line-clamp: 3;
  -webkit-box-orient: vertical;
  overflow: hidden;
  /* Lock the excerpt block to exactly three line heights so cards with
     empty / short excerpts still take the same vertical space. */
  height: calc(14px * 1.5 * 3);
}

.footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 12px;
  margin-top: auto;
  border-top: 1px solid var(--border-line);
  font-family: var(--font-ui);
  font-size: var(--fs-meta);
  color: var(--text-muted);
}

.likes {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.likeIcon {
  width: 12px;
  height: 12px;
  display: inline-block;
  color: var(--text-muted);
}

/* ── Series-card extras ─────────────────────────────────────── */

.seriesLabel {
  font-family: var(--font-ui);
  font-size: var(--fs-tag);
  font-weight: 500;
  letter-spacing: var(--tracking-tag);
  text-transform: uppercase;
  color: var(--gold);
  margin: 0 0 8px;
}

.statusComplete {
  color: var(--published);
}

.statusHiatus {
  color: var(--text-muted);
}

.partLabel {
  font-family: var(--font-ui);
  font-size: var(--fs-tag);
  font-weight: 500;
  letter-spacing: var(--tracking-tag);
  text-transform: uppercase;
  color: var(--gold);
  margin: 0;
}

.latestChapter {
  font-family: var(--font-ui);
  font-size: var(--fs-meta);
  color: var(--text-muted);
  font-style: italic;
  margin: 8px 0 0;
}

import Link from "next/link";
import InlineRichText from "@/components/InlineRichText";
import TagPill from "@/components/TagPill";
import type { StoryCard as StoryCardType } from "@/types";
import styles from "./StoryCard.module.css";

interface Props {
  story: StoryCardType;
}

const dateFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
});

function formatDate(isoString: string | null): string {
  if (!isoString) return "Draft";
  return dateFormatter.format(new Date(isoString));
}

function pluralize(n: number, singular: string, plural = `${singular}s`) {
  return `${n} ${n === 1 ? singular : plural}`;
}

export default function StoryCard({ story }: Props) {
  return (
    <Link
      href={`/story/${story.id}`}
      className={`${styles.card} ${story.isAdult ? styles.cardAdult : ""}`}
      data-tag-ids={story.tags.map((t) => t.id).join(" ")}
    >
      {/* 1. Title */}
      <h4 className={styles.title}>{story.title}</h4>

      {/* 2. Tags — first two render as pills; anything past that
            collapses into a +N chip so the row stays one line and
            every card on the site is the same height. Inert
            because the card root is already a Link; nested <a>
            isn't valid HTML. */}
      <div className={styles.tags}>
        {story.tags.slice(0, 2).map((tag) => (
          <TagPill key={tag.id} tag={tag} linkable={false} />
        ))}
        {story.tags.length > 2 && (
          <span className={styles.tagMore}>+{story.tags.length - 2}</span>
        )}
      </div>

      {/* 3. Excerpt — height locked even when empty */}
      <InlineRichText content={story.excerpt} className={styles.excerpt} />

      {/* 4. Footer */}
      <div className={styles.footer}>
        <span>{formatDate(story.publishedAt)}</span>
        <span className={styles.likes}>
          <HeartGlyph />
          {pluralize(story.likeCount, "like")}
        </span>
      </div>
    </Link>
  );
}

