"use client";

import Link from "next/link";
import type { ContinueReadingItem } from "@/lib/api";
import styles from "./ContinueCard.module.css";

interface Props {
  item: ContinueReadingItem;
  onRemove: () => void;
}

/**
 * Single card in the "Pick up where you left off" row. Combines:
 *   - Link to the chapter/story (optionally with `?page=N` so the
 *     paged reader lands on the same page the visitor was on).
 *   - "{percent}% read" badge and chapter / series subtitle.
 *   - Small X button that fires `onRemove()` — the parent does the
 *     optimistic UI removal + the DELETE.
 *
 * Kept presentational; all of the state + the API call live one
 * level up in `ResumeReadingRow`.
 */
export default function ContinueCard({ item, onRemove }: Props) {
  const isChapter = item.contentType === "chapter";
  const href =
    item.pageNumber && item.pageNumber > 1
      ? `/${item.contentType}/${item.id}?page=${item.pageNumber}`
      : `/${item.contentType}/${item.id}`;
  const percent = Math.max(0, Math.min(100, Math.round(item.scrollPercentage)));

  return (
    <article className={styles.card}>
      <Link href={href} className={styles.link}>
        {isChapter && item.orderIndex !== undefined && (
          <span className={styles.partLabel}>Part {item.orderIndex}</span>
        )}
        <span className={styles.title}>{item.title}</span>
        {isChapter && item.series && (
          <span className={styles.seriesTitle}>{item.series.title}</span>
        )}
        <span className={styles.badge}>
          {/* The chapter/page metadata lives in the link's main text;
              the badge focuses on the % read so it reads as a "where
              you stopped" hint, not a duplicate title. */}
          <span className={styles.badgePct}>{percent}%</span> read
        </span>
      </Link>
      <button
        type="button"
        onClick={(e) => {
          // The button is positioned absolutely on top of the link
          // — the bubble would still hit the <Link>'s click handler
          // and navigate the reader away.
          e.preventDefault();
          e.stopPropagation();
          onRemove();
        }}
        className={styles.remove}
        aria-label={`Remove ${item.title} from continue reading`}
      >
        <XIcon />
      </button>
    </article>
  );
}

function XIcon() {
  return (
    <svg
      viewBox="0 0 24 24"
      width="12"
      height="12"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      suppressHydrationWarning
    >
      <line x1="18" y1="6" x2="6" y2="18" />
      <line x1="6" y1="6" x2="18" y2="18" />
    </svg>
  );
}

