"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import { listProgress, type ProgressEntry } from "@/lib/readingProgress";
import styles from "./ContinueReadingRow.module.css";

/**
 * Homepage section that lists the series the reader is mid-way
 * through, sorted most-recent first. Renders nothing if there's no
 * stored progress yet, so first-time visitors see the regular feed
 * straight away.
 */
export default function ContinueReadingRow({ limit = 6 }: { limit?: number }) {
  const [entries, setEntries] = useState<ProgressEntry[] | null>(null);

  useEffect(() => {
    setEntries(listProgress().slice(0, limit));
  }, [limit]);

  // Server render + first paint while we read localStorage — both
  // produce nothing so there's no layout flicker.
  if (!entries || entries.length === 0) return null;

  return (
    <section className={styles.section} aria-label="Continue reading">
      <header className={styles.header}>
        {/* h2 mirrors the level used by sibling homepage sections
            (ExpandableSection) so the document outline reads
            "Continue reading / New stories / Most read / ..." at the
            same heading rank. */}
        <h2 className={styles.title}>Continue reading</h2>
      </header>
      <ul className={styles.list}>
        {entries.map((entry) => (
          <li key={entry.seriesId}>
            <Link
              href={`/chapter/${entry.chapterId}`}
              className={styles.card}
            >
              <span className={styles.partLabel}>
                Part {entry.chapterOrderIndex}
              </span>
              <span className={styles.chapterTitle}>{entry.chapterTitle}</span>
              <span className={styles.seriesTitle}>{entry.seriesTitle}</span>
            </Link>
          </li>
        ))}
      </ul>
    </section>
  );
}

