"use client";

import { useRef, type ReactNode } from "react";
import { useMagneticDock } from "@/lib/useMagneticDock";

interface Props {
  children: ReactNode;
  className?: string;
}

/**
 * Thin "use client" wrapper around the homepage hero's "Latest
 * entries" card column. Needed because frontend/app/page.tsx is a
 * server component (exports metadata) and so can't host the
 * pointermove + GSAP listeners. The cards themselves stay
 * server-rendered — they're passed in as `children`.
 *
 * Vertical column → axis='y', no lift (a full-width-ish card lifting
 * horizontally looks weird), conservative scale so the column doesn't
 * bulge under the cursor.
 */
export default function HeroCardsList({ children, className }: Props) {
  const ref = useRef<HTMLDivElement>(null);
  useMagneticDock(ref, { axis: "y", maxScale: 1.06, maxLift: 0 });
  return (
    <div ref={ref} className={className}>
      {children}
    </div>
  );
}

