"use client";

import Link from "next/link";
import { useMemo, useState } from "react";
import InlineRichText from "@/components/InlineRichText";
import ReadTime from "@/components/ReadTime";
import type { SeriesDetail } from "@/types";
import styles from "./ChapterList.module.css";

type Chapter = SeriesDetail["chapters"][number];

type SortKey = "chapter" | "newest" | "oldest";

const SORT_OPTIONS: { key: SortKey; label: string }[] = [
  { key: "chapter", label: "Chapter #" },
  { key: "newest", label: "Newest" },
  { key: "oldest", label: "Oldest" },
];

const dateFormatter = new Intl.DateTimeFormat("en-US", {
  month: "short",
  day: "numeric",
  year: "numeric",
});

export default function ChapterList({ chapters }: { chapters: Chapter[] }) {
  const [sort, setSort] = useState<SortKey>("chapter");

  const sorted = useMemo(() => {
    const arr = [...chapters];
    switch (sort) {
      case "chapter":
        arr.sort((a, b) => a.orderIndex - b.orderIndex);
        break;
      case "newest":
        arr.sort(
          (a, b) =>
            new Date(b.publishedAt).getTime() -
            new Date(a.publishedAt).getTime(),
        );
        break;
      case "oldest":
        arr.sort(
          (a, b) =>
            new Date(a.publishedAt).getTime() -
            new Date(b.publishedAt).getTime(),
        );
        break;
    }
    return arr;
  }, [chapters, sort]);

  if (chapters.length === 0) {
    return <p className={styles.empty}>No chapters yet.</p>;
  }

  return (
    <>
      <div className={styles.toolbar}>
        <span className={styles.sortLabel}>Sort by</span>
        <div className={styles.sortGroup} role="radiogroup" aria-label="Sort">
          {SORT_OPTIONS.map((opt) => (
            <button
              key={opt.key}
              type="button"
              role="radio"
              aria-checked={sort === opt.key}
              onClick={() => setSort(opt.key)}
              className={`${styles.sortPill} ${
                sort === opt.key ? styles.sortPillActive : ""
              }`}
            >
              {opt.label}
            </button>
          ))}
        </div>
      </div>

      <ol className={styles.list}>
        {sorted.map((chapter) => (
          <li key={chapter.id}>
            <Link
              href={`/chapter/${chapter.id}`}
              className={styles.row}
            >
              <span className={styles.partNum} aria-label={`Chapter ${chapter.orderIndex}`}>
                {chapter.orderIndex}
              </span>
              <div className={styles.body}>
                <p className={styles.title}>{chapter.title}</p>
                <InlineRichText
                  content={chapter.excerpt}
                  className={styles.excerpt}
                />
                <div className={styles.meta}>
                  <span className={styles.metaTime}>
                    <ClockIcon />
                    <ReadTime baseMinutes={chapter.estimatedReadMinutes} />
                  </span>
                  <span className={styles.metaDot} aria-hidden="true">
                    ·
                  </span>
                  <span className={styles.metaDate}>
                    {dateFormatter.format(new Date(chapter.publishedAt))}
                  </span>
                  <span className={styles.metaDot} aria-hidden="true">
                    ·
                  </span>
                  <span className={styles.metaLikes}>
                    <HeartIcon />
                    {chapter.likeCount}
                  </span>
                </div>
              </div>
            </Link>
          </li>
        ))}
      </ol>
    </>
  );
}

function ClockIcon() {
  return (
    <svg
      className={styles.metaIcon}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.75"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      suppressHydrationWarning
    >
      <circle cx="12" cy="12" r="9" />
      <polyline points="12 7 12 12 15 14" />
    </svg>
  );
}

function HeartIcon() {
  return (
    <svg
      className={styles.metaIcon}
      viewBox="0 0 24 24"
      fill="currentColor"
      stroke="none"
      aria-hidden="true"
      suppressHydrationWarning
    >
      <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
    </svg>
  );
}

