  // rather than a literal macOS dock magnification (which is wrong
  // for full-width lists). deps:[sort] re-measures centers when the
  // user changes sort order and rows rearrange.
  useMagneticDock(
    listRef,
    { axis: "y", radius: 140, maxScale: 1.04, maxLift: 0 },
