// ============================================================
// flipBridge — module-level snapshot store that carries GSAP Flip
// state across a Next.js App Router navigation.
// ============================================================
//
// Why this exists: tag-filter navigations on /search and /browse hit
// the server (URL params change → server component re-renders → DOM
// tree is REPLACED). Flip needs the same `[data-flip-id]` elements'
// positions at two points in time — one before the navigation, one
// after — but those elements are different DOM nodes by the time the
// new tree mounts.
//
// Pattern: TagBar's click handler snapshots Flip.getState BEFORE
// router.push(). The snapshot lives in this module-level Map. When
// the new CardGrid mounts on the destination page, it drains the
// snapshot by its `flipKey` and runs Flip.from(state, …).
//
// Safety:
//  - Each entry has a TTL (default 1.5s). Even without explicit
//    cleanup, stale snapshots auto-purge — so a stuck navigation or
//    a missing drain never poisons the next interaction.
//  - drain() removes the entry on access, so two consecutive grid
//    mounts can't both apply the same snapshot.
//  - Feature-flagged at the call site (NEXT_PUBLIC_FLIP_TAG_FILTER)
//    so the whole code path is dormant unless explicitly enabled.

import type { Flip } from "gsap/Flip";

type FlipState = ReturnType<typeof Flip.getState>;

const TTL_MS = 1500;

interface Entry {
  state: FlipState;
  expiresAt: number;
}

// Module-level — survives across React renders within the same SPA
// session. Cleared by TTL on drain; survives HMR best-effort (Next
// 16 / Turbopack swaps the module on edit, so the new module starts
// with an empty Map).
const bridge = new Map<string, Entry>();

/**
 * Store a Flip snapshot. Overwrites any prior entry under the same
 * key — only the most recent capture is meaningful.
 */
export function snapshotFlip(key: string, state: FlipState): void {
  bridge.set(key, { state, expiresAt: Date.now() + TTL_MS });
}

/**
 * Retrieve AND remove a snapshot. Returns null if absent or expired.
 */
export function drainFlip(key: string): FlipState | null {
  const entry = bridge.get(key);
  if (!entry) return null;
  bridge.delete(key);
  if (Date.now() > entry.expiresAt) return null;
  return entry.state;
}

/**
 * Clear all snapshots. Exported for tests / HMR plumbing; production
 * code shouldn't need to call this.
 */
export function clearFlipBridge(): void {
  bridge.clear();
}

/**
 * Build the canonical bridge key from a CardGrid's `flipKey` (e.g.
 * "search:stories") and the destination tagIds. Including tagIds in
 * the key prevents a snapshot taken for one filter from leaking into
 * a navigation with a different filter — defence in depth alongside
 * the TTL.
 */
export function flipBridgeKey(flipKey: string, tagIds?: string[]): string {
  const ids = tagIds && tagIds.length > 0 ? [...tagIds].sort().join(",") : "all";
  return `${flipKey}|${ids}`;
}

/**
 * Convenience flag — single source of truth for whether T5 is on.
 * Reads NEXT_PUBLIC_FLIP_TAG_FILTER at build time (Next inlines it).
 * Falsy by default so shipping this code to prod is a no-op.
 */
export function isFlipTagFilterEnabled(): boolean {
  return process.env.NEXT_PUBLIC_FLIP_TAG_FILTER === "1";
}

