import { useRef } from "react";
import { gsap, prefersReducedMotion, useGSAP } from "@/lib/gsap";
import { useMagneticDock } from "@/lib/useMagneticDock";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import styles from "./CardGrid.module.css";

/**
 * Grid wrapper for sections that should fill the container width
 * (auto-fill, minmax(280px, 1fr)). Same GSAP stagger reveal as CardRow
 * so the visual rhythm matches.
 */
export default function CardGrid({ children }: { children: React.ReactNode }) {
  const containerRef = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (!containerRef.current) return;
      if (prefersReducedMotion()) return;
      const cards = Array.from(containerRef.current.children);
      if (cards.length === 0) return;

      gsap.from(cards, {
        opacity: 0,
        y: 30,
        stagger: 0.08,
        duration: 0.5,
        ease: "power2.out",
        scrollTrigger: {
          trigger: containerRef.current,
          start: "top 85%",
          once: true,
        },
      });
    },
    { scope: containerRef },
  );

  void ScrollTrigger;

  // Magnetic-dock proximity magnification on cursor move. The hook
  // gates itself off on touch / reduced-motion, so this is a no-op
  // on those surfaces. Uses default tuning (radius 200, scale 1.4,
  // lift 12, axis 'x') — same params across every dock surface so
  // the public site feels consistent.
  useMagneticDock(containerRef);

  return (
    <div ref={containerRef} className={styles.grid}>
      {children}
    </div>
  );
}

