"use client";

import { useRef } from "react";
import { Flip, gsap, prefersReducedMotion, useGSAP } from "@/lib/gsap";
import {
  drainFlip,
  flipBridgeKey,
  isFlipTagFilterEnabled,
} from "@/lib/flipBridge";
import { useMagneticDock } from "@/lib/useMagneticDock";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import styles from "./CardGrid.module.css";

interface Props {
  children: React.ReactNode;
  /**
   * Stable per-grid identifier used to look up Flip snapshots
   * captured by TagBar before a tag-filter navigation (T5). The
   * convention is `${pagePath}:${section}`, e.g. `search:stories`
   * or `browse:series`. Parents that don't participate in T5 can
   * omit this prop entirely.
   */
  flipKey?: string;
  /** Optional currently-active tag ids — folded into the bridge
   *  lookup key so a snapshot taken for filter A can't apply to a
   *  filter-B remount that happens to share the same flipKey. */
  flipTagIds?: string[];
}

/**
 * Grid wrapper for sections that should fill the container width
 * (auto-fill, minmax(280px, 1fr)). Layers three GSAP behaviours on
 * the same elements:
 *   1. Flip morph from a pre-captured snapshot (T5 — feature-flagged).
 *   2. Scroll-triggered entrance stagger (the original behavior).
 *   3. Magnetic-dock proximity hover (T1).
 *
 * (1) and (2) are mutually exclusive — when a Flip snapshot drains
 * for this grid, the entrance reveal is skipped (the Flip morph is
 * the entrance). Each Flip from-state lookup is scoped by `flipKey`
 * so multiple CardGrids on the same page (e.g. /search renders
 * Stories + Series) don't share snapshots.
 */
export default function CardGrid({ children, flipKey, flipTagIds }: Props) {
  const containerRef = useRef<HTMLDivElement>(null);

  useGSAP(
    () => {
      if (!containerRef.current) return;
      if (prefersReducedMotion()) return;
      const cards = Array.from(
        containerRef.current.querySelectorAll<HTMLElement>("[data-flip-id]"),
      );
      if (cards.length === 0) return;

      // T5 path: did a TagBar click just snapshot Flip state for us?
      if (flipKey && isFlipTagFilterEnabled()) {
        const state = drainFlip(flipBridgeKey(flipKey, flipTagIds));
        if (state) {
          Flip.from(state, {
            duration: 0.55,
            ease: "power2.inOut",
            // absolute lifts morphing items out of flow so siblings
            // don't shove around them mid-tween; simple skips the
            // expensive nested-flow recursion.
            absolute: true,
            simple: true,
            // Cards new to this filter result fade up; departing
            // cards (handled by the OLD grid before unmount) get
            // their own treatment via TagBar's snapshot.
            onEnter: (els) =>
              gsap.fromTo(
                els,
                { opacity: 0, scale: 0.94 },
                { opacity: 1, scale: 1, duration: 0.35, ease: "power2.out" },
              ),
            onLeave: (els) =>
              gsap.to(els, { opacity: 0, scale: 0.94, duration: 0.25 }),
          });
          // Flip IS the entrance — skip the scroll-stagger reveal.
          return;
        }
      }

      // Default path: scroll-triggered entrance stagger.
      gsap.from(cards, {
        opacity: 0,
        y: 30,
        stagger: 0.08,
        duration: 0.5,
        ease: "power2.out",
        scrollTrigger: {
          trigger: containerRef.current,
          start: "top 85%",
          once: true,
        },
      });
    },
    { scope: containerRef },
  );

  void ScrollTrigger;

  // Magnetic-dock proximity magnification on cursor move. The hook
  // gates itself off on touch / reduced-motion, so this is a no-op
  // on those surfaces.
  useMagneticDock(containerRef);

  return (
    <div
      ref={containerRef}
      className={styles.grid}
      data-flip-grid={flipKey}
    >
      {children}
    </div>
  );
}

