"use client";

import Link from "next/link";
import { useEffect, useMemo, useRef, useState } from "react";
import type { Tag } from "@/types";
import styles from "./TagBar.module.css";

/**
 * Tracks which edges of the horizontal-scroll tag row have content
 * past them, so the CSS can fade the appropriate edge(s). Returns
 * "none" when the row fits without scrolling, and "start" / "middle"
 * / "end" when it overflows — start = at the leftmost position
 * (only right edge has more), middle = both, end = scrolled to the
 * end (only left edge has more).
 */
function useScrollEdges(ref: React.RefObject<HTMLDivElement | null>) {
  const [edge, setEdge] = useState<"none" | "start" | "middle" | "end">("start");

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const update = () => {
      // Re-read from the ref each call rather than relying solely on
      // the captured `el`. If the DOM element is detached between
      // listener registration and the next event, this stays safe
      // instead of dereferencing a node that's no longer in the tree.
      const current = ref.current;
      if (!current) return;
      // 1-px tolerance for sub-pixel scroll positions.
      if (current.scrollWidth <= current.clientWidth + 1) {
        setEdge("none");
        return;
      }
      const atStart = current.scrollLeft <= 1;
      const atEnd =
        current.scrollLeft + current.clientWidth >= current.scrollWidth - 1;
      if (atStart) setEdge("start");
      else if (atEnd) setEdge("end");
      else setEdge("middle");
    };

    update();
    el.addEventListener("scroll", update, { passive: true });
    // Resize can change whether the row overflows at all.
    window.addEventListener("resize", update);
    return () => {
      el.removeEventListener("scroll", update);
      window.removeEventListener("resize", update);
    };
  }, [ref]);

  return edge;
}

interface Props {
  tags: Tag[];
  /** Active tag ids — these get the gold-stroke active state */
  activeIds?: string[];
  /** Base href for tag links (e.g., "/search") */
  basePath?: string;
  /** Existing search query to preserve when clicking tags */
  search?: string;
  /** Threshold below which the toggle button stays hidden */
  expandThreshold?: number;
}

/**
 * Tag filter bar.
 *
 * Default: single-line horizontal scroll with a fade on the right edge.
 * Expanded: tags are grouped by their first letter (A, B, C...) so a
 * 500-tag taxonomy stays browseable. Each letter is a row with the
 * letter on the left and pills wrapping to the right.
 *
 * Color rules:
 *   - safe tag (isAdult = false)  -> green pill
 *   - adult tag (isAdult = true)  -> red pill
 *   - selected (active) tag       -> gold border, regardless
 */
