export default function TagBar({
  tags,
  activeIds,
  basePath = "/search",
  search,
  expandThreshold = 12,
}: Props) {
  const router = useRouter();
  const [expanded, setExpanded] = useState(false);
  const activeSet = useMemo(() => new Set(activeIds ?? []), [activeIds]);
  const showToggle = tags.length > expandThreshold;

  /**
   * T5 — Flip-bridge click interception. When NEXT_PUBLIC_FLIP_TAG_FILTER
   * is enabled, intercept the Link click, snapshot every CardGrid on
   * the page via Flip.getState (keyed by their data-flip-grid + the
   * destination tagIds), then hand the navigation off to the router.
   * The destination CardGrid will drain its snapshot on mount and run
   * Flip.from. Falls through to default Link nav when the flag is
   * off — code path is dormant.
   */
  const onTagNav = useCallback(
    (href: string) => (e: React.MouseEvent<HTMLAnchorElement>) => {
      if (!isFlipTagFilterEnabled()) return;
      // Honor modifier-clicks (open in new tab, etc.) — only intercept
      // a plain left-click.
      if (
        e.metaKey ||
        e.ctrlKey ||
        e.shiftKey ||
        e.altKey ||
        e.button !== 0
      ) {
        return;
      }
      e.preventDefault();
      // Parse the destination tagIds out of the href so the bridge
      // key matches what the CardGrid will compute on the other side.
      let nextTagIds: string[] = [];
      try {
        const url = new URL(href, window.location.origin);
        nextTagIds = url.searchParams.getAll("tagIds");
      } catch {
        // Malformed href shouldn't crash the click; fall through.
      }
      // Snapshot every CardGrid currently rendered. Each grid keys
      // its snapshot by its own data-flip-grid + nextTagIds so a
      // single navigation can carry multiple snapshots (e.g.
      // /search renders a Stories grid + a Series grid).
      const grids = document.querySelectorAll<HTMLElement>("[data-flip-grid]");
      grids.forEach((grid) => {
        const flipKey = grid.dataset.flipGrid;
        if (!flipKey) return;
        const items = grid.querySelectorAll("[data-flip-id]");
        if (items.length === 0) return;
        const state = Flip.getState(items, {
          props: "opacity,borderRadius",
        });
        snapshotFlip(flipBridgeKey(flipKey, nextTagIds), state);
      });
      router.push(href);
    },
    [router],
  );

