import type { Metadata } from "next";
import CardGrid from "@/components/CardGrid";
import { SeriesCard } from "@/components/SeriesCard";
import SiteHeader from "@/components/SiteHeader";
import StoryCard from "@/components/StoryCard";
import TagBar from "@/components/TagBar";
import { getSeriesList, getStories, getTags } from "@/lib/api";
import styles from "./page.module.css";

// Static metadata is fine — the page reads `searchParams` at request
// time, but the title / description / canonical are constant. Title
// is just "Search" so the root layout's `%s — Lucifer's Diary`
// template builds the full string (previous version baked the suffix
// into the title and ended up duplicated under the template).
const SEARCH_DESCRIPTION =
  "Search published stories and series on Lucifer's Diary by keyword or tag.";

export const metadata: Metadata = {
  title: "Search",
  description: SEARCH_DESCRIPTION,
  // Canonical pinned to the bare /search — query-string variants
  // (?search=…&tagIds=…) consolidate here in Google's index instead
  // of producing one shadow URL per filter combination.
  alternates: { canonical: "/search" },
  openGraph: {
    type: "website",
    title: "Search",
    description: SEARCH_DESCRIPTION,
    url: "/search",
  },
  twitter: {
    card: "summary_large_image",
    title: "Search",
    description: SEARCH_DESCRIPTION,
  },
};

export default async function SearchPage({
  searchParams,
}: {
  searchParams: Promise<{ search?: string; tagIds?: string | string[] }>;
}) {
  const params = await searchParams;
  const search = params.search?.trim() || undefined;
  const tagIdsRaw = params.tagIds;
  const tagIds = tagIdsRaw
    ? Array.isArray(tagIdsRaw)
      ? tagIdsRaw
      : [tagIdsRaw]
    : undefined;

  const [tags, storiesRes, seriesRes] = await Promise.all([
    getTags().catch(() => []),
    getStories({ search, tagIds, limit: 60 }).catch(() => ({
      data: [],
      meta: { total: 0, page: 1, limit: 60, totalPages: 0 },
    })),
    getSeriesList({ search, tagIds, limit: 60 }).catch(() => ({
      data: [],
      meta: { total: 0, page: 1, limit: 60, totalPages: 0 },
    })),
  ]);

  const stories = storiesRes.data;
  const seriesList = seriesRes.data;
  const totalCount = stories.length + seriesList.length;

  const subtitle = describeSearch({ search, tagIds, tags, totalCount });

  return (
    <>
      <SiteHeader />
      <div className={styles.page}>
        <div className={styles.intro}>
        <h2 className={styles.title}>Search</h2>
        <p className={styles.subtitle}>{subtitle}</p>
      </div>

      <TagBar
        tags={tags}
        activeIds={tagIds}
        basePath="/search"
        search={search}
      />


      <main id="main" tabIndex={-1} className={styles.main}>
        {totalCount === 0 ? (
          <p className={styles.empty}>No stories match.</p>
        ) : (
          <>
            {stories.length > 0 && (
              <section className={styles.section}>
                <h3 className={styles.sectionTitle}>
                  Stories &middot; {stories.length}
                </h3>
                <CardGrid>
                  {stories.map((s) => (
                    <StoryCard key={s.id} story={s} />
                  ))}
                </CardGrid>
              </section>
            )}
            {seriesList.length > 0 && (
              <section className={styles.section}>
                <h3 className={styles.sectionTitle}>
                  Series &middot; {seriesList.length}
                </h3>
                <CardGrid>
                  {seriesList.map((sr) => (
                    <SeriesCard key={sr.id} series={sr} />
                  ))}
                </CardGrid>
              </section>
            )}
          </>
        )}
        </main>
      </div>
    </>
  );
}

function describeSearch({
  search,
  tagIds,
  tags,
  totalCount,
}: {
  search?: string;
  tagIds?: string[];
  tags: { id: string; name: string }[];
  totalCount: number;
}): string {
  const parts: string[] = [];
  if (search) parts.push(`for "${search}"`);
  if (tagIds && tagIds.length > 0) {
    const names = tagIds
      .map((id) => tags.find((t) => t.id === id)?.name)
      .filter((n): n is string => !!n);
    if (names.length > 0) {
      parts.push(`tagged ${names.map((n) => `#${n}`).join(", ")}`);
    }
  }
  if (parts.length === 0) {
    return totalCount === 1
      ? "1 published piece"
      : `${totalCount} published pieces`;
  }
  return `${totalCount} ${totalCount === 1 ? "result" : "results"} ${parts.join(" ")}`;
}

