      'writes to (and can delete from) the database and is dev-only.\n\n' +
      'Run as:\n' +
      '  LUCIFER_ENV=dev npm run seed:dev -- --confirm=dev',
  );
}

// Guard 2: prod-URL sniff.
const dbUrl = process.env.DATABASE_URL ?? '';
if (!dbUrl) {
  refuse(
    'DATABASE_URL is not set. The script cannot proceed without a target ' +
      'database — set it (to your DEV database) and try again.',
  );
}
const matchedProdMarker = PROD_URL_MARKERS.find((m) =>
  dbUrl.toLowerCase().includes(m),
);
if (matchedProdMarker) {
  refuse(
    `DATABASE_URL contains "${matchedProdMarker}" — this looks like a ` +
      'production / managed database. Refusing.\n\n' +
      'If this is a false positive (e.g. your dev DB happens to be on ' +
      'render.com), edit PROD_URL_MARKERS in backend/scripts/' +
      'seed-dev-content.ts and remove the matching marker.',
  );
}

// Guard 3: --confirm=dev required for any write operation (seed or
// purge). Dry-run is the only exception.
const isWrite = !isDryRun; // both seed and purge are writes
if (isWrite && confirmFlag !== 'dev') {
  refuse(
    'Missing --confirm=dev flag. Both --seed (default) and --purge write ' +
      'to the database and require explicit confirmation.\n\n' +
      'Usage:\n' +
      '  LUCIFER_ENV=dev npm run seed:dev -- --confirm=dev          # seed\n' +
      '  LUCIFER_ENV=dev npm run seed:dev -- --dry-run              # preview\n' +
      '  LUCIFER_ENV=dev npm run seed:dev -- --purge --confirm=dev  # wipe seeded rows',
  );
}

// ── Prisma client ────────────────────────────────────────────────────

const prisma = new PrismaClient();

// ── Random helpers ───────────────────────────────────────────────────

function randomInt(min: number, max: number): number {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

function randomChoice<T>(arr: readonly T[]): T {
  return arr[Math.floor(Math.random() * arr.length)];
}

function randomDateInLast6Months(): Date {
  const now = Date.now();
  const earliest = now - 180 * 24 * 60 * 60 * 1000;
  return new Date(earliest + Math.random() * (now - earliest));
}

function chance(probability: number): boolean {
  return Math.random() < probability;
}

// ── Content generators ──────────────────────────────────────────────
//
// IMPORTANT: every string below is either faker.lorem.* (synthetic) or
// drawn from the hand-curated mood pools defined in this file. No
// content is derived from any external source, copyrighted or
// otherwise.

const MOOD_NOUNS = [
  'Confession',
  'Letter',
  'Mirror',
  'Threshold',
  'Vow',
  'Kiss',
  'Hour',
  'Garden',
  'Library',
  'Stairwell',
  'Balcony',
  'Veil',
  'Shadow',
  'Lantern',
  'Echo',
  'Promise',
  'Secret',
  'Bargain',
  'Pact',
  'Ritual',
  'Diary',
  'Mark',
  'Trace',
  'Pause',
  'Distance',
  'Silence',
  'Door',
  'Window',
  'Memory',
  'Touch',
] as const;

const TITLE_PATTERNS: ReadonlyArray<() => string> = [
  () => `The ${randomChoice(MOOD_NOUNS)}`,
  () => `${capitalize(faker.word.adjective({ length: { min: 4, max: 10 } }))} ${randomChoice(MOOD_NOUNS)}`,
  () => `After ${randomChoice(MOOD_NOUNS)}`,
  () => `Before ${randomChoice(MOOD_NOUNS)}`,
  () => `Without ${randomChoice(MOOD_NOUNS)}`,
  () => `On ${randomChoice(MOOD_NOUNS)}`,
  () => `The ${randomChoice(MOOD_NOUNS)} of ${faker.person.firstName()}`,
  () => `What ${faker.person.firstName()} Knew`,
  () => `Notes on ${randomChoice(MOOD_NOUNS)}`,
];

function capitalize(s: string): string {
  return s.length === 0 ? s : s[0].toUpperCase() + s.slice(1);
}

function generateTitle(): string {
  return randomChoice(TITLE_PATTERNS)();
}

function generateExcerpt(): string {
  return faker.lorem.sentences(3);
}

function generateBody(wordTarget: number): string {
  const paragraphs: string[] = [];
  let words = 0;
  while (words < wordTarget) {
    const paragraph = faker.lorem.paragraph(randomInt(4, 9));
    paragraphs.push(paragraph);
    words += paragraph.split(/\s+/).length;
  }
  return paragraphs.join('\n\n');
}

function estimateReadMinutes(content: string): number {
  const words = content.split(/\s+/).filter(Boolean).length;
  return Math.max(1, Math.round(words / READING_WPM));
}

function buildAuthorsNote(): string {
  return `${SEED_MARKER} ${faker.lorem.sentence()}`;
}

function pickTags(
  tagPool: Tag[],
  count: number,
  adultRatio: number,
): Tag[] {
  const safe = tagPool.filter((t) => !t.isAdult);
  const adult = tagPool.filter((t) => t.isAdult);
  const adultCount = Math.min(adult.length, Math.round(count * adultRatio));
  const safeCount = Math.min(safe.length, count - adultCount);

  const shuffleAndTake = (arr: Tag[], n: number): Tag[] => {
    const copy = arr.slice();
    for (let i = copy.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [copy[i], copy[j]] = [copy[j], copy[i]];
    }
    return copy.slice(0, n);
  };

  return [
    ...shuffleAndTake(safe, safeCount),
    ...shuffleAndTake(adult, adultCount),
  ];
}

// ── Plans ────────────────────────────────────────────────────────────

interface StoryPlan {
  title: string;
  content: string;
  excerpt: string;
  estimatedReadMinutes: number;
  isAuthorsChoice: boolean;
  authorsNote: string;
  publishedAt: Date | null;
  tagIds: string[];
}

interface ChapterPlan {
  title: string;
  content: string;
  excerpt: string;
  orderIndex: number;
  estimatedReadMinutes: number;
  isAuthorsChoice: boolean;
  authorsNote: string;
  publishedAt: Date | null;
  tagIds: string[];
}

type SeriesStatusValue = 'ONGOING' | 'COMPLETE' | 'HIATUS';

interface SeriesPlan {
  title: string;
  excerpt: string;
  status: SeriesStatusValue;
  authorsNote: string;
  tagIds: string[];
  chapters: ChapterPlan[];
}

function planStory(tagPool: Tag[], asDraft: boolean): StoryPlan {
  const content = generateBody(randomInt(BODY_WORD_MIN, BODY_WORD_MAX));
  const tags = pickTags(
    tagPool,
    randomInt(TAGS_PER_ITEM_MIN, TAGS_PER_ITEM_MAX),
    ADULT_TAG_RATIO,
  );
  return {
    title: generateTitle(),
    content,
    excerpt: generateExcerpt(),
    estimatedReadMinutes: estimateReadMinutes(content),
    isAuthorsChoice: chance(AUTHORS_CHOICE_PROBABILITY),
    authorsNote: buildAuthorsNote(),
    publishedAt: asDraft ? null : randomDateInLast6Months(),
    tagIds: tags.map((t) => t.id),
  };
}

function planSeries(tagPool: Tag[], allChaptersDraft: boolean): SeriesPlan {
  const chapterCount = randomInt(
    CHAPTERS_PER_SERIES_MIN,
    CHAPTERS_PER_SERIES_MAX,
  );
  const status: SeriesStatusValue = randomChoice([
    'ONGOING',
    'ONGOING',
    'COMPLETE',
    'HIATUS',
  ]); // weighted toward ONGOING
  const seriesTags = pickTags(
    tagPool,
    randomInt(TAGS_PER_ITEM_MIN, TAGS_PER_ITEM_MAX),
    ADULT_TAG_RATIO,
  );
  const chapters: ChapterPlan[] = [];
  for (let i = 0; i < chapterCount; i++) {
    const content = generateBody(randomInt(BODY_WORD_MIN, BODY_WORD_MAX));
    const chapterTags = pickTags(
      tagPool,
      randomInt(TAGS_PER_ITEM_MIN, TAGS_PER_ITEM_MAX),
      ADULT_TAG_RATIO,
    );
    chapters.push({
      title: generateTitle(),
      content,
      excerpt: generateExcerpt(),
      orderIndex: i + 1,
      estimatedReadMinutes: estimateReadMinutes(content),
      isAuthorsChoice: chance(AUTHORS_CHOICE_PROBABILITY),
      authorsNote: buildAuthorsNote(),
      publishedAt: allChaptersDraft ? null : randomDateInLast6Months(),
      tagIds: chapterTags.map((t) => t.id),
    });
  }
  return {
    title: generateTitle(),
    excerpt: generateExcerpt(),
    status,
    authorsNote: buildAuthorsNote(),
    tagIds: seriesTags.map((t) => t.id),
    chapters,
  };
}

// ── Idempotency check ───────────────────────────────────────────────

async function countMarkerRows(): Promise<{
  stories: number;
  series: number;
  chapters: number;
}> {
  const [stories, series, chapters] = await Promise.all([
    prisma.story.count({
      where: { authorsNote: { startsWith: SEED_MARKER } },
    }),
    prisma.series.count({
      where: { authorsNote: { startsWith: SEED_MARKER } },
    }),
    prisma.chapter.count({
      where: { authorsNote: { startsWith: SEED_MARKER } },
    }),
  ]);
  return { stories, series, chapters };
}

// ── Purge ────────────────────────────────────────────────────────────

async function purge(): Promise<void> {
  console.log(
    `\n🧹 Purging rows with authorsNote starting with "${SEED_MARKER}"...`,
  );
  const result = await prisma.$transaction(
    async (tx) => {
      // Collect ids first so we can delete the join rows by FK
      // (StoryTag / SeriesTag / ChapterTag aren't declared with
      // onDelete: Cascade in the schema, so we must clear them
      // explicitly before deleting the parents).
      const stories = await tx.story.findMany({
        where: { authorsNote: { startsWith: SEED_MARKER } },
        select: { id: true },
      });
      const series = await tx.series.findMany({
        where: { authorsNote: { startsWith: SEED_MARKER } },
        select: { id: true },
      });
      const chapters = await tx.chapter.findMany({
        where: { authorsNote: { startsWith: SEED_MARKER } },
        select: { id: true },
      });
      const storyIds = stories.map((s) => s.id);
      const seriesIds = series.map((s) => s.id);
      const chapterIds = chapters.map((c) => c.id);

      // Drop tag joins first.
      if (storyIds.length > 0) {
        await tx.storyTag.deleteMany({
          where: { storyId: { in: storyIds } },
        });
      }
      if (seriesIds.length > 0) {
        await tx.seriesTag.deleteMany({
          where: { seriesId: { in: seriesIds } },
        });
      }
      if (chapterIds.length > 0) {
        await tx.chapterTag.deleteMany({
          where: { chapterId: { in: chapterIds } },
        });
      }

      // Drop Notes (the relation has onDelete: Cascade, but being
      // explicit here keeps the transaction self-contained even if
      // someone later changes that cascade).
      if (storyIds.length > 0) {
        await tx.note.deleteMany({
          where: { storyId: { in: storyIds } },
        });
      }
      if (chapterIds.length > 0) {
        await tx.note.deleteMany({
          where: { chapterId: { in: chapterIds } },
        });
      }

      // Now safe to delete the parents. Chapters first (FK -> series),
      // then series, then stories.
      const chapterDel = await tx.chapter.deleteMany({
        where: { id: { in: chapterIds } },
      });
      const seriesDel = await tx.series.deleteMany({
        where: { id: { in: seriesIds } },
      });
      const storyDel = await tx.story.deleteMany({
        where: { id: { in: storyIds } },
      });

      return {
        stories: storyDel.count,
        series: seriesDel.count,
        chapters: chapterDel.count,
      };
    },
    { timeout: TX_TIMEOUT_MS },
  );

  console.log(
    `✅ Purged: ${result.stories} stories, ${result.series} series, ${result.chapters} chapters.\n`,
  );
}

// ── Seed ─────────────────────────────────────────────────────────────

async function seed(dryRun: boolean): Promise<void> {
  // Refuse re-seed if marker rows exist.
  const prior = await countMarkerRows();
  const priorTotal = prior.stories + prior.series + prior.chapters;
  if (priorTotal > 0) {
    refuse(
      `Existing seeded rows detected: ${prior.stories} stories, ` +
        `${prior.series} series, ${prior.chapters} chapters.\n\n` +
        'Re-seeding would create duplicates. Wipe them first:\n' +
        '  LUCIFER_ENV=dev npm run seed:dev -- --purge --confirm=dev',
    );
  }

  // Load tag pool.
  const tagPool = await prisma.tag.findMany();
  if (tagPool.length === 0) {
    refuse(
      'No tags in DB — seed the tag taxonomy first:\n' +
        '  npm run seed:tags',
    );
  }
  const safeCount = tagPool.filter((t) => !t.isAdult).length;
  const adultCount = tagPool.filter((t) => t.isAdult).length;
  console.log(
    `\n📚 Loaded ${tagPool.length} tags (${safeCount} safe, ${adultCount} adult).`,
  );

  // Plan everything up front so a dry-run can preview the same shape
  // that the real run would commit.
  const publishedStories = Array.from(
    { length: PUBLISHED_STORY_COUNT },
    () => planStory(tagPool, false),
  );
  const draftStories = Array.from({ length: DRAFT_STORY_COUNT }, () =>
    planStory(tagPool, true),
  );
  const publishedSeries = Array.from(
    { length: PUBLISHED_SERIES_COUNT },
    () => planSeries(tagPool, false),
  );
  const draftSeries = Array.from({ length: DRAFT_SERIES_COUNT }, () =>
    planSeries(tagPool, true),
  );

  const allStories = [...publishedStories, ...draftStories];
  const allSeries = [...publishedSeries, ...draftSeries];
  const totalChapters = allSeries.reduce(
    (sum, s) => sum + s.chapters.length,
    0,
  );

  console.log('\n📋 Plan:');
  console.log(
    `  Stories: ${allStories.length} ` +
      `(${publishedStories.length} published, ${draftStories.length} draft)`,
  );
  console.log(
    `  Series:  ${allSeries.length} ` +
      `(${publishedSeries.length} published, ${draftSeries.length} fully-draft)`,
  );
  console.log(`  Chapters: ${totalChapters}`);

  console.log('\n📝 First 5 story titles:');
  allStories.slice(0, 5).forEach((s, i) => {
    console.log(
      `  ${i + 1}. ${s.title} ${s.publishedAt ? '(published)' : '(DRAFT)'}`,
    );
  });
  console.log('\n📝 First 5 series titles:');
  allSeries.slice(0, 5).forEach((s, i) => {
    console.log(`  ${i + 1}. ${s.title} (${s.status}, ${s.chapters.length} chapters)`);
  });

  if (dryRun) {
    console.log('\n💨 Dry run complete — no DB writes.\n');
    return;
  }

  // Real write — single transaction so a mid-run failure leaves zero
  // partial rows.
  console.log('\n💾 Writing to DB...');
  await prisma.$transaction(
    async (tx) => {
      for (const plan of allStories) {
        await tx.story.create({
          data: {
            title: plan.title,
            content: plan.content,
            excerpt: plan.excerpt,
            estimatedReadMinutes: plan.estimatedReadMinutes,
            isAuthorsChoice: plan.isAuthorsChoice,
            authorsNote: plan.authorsNote,
            publishedAt: plan.publishedAt,
            tags: {
              create: plan.tagIds.map((tagId) => ({ tagId })),
            },
          },
        });
      }

      for (const plan of allSeries) {
        const created = await tx.series.create({
          data: {
            title: plan.title,
            excerpt: plan.excerpt,
            status: plan.status,
            authorsNote: plan.authorsNote,
            tags: {
              create: plan.tagIds.map((tagId) => ({ tagId })),
            },
          },
        });
        for (const ch of plan.chapters) {
          await tx.chapter.create({
            data: {
              seriesId: created.id,
              title: ch.title,
              content: ch.content,
              excerpt: ch.excerpt,
              orderIndex: ch.orderIndex,
              estimatedReadMinutes: ch.estimatedReadMinutes,
              isAuthorsChoice: ch.isAuthorsChoice,
              authorsNote: ch.authorsNote,
              publishedAt: ch.publishedAt,
              tags: {
                create: ch.tagIds.map((tagId) => ({ tagId })),
              },
            },
          });
        }
      }
    },
    { timeout: TX_TIMEOUT_MS },
  );

  console.log(
    `\n✅ Seeded: ${allStories.length} stories, ${allSeries.length} series, ${totalChapters} chapters.`,
  );
  console.log(
    `📌 To wipe later: LUCIFER_ENV=dev npm run seed:dev -- --purge --confirm=dev\n`,
  );
}

// ── Main ─────────────────────────────────────────────────────────────

async function main(): Promise<void> {
  try {
    if (isPurge) {
      await purge();
    } else {
      await seed(isDryRun);
    }
  } finally {
    await prisma.$disconnect();
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(2);
});

