// Pick a pool piece whose word count is close to `wordTarget`, falling
// back to a uniform pick if no piece is in the tolerance window. Used
// when we want a story body that fits a specific length budget.
function pickPoolPieceForWordTarget(wordTarget: number): DevProsePiece {
  const filtered = DEV_PROSE_POOL.filter(
    (p) =>
      Math.abs(p.wordCount - wordTarget) / wordTarget <=
      POOL_VERBATIM_TOLERANCE,
  );
  return filtered.length > 0 ? randomChoice(filtered) : pickPoolPiece();
}

// Map a pool piece's `suggestedTags` (free-text labels supplied by the
// writer agents) to actual rows in the live tag taxonomy via a relaxed
// case-insensitive substring match in both directions. Falls back to
// the existing random `pickTags` for any remaining slots so the
// adult/safe ratio in the row's final tag set is still honored.
function derivedTagsFromPiece(
  piece: DevProsePiece,
  tagPool: Tag[],
  count: number,
  adultRatio: number,
): Tag[] {
  const wanted = piece.suggestedTags.map((s) => s.toLowerCase().trim());
  const seen = new Set<string>();
  const matches: Tag[] = [];
  for (const tag of tagPool) {
    const name = tag.name.toLowerCase();
    const hit = wanted.some((w) => name.includes(w) || w.includes(name));
    if (hit && !seen.has(tag.id)) {
      seen.add(tag.id);
      matches.push(tag);
    }
  }
  // Shuffle so the matched-tag slice itself isn't always in the same
  // taxonomy order across rows.
  for (let i = matches.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [matches[i], matches[j]] = [matches[j], matches[i]];
  }
  const take = matches.slice(0, count);
  if (take.length >= count) return take;
  // Fill remaining slots from the random picker, deduped against the
  // already-matched set so the same tag isn't joined twice.
  const remaining = count - take.length;
  const fillerPool = tagPool.filter((t) => !seen.has(t.id));
  const filler = pickTags(fillerPool, remaining, adultRatio);
  return [...take, ...filler];
}

