import type { Metadata } from "next";
import CardGrid from "@/components/CardGrid";
import { SeriesCard } from "@/components/SeriesCard";
import SiteHeader from "@/components/SiteHeader";
import StoryCard from "@/components/StoryCard";
import TagBar from "@/components/TagBar";
import { getSeriesList, getStories, getTags } from "@/lib/api";
import styles from "./page.module.css";

// Static metadata is fine — the page reads `searchParams` at request
// time, but the title / description / canonical are constant. Title
// is just "Search" so the root layout's `%s — Lucifer's Diary`
// template builds the full string (previous version baked the suffix
// into the title and ended up duplicated under the template).
const SEARCH_DESCRIPTION =
  "Search published stories and series on Lucifer's Diary by keyword or tag.";

export const metadata: Metadata = {
  title: "Search",
  description: SEARCH_DESCRIPTION,
  // Canonical pinned to the bare /search — query-string variants
  // (?search=…&tagIds=…) consolidate here in Google's index instead
  // of producing one shadow URL per filter combination.
  alternates: { canonical: "/search" },
  openGraph: {
    type: "website",
    title: "Search",
    description: SEARCH_DESCRIPTION,
    url: "/search",
  },
  twitter: {
    card: "summary_large_image",
    title: "Search",
    description: SEARCH_DESCRIPTION,
  },
};

export default async function SearchPage({
  searchParams,
}: {
  searchParams: Promise<{ search?: string; tagIds?: string | string[] }>;
}) {
  const params = await searchParams;
  const search = params.search?.trim() || undefined;
  const tagIdsRaw = params.tagIds;
  const tagIds = tagIdsRaw
    ? Array.isArray(tagIdsRaw)
      ? tagIdsRaw
      : [tagIdsRaw]
    : undefined;

  const [tags, storiesRes, seriesRes] = await Promise.all([
    getTags().catch(() => []),
    getStories({ search, tagIds, limit: 60 }).catch(() => ({
      data: [],
      meta: { total: 0, page: 1, limit: 60, totalPages: 0 },
    })),
    getSeriesList({ search, tagIds, limit: 60 }).catch(() => ({
      data: [],
      meta: { total: 0, page: 1, limit: 60, totalPages: 0 },
    })),
  ]);

  const stories = storiesRes.data;
  const seriesList = seriesRes.data;
  const totalCount = stories.length + seriesList.length;

  const subtitle = describeSearch({ search, tagIds, tags, totalCount });

  // Stable key per (search, tagIds) combo so each CardGrid REMOUNTS
  // on filter change — the only way the Flip-bridge drain (T5) fires
  // on App-Router server-side navigation. Without a fresh key React
  // would update children in place and the useGSAP mount-effect
  // wouldn't re-run.
  const filterKey = `${search ?? ""}|${(tagIds ?? []).slice().sort().join(",")}`;

  return (
    <>
      <SiteHeader />
      <div className={styles.page}>
        <div className={styles.intro}>
        <h2 className={styles.title}>Search</h2>
        <p className={styles.subtitle}>{subtitle}</p>
      </div>

      <TagBar
        tags={tags}
        activeIds={tagIds}
        basePath="/search"
        search={search}
      />


      <main id="main" tabIndex={-1} className={styles.main}>
        {totalCount === 0 ? (
          <p className={styles.empty}>No stories match.</p>
        ) : (
          <>
            {stories.length > 0 && (
              <section className={styles.section}>
                <h3 className={styles.sectionTitle}>
                  Stories &middot; {stories.length}
                </h3>
                <CardGrid
                  key={`stories|${filterKey}`}
                  flipKey="search:stories"
                  flipTagIds={tagIds}
                >
                  {stories.map((s) => (
                    <StoryCard key={s.id} story={s} />
                  ))}
                </CardGrid>
              </section>
            )}
            {seriesList.length > 0 && (
              <section className={styles.section}>
                <h3 className={styles.sectionTitle}>
                  Series &middot; {seriesList.length}
                </h3>
                <CardGrid
                  key={`series|${filterKey}`}
                  flipKey="search:series"
                  flipTagIds={tagIds}
                >
                  {seriesList.map((sr) => (
                    <SeriesCard key={sr.id} series={sr} />
                  ))}
                </CardGrid>
              </section>
            )}
          </>
        )}
        </main>
      </div>
    </>
  );
}

function describeSearch({
  search,
  tagIds,
  tags,
  totalCount,
}: {
  search?: string;
  tagIds?: string[];
  tags: { id: string; name: string }[];
  totalCount: number;
}): string {
  const parts: string[] = [];
  if (search) parts.push(`for "${search}"`);
  if (tagIds && tagIds.length > 0) {
    const names = tagIds
      .map((id) => tags.find((t) => t.id === id)?.name)
      .filter((n): n is string => !!n);
    if (names.length > 0) {
      parts.push(`tagged ${names.map((n) => `#${n}`).join(", ")}`);
    }
  }
  if (parts.length === 0) {
    return totalCount === 1
      ? "1 published piece"
      : `${totalCount} published pieces`;
  }
  return `${totalCount} ${totalCount === 1 ? "result" : "results"} ${parts.join(" ")}`;
}

"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  flipBridgeKey,
  isFlipTagFilterEnabled,
  snapshotFlip,
} from "@/lib/flipBridge";
import { Flip } from "@/lib/gsap";
import type { Tag } from "@/types";
import styles from "./TagBar.module.css";

/**
 * Tracks which edges of the horizontal-scroll tag row have content
 * past them, so the CSS can fade the appropriate edge(s). Returns
 * "none" when the row fits without scrolling, and "start" / "middle"
 * / "end" when it overflows — start = at the leftmost position
 * (only right edge has more), middle = both, end = scrolled to the
 * end (only left edge has more).
 */
function useScrollEdges(ref: React.RefObject<HTMLDivElement | null>) {
  const [edge, setEdge] = useState<"none" | "start" | "middle" | "end">("start");

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    const update = () => {
      // Re-read from the ref each call rather than relying solely on
      // the captured `el`. If the DOM element is detached between
      // listener registration and the next event, this stays safe
      // instead of dereferencing a node that's no longer in the tree.
      const current = ref.current;
      if (!current) return;
      // 1-px tolerance for sub-pixel scroll positions.
      if (current.scrollWidth <= current.clientWidth + 1) {
        setEdge("none");
        return;
      }
      const atStart = current.scrollLeft <= 1;
      const atEnd =
        current.scrollLeft + current.clientWidth >= current.scrollWidth - 1;
      if (atStart) setEdge("start");
      else if (atEnd) setEdge("end");
      else setEdge("middle");
    };

    update();
    el.addEventListener("scroll", update, { passive: true });
    // Resize can change whether the row overflows at all.
    window.addEventListener("resize", update);
    return () => {
      el.removeEventListener("scroll", update);
      window.removeEventListener("resize", update);
    };
  }, [ref]);

  return edge;
}

interface Props {
  tags: Tag[];
  /** Active tag ids — these get the gold-stroke active state */
  activeIds?: string[];
  /** Base href for tag links (e.g., "/search") */
  basePath?: string;
  /** Existing search query to preserve when clicking tags */
  search?: string;
  /** Threshold below which the toggle button stays hidden */
  expandThreshold?: number;
}

/**
 * Tag filter bar.
 *
 * Default: single-line horizontal scroll with a fade on the right edge.
 * Expanded: tags are grouped by their first letter (A, B, C...) so a
 * 500-tag taxonomy stays browseable. Each letter is a row with the
 * letter on the left and pills wrapping to the right.
 *
 * Color rules:
 *   - safe tag (isAdult = false)  -> green pill
 *   - adult tag (isAdult = true)  -> red pill
 *   - selected (active) tag       -> gold border, regardless
 */
export default function TagBar({
  tags,
  activeIds,
  basePath = "/search",
  search,
  expandThreshold = 12,
}: Props) {
  const router = useRouter();
  const [expanded, setExpanded] = useState(false);
  const activeSet = useMemo(() => new Set(activeIds ?? []), [activeIds]);
  const showToggle = tags.length > expandThreshold;

  /**
   * T5 — Flip-bridge click interception. When NEXT_PUBLIC_FLIP_TAG_FILTER
   * is enabled, intercept the Link click, snapshot every CardGrid on
   * the page via Flip.getState (keyed by their data-flip-grid + the
   * destination tagIds), then hand the navigation off to the router.
   * The destination CardGrid will drain its snapshot on mount and run
   * Flip.from. Falls through to default Link nav when the flag is
   * off — code path is dormant.
   */
  const onTagNav = useCallback(
    (href: string) => (e: React.MouseEvent<HTMLAnchorElement>) => {
      if (!isFlipTagFilterEnabled()) return;
      // Honor modifier-clicks (open in new tab, etc.) — only intercept
      // a plain left-click.
      if (
        e.metaKey ||
        e.ctrlKey ||
        e.shiftKey ||
        e.altKey ||
        e.button !== 0
      ) {
        return;
      }
      e.preventDefault();
      // Parse the destination tagIds out of the href so the bridge
      // key matches what the CardGrid will compute on the other side.
      let nextTagIds: string[] = [];
      try {
        const url = new URL(href, window.location.origin);
        nextTagIds = url.searchParams.getAll("tagIds");
      } catch {
        // Malformed href shouldn't crash the click; fall through.
      }
      // Snapshot every CardGrid currently rendered. Each grid keys
      // its snapshot by its own data-flip-grid + nextTagIds so a
      // single navigation can carry multiple snapshots (e.g.
      // /search renders a Stories grid + a Series grid).
      const grids = document.querySelectorAll<HTMLElement>("[data-flip-grid]");
      grids.forEach((grid) => {
        const flipKey = grid.dataset.flipGrid;
        if (!flipKey) return;
        const items = grid.querySelectorAll("[data-flip-id]");
        if (items.length === 0) return;
        const state = Flip.getState(items, {
          props: "opacity,borderRadius",
        });
        snapshotFlip(flipBridgeKey(flipKey, nextTagIds), state);
      });
      router.push(href);
    },
    [router],
  );

  const allHref = search
    ? `${basePath}?search=${encodeURIComponent(search)}`
    : basePath;

  const buildTagHref = (tagId: string) => {
    const params = new URLSearchParams();
    if (search) params.set("search", search);
    params.set("tagIds", tagId);
    return `${basePath}?${params.toString()}`;
  };

  const sortedTags = useMemo(
    () => [...tags].sort((a, b) => a.name.localeCompare(b.name)),
    [tags],
  );

  // Group expanded tags by first letter for browsability.
  const grouped = useMemo(() => {
    const map = new Map<string, Tag[]>();
    for (const tag of sortedTags) {
      const ch = tag.name.charAt(0);
      const key = ch ? (/[a-z]/i.test(ch) ? ch.toUpperCase() : "#") : "#";
      const list = map.get(key) ?? [];
      list.push(tag);
      map.set(key, list);
    }
    return Array.from(map.entries()).sort(([a], [b]) => {
      if (a === "#") return 1;
      if (b === "#") return -1;
      return a.localeCompare(b);
    });
  }, [sortedTags]);

  if (tags.length === 0) return null;

  if (expanded) {
    return (
      <div className={styles.wrapper}>
        <div className={styles.collapseRow}>
          <button
            type="button"
            onClick={() => setExpanded(false)}
            className={styles.toggle}
            // Explicit boolean — `aria-expanded` without a value
            // renders as the empty string, which some screen readers
            // misinterpret. The collapsed-row button below uses
            // `aria-expanded={false}` so this mirror is consistent.
            aria-expanded={true}
          >
            Collapse
            <Chevron open />
          </button>
        </div>

        <div className={styles.expanded}>
          {/* "All" stays at the top */}
          <div className={styles.letterGroup}>
            <span className={styles.letter} aria-hidden>·</span>
            <div className={styles.letterPills}>
              <Link
                href={allHref}
                onClick={onTagNav(allHref)}
                className={`${styles.pill} ${activeSet.size === 0 ? styles.pillActive : ""}`}
              >
                All
              </Link>
            </div>
          </div>

          {grouped.map(([letter, letterTags]) => (
            <div key={letter} className={styles.letterGroup}>
              <span className={styles.letter}>{letter}</span>
              <div className={styles.letterPills}>
                {letterTags.map((tag) => {
                  const href = buildTagHref(tag.id);
                  return (
                    <Pill
                      key={tag.id}
                      tag={tag}
                      href={href}
                      active={activeSet.has(tag.id)}
                      onClick={onTagNav(href)}
                    />
                  );
                })}
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  // Collapsed (default): single horizontal-scroll row.
  return <CollapsedRow
    sortedTags={sortedTags}
    allHref={allHref}
    activeSet={activeSet}
    buildTagHref={buildTagHref}
    showToggle={showToggle}
    onExpand={() => setExpanded(true)}
    onTagNav={onTagNav}
  />;
}

function CollapsedRow({
  sortedTags,
  allHref,
  activeSet,
  buildTagHref,
  showToggle,
  onExpand,
  onTagNav,
}: {
  sortedTags: Tag[];
  allHref: string;
  activeSet: Set<string>;
  buildTagHref: (id: string) => string;
  showToggle: boolean;
  onExpand: () => void;
  onTagNav: (href: string) => (e: React.MouseEvent<HTMLAnchorElement>) => void;
}) {
  const listRef = useRef<HTMLDivElement>(null);
  // Drives the data-scroll attribute on the list, which the CSS
  // uses to pick a mask-image (left fade / right fade / both /
  // none) per the row's current scroll position.
  const edge = useScrollEdges(listRef);

  return (
    <div className={styles.wrapper}>
      <div className={styles.row}>
        <div ref={listRef} className={styles.list} data-scroll={edge}>
          <Link
            href={allHref}
            onClick={onTagNav(allHref)}
            className={`${styles.pill} ${activeSet.size === 0 ? styles.pillActive : ""}`}
          >
            All
          </Link>
          {sortedTags.map((tag) => {
            const href = buildTagHref(tag.id);
            return (
              <Pill
                key={tag.id}
                tag={tag}
                href={href}
                active={activeSet.has(tag.id)}
                onClick={onTagNav(href)}
              />
            );
          })}
        </div>

        {showToggle && (
          <button
            type="button"
            onClick={onExpand}
            className={styles.toggle}
            aria-expanded={false}
          >
            All tags
            <Chevron open={false} />
          </button>
        )}
      </div>
    </div>
  );
}

function Pill({
  tag,
  href,
  active,
  onClick,
}: {
  tag: Tag;
  href: string;
  active: boolean;
  onClick?: React.MouseEventHandler<HTMLAnchorElement>;
}) {
  const variant = tag.isAdult ? styles.pillAdult : styles.pillSafe;
  const activeCls = active ? styles.pillActive : "";
  return (
    <Link
      href={href}
      onClick={onClick}
      className={`${styles.pill} ${variant} ${activeCls}`}
      title={tag.isAdult ? `${tag.name} (adult)` : tag.name}
    >
      {tag.name}
    </Link>
  );
}

function Chevron({ open }: { open: boolean }) {
  return (
    <svg
      className={`${styles.chevron} ${open ? styles.chevronOpen : ""}`}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
