// localStorage throws SecurityError on opaque origins (some file://
// contexts, sandboxed iframes). Wrap every call so a broken storage
// degrades to "no persistence" instead of killing the whole script.
const safeLs = {
  get(key) { try { return localStorage.getItem(key); } catch { return null; } },
  set(key, val) { try { localStorage.setItem(key, val); return true; } catch { return false; } },
};
let storageWarned = false;
function warnStorageOnce() {
  if (storageWarned) return;
  storageWarned = true;
  try { localStorage.getItem('__probe'); }
  catch {
    const banner = document.getElementById('js-warn');
    if (banner) {
      banner.style.display = 'block';
      banner.textContent = '⚠ localStorage is unavailable in this context — your progress and notes will NOT persist across reloads. (Open the file via "open dev-test-checklist.html" or move it to a real web origin to fix.)';
    }
  }
}
function loadState() {
  try { return JSON.parse(safeLs.get(STORE_KEY) || '{}'); }
  catch { return {}; }
}
function saveState(s) {
  if (!safeLs.set(STORE_KEY, JSON.stringify(s))) warnStorageOnce();
}
function loadBaseUrl() {
  return safeLs.get(BASE_URL_KEY) || '';
}
function saveBaseUrl(v) {
  if (!safeLs.set(BASE_URL_KEY, v)) warnStorageOnce();
}

