cd /tmp/lucifer-cl-sim && cat > sim2.js << 'EOF'
const fs = require('fs');
const { JSDOM, VirtualConsole } = require('jsdom');

const html = fs.readFileSync('/Users/taha/Claude projects/LucifersDiary/dev-test-checklist.html', 'utf8');

const errors = [];
const vc = new VirtualConsole();
vc.on('jsdomError', e => errors.push('jsdomError: ' + (e.message || e)));
vc.on('error', e => errors.push('console.error: ' + e));

const dom = new JSDOM(html, {
  runScripts: 'dangerously',
  pretendToBeVisual: true,
  virtualConsole: vc,
  url: 'file:///dev-test-checklist.html',
});

const articles = dom.window.document.querySelectorAll('article.test');
const sections = dom.window.document.querySelectorAll('section.test-section');
const progressTotal = dom.window.document.getElementById('ptotal')?.textContent;
const filtersAll = dom.window.document.getElementById('fall')?.textContent;
const errorBanner = dom.window.document.getElementById('js-error');
const warnBanner = dom.window.document.getElementById('js-warn');

console.log('Sections rendered:', sections.length);
console.log('Test articles rendered:', articles.length);
console.log('Progress total text:', progressTotal);
console.log('Filter ALL count:', filtersAll);
console.log('Error banner visible?:', errorBanner?.style.display !== 'none' ? `YES: ${errorBanner.textContent}` : 'no');
console.log('Warn banner visible?: ', warnBanner?.style.display !== 'none' ? `YES: ${warnBanner.textContent}` : 'no');
console.log('Errors during run:', errors.length);
errors.forEach(e => console.log('  -', e));
console.log('--- per-section ---');
sections.forEach(sec => {
  const id = sec.dataset.section;
  const count = sec.querySelectorAll('article.test').length;
  console.log(`  ${id}: ${count} tests`);
});

// Sanity check: click a verdict button and confirm state changes
const firstArticle = articles[0];
const passBtn = firstArticle?.querySelector('[data-status="pass"]');
passBtn?.click();
console.log('After Pass click:');
console.log('  Article data-status:', firstArticle?.dataset.status);
console.log('  Progress total now:', dom.window.document.getElementById('ptotal')?.textContent);
console.log('  Pass pill text:', dom.window.document.getElementById('ppass')?.textContent);
EOF
node sim2.js
